insert into constitutional_batch values ($constitutional_63dc1420384552ec${"version":1,"checked_at":"2026-10-24T21:27:58.671975+00:00","new_modules":12,"updated_modules":3,"new_module_exercises":240,"rebalanced_existing_exercises":11,"global_catalog_insertions":0,"new_cases":30,"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"},{"title":"Edital PCPI Delegado — matriz constitucional cadastrada","url":"https://conhecimento.fgv.br/sites/default/files/concursos/edital_delegado.22.12_0.pdf","sha256":"a2f1676ecf38e22c2faef198420a071031b324831f4b488bdd276999a0725964","checked_at":"2026-10-24T20:54:30.639180+00:00"},{"title":"Lei 9.507/1997 — habeas data","url":"https://www.planalto.gov.br/ccivil_03/Leis/L9507.htm","sha256":"40a296f0fd3180b5a7d550e53b1f12b81f480c2ad018c5919e5be692d1a2a6d0","checked_at":"2026-10-24T20:54:30.185012+00:00"},{"title":"Lei 13.300/2016 — mandado de injunção","url":"https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm","sha256":"9492a18c98cca6062aff17c9ae9dc32125d9431a1a3e2d0cfdca234815fa39e2","checked_at":"2026-10-24T20:54:30.132001+00:00"},{"title":"Lei 12.016/2009 — mandado de segurança","url":"https://www.planalto.gov.br/ccivil_03/_Ato2007-2010/2009/Lei/L12016.htm","sha256":"e5e2c723ffd948ac102f7116c1f7c03fd86133b13a11e16c6ca09f3212259c6f","checked_at":"2026-10-24T20:54:29.930924+00:00"},{"title":"STF — Súmula Vinculante 25 e precedentes representativos","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","sha256":"bc86006e17122d1adbcb84afabff011071c4d7aa66f1fdfb642aa303fefe8861","checked_at":"2026-10-24T20:54:31.843369+00:00"}],"syllabus":{"topic":{"id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","block_name":"Histórico 2026","created_at":"2026-09-28T03:22:06.477804+00:00","discipline":"Direito Constitucional","edition_id":"c0ea9fc5-d65d-4f8c-a936-729f8824a072","topic_text":"DIREITO CONSTITUCIONAL (Edital nº 01/2025 PC-PI (FGV), Anexo I): 1. Teoria da Constituição. 1.1. Conceito, Objeto e Classificações das Constituições. 1.2. Poder Constituinte: Titularidade, espécies (originário, derivado, decorrente, difuso), características e limites do poder constituinte originário. 1.3. Mutação Constitucional e Reforma Constitucional: Emendas e Revisão. 1.4. Supremacia da Constituição e o Bloco de Constitucionalidade. 1.5. Normas Constitucionais: Classificação quanto à eficácia e aplicabilidade (normas de eficácia plena, contida e limitada). 2. Controle de Constitucionalidade. 2.1. Conceito e Histórico. 2.2. Sistemas de Controle de Constitucionalidade: Difuso e Concentrado. 2.3. Ação Direta de Inconstitucionalidade (ADI). 2.4. Ação Declaratória de Constitucionalidade (ADC). 2.5. Arguição de Descumprimento de Preceito Fundamental (ADPF). 2.6. Ação Direta de Inconstitucionalidade por Omissão (ADO). 2.7. Recurso Extraordinário. 2.8. Efeitos das decisões em controle de constitucionalidade. 3. Direitos e Garantias Fundamentais. 3.1. Direitos e Deveres Individuais e Coletivos (art. 5º da CF). 3.2. Direitos Sociais (arts. 6º a 11 da CF). 3.3. Nacionalidade (arts. 12 e 13 da CF). 3.4. Direitos Políticos (arts. 14 a 16 da CF). 3.5. Partidos Políticos (art. 17 da CF). 4. Organização do Estado. 4.1. Organização Político-Administrativa da República Federativa do Brasil (arts. 18 e 19 da CF). 4.2. Repartição de Competências. 4.3. Intervenção Federal (arts. 34 a 36 da CF). 4.4. Administração Pública (arts. 37 a 41 da CF). 5. Organização dos Poderes. 5.1. Poder Legislativo (arts. 44 a 70 da CF). 5.2. Poder Executivo (arts. 76 a 91 da CF). 5.3. Poder Judiciário (arts. 92 a 126 da CF). 5.4. Funções Essenciais à Justiça (arts. 127 a 135 da CF). 6. Defesa do Estado e das Instituições Democráticas. 6.1. Estado de Defesa (arts. 136 e 137 da CF). 6.2. Estado de Sítio (arts. 138 e 139 da CF). 6.3. Forças Armadas (arts. 142 e 143 da CF). 7. Segurança Pública. 7.1. Disposições Gerais (art. 144 da CF). 7.2. Órgãos de Segurança Pública. 7.3. Atribuições da Polícia Civil. 8. Ordem Social. 8.1. Base e Objetivos da Ordem Social. 8.2. Seguridade Social (arts. 194 a 204 da CF). 8.3. Educação, Cultura e Desporto (arts. 205 a 217 da CF). 8.4. Meio Ambiente (art. 225 da CF). 8.5. Família, Criança, Adolescente, Jovem e Idoso (arts. 226 a 230 da CF). 9. Constituição do Estado do Piauí. 9.1. Princípios Fundamentais do Estado do Piauí. 9.2. Direitos e Garantias Fundamentais no âmbito estadual. 9.3. Organização dos Poderes Estaduais. 9.4. Administração Pública Estadual. 9.5. Segurança Pública Estadual.","topic_order":2,"content_status":"current"},"edition":{"id":"c0ea9fc5-d65d-4f8c-a936-729f8824a072","status":"active","role_name":"Delegado de Polícia Civil","source_id":"6d246b75-f48d-5433-804e-8c2999e120bb","created_at":"2026-09-28T03:22:03.801841+00:00","exam_board":"FGV","contest_name":"Polícia Civil do Piauí","contest_year":2026},"source":{"id":"6d246b75-f48d-5433-804e-8c2999e120bb","url":"https://conhecimento.fgv.br/sites/default/files/concursos/edital_delegado.22.12_0.pdf","notes":"Conferência individual em 17/10/2026: itens 2 e 4, página 3, e chaves E/D do Tipo 1, página 1; programa na página 41 do edital retificado em 01/10/2026. O cabeçalho do gabarito informa 25/01/2025, inconsistente com a edição e o catálogo; a conferência usa identidade do cargo/tipo e itens, sem certificar essa data como correta. SHA-256 a2f1676ecf38e22c2faef198420a071031b324831f4b488bdd276999a0725964","title":"Edital nº 01/2025 PCPI — Delegado — retificado em 01/10/2026","issuer":"FGV / Polícia Civil do Piauí","status":"vigente","checked_at":"2026-10-17T21:12:37.27693+00:00","is_official":true,"source_type":"edital","published_on":null}},"rows":[{"kind":"new","material":{"id":"577118dd-3d0c-56ad-a473-9f3541bb1ade","slug":"constitucional-direitos-fundamentais-teoria-geral","discipline":"Direito Constitucional","topic_label":"Teoria geral dos direitos fundamentais","sort_order":10,"title":"Direitos fundamentais: teoria, eficácia e tratados","summary":"Leitura orientada de direitos fundamentais: teoria, eficácia e tratados. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Direito, garantia e aplicação\n\nUm direito protege uma posição jurídica, como a liberdade de locomoção. Uma garantia oferece instrumentos de proteção: o habeas corpus, por exemplo, enfrenta ameaça ou restrição ilegal à locomoção. A distinção ajuda a escolher o instrumento, sem separar artificialmente sua finalidade protetiva.\n\nO art. 5º, § 1º, determina aplicação imediata das normas definidoras de direitos e garantias fundamentais. Isso não elimina toda necessidade de regulamentação: o próprio texto prevê mandado de injunção quando falta norma que torne viável determinado exercício.\n\n| Categoria didática | Como analisar |\n| --- | --- |\n| Eficácia plena | A norma permite produzir seus efeitos essenciais sem integração legislativa |\n| Eficácia contida | O exercício existe desde logo, mas admite restrições constitucionalmente autorizadas |\n| Eficácia limitada | A concretização de certos efeitos depende de integração normativa; isso não significa ausência de força jurídica |\n\nO art. 5º, XIII, permite estudar liberdade profissional e qualificações legais. Não classifique qualquer restrição como legítima só porque consta de uma lei: conteúdo, finalidade e compatibilidade constitucional continuam sujeitos a controle.\n\n## Tratados de direitos humanos\n\nO art. 5º, § 3º, exige aprovação **em cada Casa do Congresso, em dois turnos, por três quintos dos respectivos membros** para equivalência a emenda constitucional. Aprovação apenas no Senado, ou por maioria simples, não satisfaz esse procedimento.\n\nPara tratados de direitos humanos incorporados sem esse rito, a jurisprudência do STF reconhece posição supralegal, abaixo da Constituição e acima da legislação ordinária. A página oficial da Súmula Vinculante 25 apresenta os precedentes pertinentes, inclusive o RE 466.343. Não transforme essa orientação em afirmação de que todo tratado, de qualquer matéria, tem o mesmo nível.\n\nO § 2º admite direitos decorrentes do regime, dos princípios e dos tratados; o catálogo constitucional não deve ser tratado como uma lista materialmente fechada. O § 4º prevê submissão do Brasil à jurisdição do Tribunal Penal Internacional a cuja criação tenha manifestado adesão.\n\n## Características sem generalizações\n\nDimensões de direitos são uma organização histórica e didática, não etapas que apagam as anteriores. A proteção das liberdades convive com direitos sociais e interesses coletivos. Também não use “todo direito é absoluto” ou “qualquer direito pode ser restringido livremente”: a solução depende da norma, de suas garantias e dos limites constitucionais.\n\nNa dimensão subjetiva, investigue a posição que a pessoa pode exigir; na objetiva, a influência dos direitos sobre instituições e interpretação do ordenamento. Eficácia perante o Estado e repercussões nas relações privadas são problemas distintos; o resultado concreto exige identificar o direito e a relação envolvidos.\n\nLeia os dispositivos na Constituição compilada e os precedentes na página oficial da Súmula Vinculante 25. Para instrumentos específicos, continue em [Remédios constitucionais](/dashboard/library/constitucional-remedios-constitucionais).\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"STF — Súmula Vinculante 25 e precedentes representativos","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Uma lei ainda precisa disciplinar certos aspectos de um direito. Isso não permite concluir, por si só, que a norma constitucional não tenha nenhuma força jurídica antes da regulamentação.","a":true,"why":"Aplicação imediata e necessidade de integração para determinados efeitos não são conceitos incompatíveis. A norma constitucional continua a orientar e limitar a atuação estatal. Base: Art. 5º, § 1º."},{"q":"Como as normas de direitos fundamentais têm aplicação imediata, a Constituição não admite que uma omissão normativa inviabilize o exercício de direito constitucional.","a":false,"why":"O próprio mandado de injunção enfrenta essa omissão. É errado transformar a aplicação imediata em afirmação de que toda regulamentação seria desnecessária. Base: Art. 5º, § 1º e LXXI."},{"q":"Ao estudar eficácia contida, a estudante pode analisar liberdade profissional e qualificações legais sem afirmar que qualquer restrição criada pelo legislador seja constitucional.","a":true,"why":"A liberdade existe com a ressalva constitucional às qualificações legais. A compatibilidade e a finalidade da restrição continuam sujeitas a exame. Base: Art. 5º, XIII."},{"q":"Para tornar um tratado de direitos humanos equivalente a emenda, basta aprovação por três quintos dos senadores em duas votações.","a":false,"why":"O rito exige cada Casa do Congresso, dois turnos e três quintos dos respectivos membros. Cumprir apenas a etapa do Senado não satisfaz a Constituição. Base: Art. 5º, §§ 2º e 3º."},{"q":"Um tratado aprovado em dois turnos na Câmara e no Senado, por três quintos dos respectivos membros, preenche o requisito de votação do § 3º, se for tratado de direitos humanos.","a":true,"why":"A natureza da matéria e o procedimento são cumulativos. A equivalência constitucional não decorre apenas de chamar o documento de tratado internacional. Base: Art. 5º, § 3º."},{"q":"A orientação do STF coloca os tratados de direitos humanos incorporados sem o rito do § 3º acima da própria Constituição.","a":false,"why":"A posição supralegal referida nos precedentes está abaixo da Constituição e acima da legislação ordinária. Supralegal não significa supraconstitucional. Base: Súmula Vinculante 25 — precedentes."},{"q":"Na análise de conflito entre lei ordinária e tratado de direitos humanos supralegal, não basta tratar os dois como normas necessariamente do mesmo nível.","a":true,"why":"A posição diferenciada do tratado pode paralisar a eficácia da legislação incompatível. A análise exige identificar a espécie de tratado e sua incorporação. Base: Súmula Vinculante 25 — precedentes."},{"q":"Todo tratado comercial aprovado pelo Congresso é equivalente a emenda constitucional por força do § 3º.","a":false,"why":"O dispositivo se refere a tratados e convenções internacionais sobre direitos humanos e exige rito qualificado. A afirmação amplia indevidamente matéria e procedimento. Base: Art. 5º, § 3º."},{"q":"A ausência de um direito em uma enumeração expressa não basta para descartar a proteção decorrente do regime, dos princípios ou dos tratados a que o Brasil se vincule.","a":true,"why":"O § 2º abre o catálogo material a essas fontes. Isso exige fundamento jurídico, não a simples preferência pessoal de quem interpreta. Base: Art. 5º, § 2º."},{"q":"O texto constitucional determina submissão automática do Brasil a qualquer tribunal internacional criado por outro país.","a":false,"why":"O § 4º trata do Tribunal Penal Internacional a cuja criação o Brasil tenha manifestado adesão. Não estabelece submissão genérica a qualquer corte estrangeira. Base: Art. 5º, § 4º."},{"q":"Ao analisar emenda sobre direito individual, o candidato deve examinar se ela tende a abolir a garantia protegida, e não apenas verificar se houve qualquer mudança de redação.","a":true,"why":"O limite material não torna todo ajuste textual automaticamente proibido. O efeito da proposta sobre a proteção constitucional é relevante. Base: Art. 60, § 4º, IV."},{"q":"Uma proposta que obtém quórum constitucional pode ignorar as limitações materiais porque o número de votos supre qualquer conteúdo.","a":false,"why":"O cumprimento do procedimento não elimina cláusulas pétreas. Há limites materiais que permanecem mesmo com apoio parlamentar suficiente. Base: Art. 60, § 4º."},{"q":"Distinguir direito de locomoção e habeas corpus ajuda a separar o bem protegido do instrumento constitucional de proteção.","a":true,"why":"O habeas corpus é garantia voltada à locomoção ameaçada ou restringida nas condições constitucionais. Não é sinônimo do próprio direito em todas as suas manifestações. Base: Art. 5º, LXVIII."},{"q":"Classificar uma norma como de eficácia limitada equivale a afirmar que ela pode ser livremente contrariada até existir lei.","a":false,"why":"A dependência de integração para certos efeitos não elimina sua força vinculante. Omissões e violações continuam a exigir análise constitucional. Base: Art. 5º, XXXV e LXXI."},{"q":"As categorias de eficácia ajudam a investigar como uma norma produz efeitos, mas não autorizam ignorar a redação e as condições do dispositivo concreto.","a":true,"why":"Uma classificação didática não substitui o texto constitucional. É preciso identificar o efeito discutido e a eventual integração necessária. Base: Art. 5º, § 1º."},{"q":"A expressão direitos fundamentais permite presumir que toda liberdade é ilimitada em qualquer conflito com outros direitos.","a":false,"why":"A Constituição combina proteções e condições específicas. Não se resolve o conflito com a fórmula de que qualquer direito prevalece sempre e sem exame. Base: Art. 5º, caput e IX."},{"q":"Um esquema que organize direitos em dimensões históricas não deve ensinar que o surgimento de direitos sociais extinguiu as liberdades anteriormente protegidas.","a":true,"why":"A organização em dimensões é didática e cumulativa, não mecanismo de revogação. Liberdades e direitos sociais convivem na Constituição. Base: Art. 5º, § 2º."},{"q":"A previsão de qualificações profissionais significa que toda pessoa deve esperar uma lei de cada profissão para exercer qualquer atividade laboral.","a":false,"why":"O texto garante livre exercício, atendidas as qualificações que a lei estabelecer. Não converte toda atividade em profissão dependente de autorização legislativa específica. Base: Art. 5º, XIII."},{"q":"Ao avaliar um caso, identificar o direito, seu titular e a relação jurídica é mais adequado que concluir que todas as proteções têm idêntico alcance para qualquer pessoa ou entidade.","a":true,"why":"A incidência concreta exige examinar compatibilidade e âmbito da garantia. Uma pessoa jurídica, por exemplo, não exerce direitos inerentes à pessoa física de maneira indistinta. Base: Art. 5º, §§ 1º e 2º."},{"q":"Uma votação única em cada Casa, ainda que unânime, atende ao número de turnos expressamente exigido para a equivalência a emenda.","a":false,"why":"O § 3º exige dois turnos em cada Casa. A intensidade do apoio em uma votação não substitui o requisito procedimental omitido. Base: Art. 5º, § 3º."}],"flashcards":[{"f":"Qual é o rito do art. 5º, § 3º?","b":"Cada Casa do Congresso, dois turnos, três quintos dos respectivos membros, em tratado de direitos humanos."},{"f":"Supralegal significa acima da Constituição?","b":"Não. A posição referida nos precedentes do STF fica abaixo da Constituição e acima da legislação ordinária."},{"f":"Aplicação imediata elimina toda regulamentação?","b":"Não. Alguns efeitos podem exigir integração, sem que a norma constitucional perca força jurídica."},{"f":"Dimensões de direitos substituem as anteriores?","b":"Não. A classificação histórica não elimina proteções anteriores."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-direitos-fundamentais-teoria-geral","subject":"Direito Constitucional","topic_label":"Teoria geral dos direitos fundamentais","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"},{"url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","sha256":"bc86006e17122d1adbcb84afabff011071c4d7aa66f1fdfb642aa303fefe8861","checked_at":"2026-10-24T20:54:31.843369+00:00"}],"items":[{"q":"Uma lei ainda precisa disciplinar certos aspectos de um direito. Isso não permite concluir, por si só, que a norma constitucional não tenha nenhuma força jurídica antes da regulamentação.","a":true,"why":"Aplicação imediata e necessidade de integração para determinados efeitos não são conceitos incompatíveis. A norma constitucional continua a orientar e limitar a atuação estatal. Base: Art. 5º, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 1º","origin":"authored_current_official_source"},{"q":"Como as normas de direitos fundamentais têm aplicação imediata, a Constituição não admite que uma omissão normativa inviabilize o exercício de direito constitucional.","a":false,"why":"O próprio mandado de injunção enfrenta essa omissão. É errado transformar a aplicação imediata em afirmação de que toda regulamentação seria desnecessária. Base: Art. 5º, § 1º e LXXI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 1º e LXXI","origin":"authored_current_official_source"},{"q":"Ao estudar eficácia contida, a estudante pode analisar liberdade profissional e qualificações legais sem afirmar que qualquer restrição criada pelo legislador seja constitucional.","a":true,"why":"A liberdade existe com a ressalva constitucional às qualificações legais. A compatibilidade e a finalidade da restrição continuam sujeitas a exame. Base: Art. 5º, XIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XIII","origin":"authored_current_official_source"},{"q":"Para tornar um tratado de direitos humanos equivalente a emenda, basta aprovação por três quintos dos senadores em duas votações.","a":false,"why":"O rito exige cada Casa do Congresso, dois turnos e três quintos dos respectivos membros. Cumprir apenas a etapa do Senado não satisfaz a Constituição. Base: Art. 5º, §§ 2º e 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, §§ 2º e 3º","origin":"authored_current_official_source"},{"q":"Um tratado aprovado em dois turnos na Câmara e no Senado, por três quintos dos respectivos membros, preenche o requisito de votação do § 3º, se for tratado de direitos humanos.","a":true,"why":"A natureza da matéria e o procedimento são cumulativos. A equivalência constitucional não decorre apenas de chamar o documento de tratado internacional. Base: Art. 5º, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 3º","origin":"authored_current_official_source"},{"q":"A orientação do STF coloca os tratados de direitos humanos incorporados sem o rito do § 3º acima da própria Constituição.","a":false,"why":"A posição supralegal referida nos precedentes está abaixo da Constituição e acima da legislação ordinária. Supralegal não significa supraconstitucional. Base: Súmula Vinculante 25 — precedentes.","source_url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","article":"Súmula Vinculante 25 — precedentes","origin":"authored_current_official_source"},{"q":"Na análise de conflito entre lei ordinária e tratado de direitos humanos supralegal, não basta tratar os dois como normas necessariamente do mesmo nível.","a":true,"why":"A posição diferenciada do tratado pode paralisar a eficácia da legislação incompatível. A análise exige identificar a espécie de tratado e sua incorporação. Base: Súmula Vinculante 25 — precedentes.","source_url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","article":"Súmula Vinculante 25 — precedentes","origin":"authored_current_official_source"},{"q":"Todo tratado comercial aprovado pelo Congresso é equivalente a emenda constitucional por força do § 3º.","a":false,"why":"O dispositivo se refere a tratados e convenções internacionais sobre direitos humanos e exige rito qualificado. A afirmação amplia indevidamente matéria e procedimento. Base: Art. 5º, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 3º","origin":"authored_current_official_source"},{"q":"A ausência de um direito em uma enumeração expressa não basta para descartar a proteção decorrente do regime, dos princípios ou dos tratados a que o Brasil se vincule.","a":true,"why":"O § 2º abre o catálogo material a essas fontes. Isso exige fundamento jurídico, não a simples preferência pessoal de quem interpreta. Base: Art. 5º, § 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 2º","origin":"authored_current_official_source"},{"q":"O texto constitucional determina submissão automática do Brasil a qualquer tribunal internacional criado por outro país.","a":false,"why":"O § 4º trata do Tribunal Penal Internacional a cuja criação o Brasil tenha manifestado adesão. Não estabelece submissão genérica a qualquer corte estrangeira. Base: Art. 5º, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 4º","origin":"authored_current_official_source"},{"q":"Ao analisar emenda sobre direito individual, o candidato deve examinar se ela tende a abolir a garantia protegida, e não apenas verificar se houve qualquer mudança de redação.","a":true,"why":"O limite material não torna todo ajuste textual automaticamente proibido. O efeito da proposta sobre a proteção constitucional é relevante. Base: Art. 60, § 4º, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 60, § 4º, IV","origin":"authored_current_official_source"},{"q":"Uma proposta que obtém quórum constitucional pode ignorar as limitações materiais porque o número de votos supre qualquer conteúdo.","a":false,"why":"O cumprimento do procedimento não elimina cláusulas pétreas. Há limites materiais que permanecem mesmo com apoio parlamentar suficiente. Base: Art. 60, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 60, § 4º","origin":"authored_current_official_source"},{"q":"Distinguir direito de locomoção e habeas corpus ajuda a separar o bem protegido do instrumento constitucional de proteção.","a":true,"why":"O habeas corpus é garantia voltada à locomoção ameaçada ou restringida nas condições constitucionais. Não é sinônimo do próprio direito em todas as suas manifestações. Base: Art. 5º, LXVIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXVIII","origin":"authored_current_official_source"},{"q":"Classificar uma norma como de eficácia limitada equivale a afirmar que ela pode ser livremente contrariada até existir lei.","a":false,"why":"A dependência de integração para certos efeitos não elimina sua força vinculante. Omissões e violações continuam a exigir análise constitucional. Base: Art. 5º, XXXV e LXXI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXXV e LXXI","origin":"authored_current_official_source"},{"q":"As categorias de eficácia ajudam a investigar como uma norma produz efeitos, mas não autorizam ignorar a redação e as condições do dispositivo concreto.","a":true,"why":"Uma classificação didática não substitui o texto constitucional. É preciso identificar o efeito discutido e a eventual integração necessária. Base: Art. 5º, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 1º","origin":"authored_current_official_source"},{"q":"A expressão direitos fundamentais permite presumir que toda liberdade é ilimitada em qualquer conflito com outros direitos.","a":false,"why":"A Constituição combina proteções e condições específicas. Não se resolve o conflito com a fórmula de que qualquer direito prevalece sempre e sem exame. Base: Art. 5º, caput e IX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput e IX","origin":"authored_current_official_source"},{"q":"Um esquema que organize direitos em dimensões históricas não deve ensinar que o surgimento de direitos sociais extinguiu as liberdades anteriormente protegidas.","a":true,"why":"A organização em dimensões é didática e cumulativa, não mecanismo de revogação. Liberdades e direitos sociais convivem na Constituição. Base: Art. 5º, § 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 2º","origin":"authored_current_official_source"},{"q":"A previsão de qualificações profissionais significa que toda pessoa deve esperar uma lei de cada profissão para exercer qualquer atividade laboral.","a":false,"why":"O texto garante livre exercício, atendidas as qualificações que a lei estabelecer. Não converte toda atividade em profissão dependente de autorização legislativa específica. Base: Art. 5º, XIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XIII","origin":"authored_current_official_source"},{"q":"Ao avaliar um caso, identificar o direito, seu titular e a relação jurídica é mais adequado que concluir que todas as proteções têm idêntico alcance para qualquer pessoa ou entidade.","a":true,"why":"A incidência concreta exige examinar compatibilidade e âmbito da garantia. Uma pessoa jurídica, por exemplo, não exerce direitos inerentes à pessoa física de maneira indistinta. Base: Art. 5º, §§ 1º e 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, §§ 1º e 2º","origin":"authored_current_official_source"},{"q":"Uma votação única em cada Casa, ainda que unânime, atende ao número de turnos expressamente exigido para a equivalência a emenda.","a":false,"why":"O § 3º exige dois turnos em cada Casa. A intensidade do apoio em uma votação não substitui o requisito procedimental omitido. Base: Art. 5º, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, § 3º","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"},{"title":"STF — Súmula Vinculante 25 e precedentes representativos","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","sha256":"bc86006e17122d1adbcb84afabff011071c4d7aa66f1fdfb642aa303fefe8861"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"7d0b6e65-08cd-585a-a1a5-66a42b3353fd","material_slug":"constitucional-direitos-fundamentais-teoria-geral","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"11d4352074afb56cb374dd1decada1b5f0764753898b781a67caaf88f2847d13","content":{"cases":[{"id":"rito","title":"Um tratado aprovado só no Senado","scenario":"Um tratado de direitos humanos recebe três quintos dos votos no Senado em dois turnos. Não houve votação na Câmara.","question":"Já existe equivalência a emenda pelo rito do art. 5º, § 3º?","steps":["Identifique a matéria: direitos humanos.","Confira separadamente as duas Casas, os dois turnos e o quórum.","Não substitua uma etapa ausente por votação qualificada em outra Casa."],"conclusion":"Não. A etapa da Câmara é parte do procedimento constitucional.","pitfall":"Conferir o quórum e esquecer o órgão e os turnos.","variation":{"scenario":"O tratado completa duas votações também na Câmara com três quintos dos membros.","answer":"A condição de aprovação do § 3º está preenchida, observados os demais atos necessários à incorporação."},"articles":["Art. 5º, § 3º"]},{"id":"omissao","title":"O direito existe, mas falta norma","scenario":"Uma pessoa aponta direito constitucional cujo exercício está inviabilizado por falta de regulamentação. A resposta administrativa diz que a Constituição não produz efeito algum antes da lei.","question":"A resposta pode tratar a norma constitucional como juridicamente inexistente?","steps":["Separe força jurídica da norma e integração necessária a certos efeitos.","Considere o comando de aplicação imediata.","Examine a hipótese constitucional e a lei de mandado de injunção."],"conclusion":"Não. A dependência de regulamentação não transforma a norma em texto sem força jurídica.","pitfall":"Confundir eficácia limitada com liberdade para contrariar a Constituição.","variation":{"scenario":"A controvérsia é sobre ato que viola direito já exercitável, e não omissão normativa.","answer":"O problema muda: deve-se avaliar o instrumento adequado ao ato e ao direito, sem escolher injunção apenas por preferência."},"articles":["Art. 5º, § 1º","Art. 5º, LXXI"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"STF — Súmula Vinculante 25 e precedentes representativos","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"46820d63-3fe9-5beb-b7af-e66fa402d5d8","slug":"constitucional-vida-igualdade","discipline":"Direito Constitucional","topic_label":"Vida e igualdade","sort_order":11,"title":"Vida e igualdade: leitura constitucional aplicada","summary":"Leitura orientada de vida e igualdade: leitura constitucional aplicada. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Vida e igualdade no texto constitucional\n\nO caput do art. 5º protege vida, liberdade, igualdade, segurança e propriedade. O inciso I estabelece igualdade de direitos e obrigações entre homens e mulheres nos termos da Constituição. O inciso III proíbe tortura e tratamento desumano ou degradante.\n\nA vedação de pena de morte tem a exceção expressa de guerra declarada, nos termos do art. 84, XIX. Não converta essa exceção constitucional em autorização para outras hipóteses, nem use um resumo de concurso para resolver isoladamente questões médicas ou penais complexas.\n\n## Igualdade não é um teste apenas de aparência\n\nO raciocínio formal pergunta se a regra discrimina sem fundamento. O raciocínio material considera diferenças relevantes e medidas de proteção ou inclusão. A Constituição prevê, por exemplo, reserva legal de percentual de cargos e empregos públicos para pessoas com deficiência e critérios de admissão (art. 37, VIII).\n\nDuas cautelas são necessárias: uma diferenciação não é inválida apenas por existir; também não é válida apenas por ser chamada de ação afirmativa. Examine finalidade, base normativa, adequação e o contexto. Percentuais, destinatários e regras de cotas dependem da legislação vigente do concurso; este módulo não reaproveita tabelas antigas de percentuais.\n\n## Concurso público: leia o requisito concreto\n\nDistingua reserva de vagas, adaptação de provas e requisitos de ingresso. A reserva constitucional não elimina os demais requisitos legítimos do cargo. Da mesma forma, a palavra “igualdade” não autoriza negar automaticamente toda adaptação de acessibilidade.\n\n**Método:** identifique o grupo de comparação; localize a diferença de tratamento; confira a base constitucional e legal; avalie a relação com o objetivo protegido. Não invente idade máxima, limite físico ou percentual que o edital e a lei atual não estabelecem.\n\n## Continue sem repetir conteúdos\n\nQuestões de intimidade e tratamento de dados estão em [Privacidade e dados pessoais](/dashboard/library/constitucional-privacidade-dados). As garantias de defesa e controle de atos estão em [Segurança jurídica e processo](/dashboard/library/constitucional-seguranca-juridica-processo). Aqui o foco é compreender a proteção constitucional da vida e da igualdade.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Uma comissão distingue igualdade perante a lei e análise das diferenças relevantes entre pessoas. A distinção não autoriza presumir válida toda diferenciação estatal.","a":true,"why":"A análise deve verificar fundamento, finalidade e compatibilidade constitucional. Dar um nome inclusivo à medida não dispensa examinar seus critérios. Base: Art. 5º, caput e I."},{"q":"A Constituição permite pena de morte por qualquer crime considerado muito grave pelo legislador ordinário.","a":false,"why":"A exceção expressa é guerra declarada nos termos do art. 84, XIX. Gravidade abstrata ou clamor público não criam outra exceção constitucional. Base: Art. 5º, XLVII, a."},{"q":"Invocar eficiência de uma investigação não torna constitucional submeter uma pessoa a tortura ou tratamento degradante.","a":true,"why":"O inciso III proíbe essas práticas. A finalidade administrativa ou investigativa não elimina a garantia. Base: Art. 5º, III."},{"q":"A reserva constitucional de cargos a pessoas com deficiência é incompatível, por definição, com a igualdade, porque distingue candidatos.","a":false,"why":"A própria Constituição prevê reserva percentual por lei e critérios de admissão. Igualdade não equivale a proibição de toda medida diferenciada. Base: Art. 37, VIII."},{"q":"Um edital de concurso deve ser confrontado com a lei atual sobre reserva de vagas, em vez de receber automaticamente um percentual copiado de apostila antiga.","a":true,"why":"O dispositivo constitucional remete a percentual e critérios legais. A existência da garantia não fixa, por si só, o mesmo número para todo concurso e regime. Base: Art. 37, VIII."},{"q":"A igualdade entre homens e mulheres torna desnecessário observar as condições e proteções específicas que a própria Constituição estabelece.","a":false,"why":"A igualdade é assegurada nos termos constitucionais. Não se deve apagar outros dispositivos constitucionais sob uma leitura isolada do inciso I. Base: Art. 5º, I."},{"q":"Se duas regras usam palavras idênticas, ainda pode ser necessário investigar seus efeitos e a situação dos grupos atingidos para avaliar igualdade.","a":true,"why":"A aparência textual não encerra toda análise de tratamento discriminatório. É preciso compreender a relação entre critérios, finalidade e consequências relevantes. Base: Art. 5º, caput."},{"q":"Toda diferenciação que beneficie determinado grupo dispensa fundamento jurídico por se declarar uma ação afirmativa.","a":false,"why":"A finalidade declarada não supre base normativa nem exame de compatibilidade. O rótulo não concede validade automática à política. Base: Art. 5º, caput."},{"q":"Reserva de vagas e adaptação de acessibilidade em prova são providências distintas, embora possam atuar juntas na proteção de pessoas com deficiência.","a":true,"why":"Uma organiza a disputa de vagas; a outra enfrenta barreiras de participação. Não se devem tratar as duas como uma única regra numérica. Base: Art. 37, VIII."},{"q":"Estar abrangido por reserva de vagas elimina, automaticamente, todos os requisitos legítimos para o exercício do cargo.","a":false,"why":"A reserva não afasta indistintamente requisitos constitucionais e legais pertinentes. É necessário distinguir critério de acesso e requisito funcional válido. Base: Art. 37, I e VIII."},{"q":"Um requisito de ingresso deve ser analisado conforme seu fundamento e sua relação com o cargo, sem concluir que qualquer distinção é válida por constar do edital.","a":true,"why":"O edital não fica acima da Constituição e da lei. A inserção formal de uma exigência não elimina controle de sua legitimidade. Base: Art. 5º, caput e I."},{"q":"A proteção constitucional da vida significa que a própria Constituição não contempla nenhuma exceção à vedação da pena de morte.","a":false,"why":"O inciso XLVII, a, prevê a exceção de guerra declarada. A leitura deve distinguir proteção da vida e formulação literal dessa regra penal. Base: Art. 5º, caput."},{"q":"A vedação de tratamento desumano ou degradante protege a pessoa mesmo quando ela é suspeita de infração.","a":true,"why":"A condição de suspeito não retira a proteção constitucional. Apuração de responsabilidade deve observar as garantias pertinentes. Base: Art. 5º, III."},{"q":"Toda diferença de renda ou situação social pode ser ignorada obrigatoriamente ao desenhar políticas de proteção, porque a igualdade só admite critérios abstratamente idênticos.","a":false,"why":"A compreensão material da igualdade considera diferenças relevantes. Isso não dispensa base jurídica nem autoriza discriminação arbitrária. Base: Art. 5º, caput."},{"q":"A análise de uma política de inclusão deve identificar quem é comparado, qual tratamento difere e qual finalidade constitucional se pretende alcançar.","a":true,"why":"Esse método evita decidir apenas por palavras de ordem. Os fatos e o fundamento normativo continuam necessários. Base: Art. 5º, caput."},{"q":"O art. 37, VIII, fixa diretamente em seu texto um percentual único de reserva para todos os cargos e empregos do país.","a":false,"why":"O dispositivo atribui à lei a reserva percentual e os critérios. Não contém um número nacional único que dispense a legislação aplicável. Base: Art. 37, VIII."},{"q":"Uma justificativa que trate homens e mulheres como sujeitos de direitos e obrigações deve respeitar a igualdade constitucional, sem presumir incapacidade genérica de um grupo.","a":true,"why":"O inciso I rejeita a desigualdade arbitrária. Regras específicas precisam de fundamento no sistema constitucional e legal. Base: Art. 5º, I."},{"q":"A proibição de tortura só protege quem já tenha sido condenado, não alcançando a fase anterior ao processo.","a":false,"why":"A garantia não depende de condenação prévia. O enunciado cria limitação que o inciso III não estabelece. Base: Art. 5º, III."},{"q":"Uma aula sobre igualdade deve evitar substituir o exame da legislação atual de cotas por um percentual histórico sem indicar sua vigência e âmbito.","a":true,"why":"A regra concreta depende do regime e do período pertinentes. Preservar a precisão temporal evita aplicar automaticamente política já alterada. Base: Art. 5º, caput."},{"q":"Reconhecer uma proteção diferenciada em favor de pessoa vulnerável exige concluir que todos os demais direitos dos outros grupos foram eliminados.","a":false,"why":"Direitos e medidas de proteção devem ser interpretados no conjunto constitucional. Uma medida específica não extingue indiscriminadamente as garantias dos demais. Base: Art. 5º, caput."}],"flashcards":[{"f":"Toda diferenciação viola igualdade?","b":"Não. É preciso examinar fundamento, finalidade e compatibilidade constitucional."},{"f":"Qual é a exceção constitucional à vedação de pena de morte?","b":"Guerra declarada nos termos do art. 84, XIX."},{"f":"Reserva de vagas e acessibilidade são a mesma medida?","b":"Não. Têm funções distintas e podem atuar conjuntamente."},{"f":"A tortura depende de condenação para ser proibida?","b":"Não. A proteção do art. 5º, III, não exige condenação prévia."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-vida-igualdade","subject":"Direito Constitucional","topic_label":"Vida e igualdade","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"Uma comissão distingue igualdade perante a lei e análise das diferenças relevantes entre pessoas. A distinção não autoriza presumir válida toda diferenciação estatal.","a":true,"why":"A análise deve verificar fundamento, finalidade e compatibilidade constitucional. Dar um nome inclusivo à medida não dispensa examinar seus critérios. Base: Art. 5º, caput e I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput e I","origin":"authored_current_official_source"},{"q":"A Constituição permite pena de morte por qualquer crime considerado muito grave pelo legislador ordinário.","a":false,"why":"A exceção expressa é guerra declarada nos termos do art. 84, XIX. Gravidade abstrata ou clamor público não criam outra exceção constitucional. Base: Art. 5º, XLVII, a.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XLVII, a","origin":"authored_current_official_source"},{"q":"Invocar eficiência de uma investigação não torna constitucional submeter uma pessoa a tortura ou tratamento degradante.","a":true,"why":"O inciso III proíbe essas práticas. A finalidade administrativa ou investigativa não elimina a garantia. Base: Art. 5º, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, III","origin":"authored_current_official_source"},{"q":"A reserva constitucional de cargos a pessoas com deficiência é incompatível, por definição, com a igualdade, porque distingue candidatos.","a":false,"why":"A própria Constituição prevê reserva percentual por lei e critérios de admissão. Igualdade não equivale a proibição de toda medida diferenciada. Base: Art. 37, VIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, VIII","origin":"authored_current_official_source"},{"q":"Um edital de concurso deve ser confrontado com a lei atual sobre reserva de vagas, em vez de receber automaticamente um percentual copiado de apostila antiga.","a":true,"why":"O dispositivo constitucional remete a percentual e critérios legais. A existência da garantia não fixa, por si só, o mesmo número para todo concurso e regime. Base: Art. 37, VIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, VIII","origin":"authored_current_official_source"},{"q":"A igualdade entre homens e mulheres torna desnecessário observar as condições e proteções específicas que a própria Constituição estabelece.","a":false,"why":"A igualdade é assegurada nos termos constitucionais. Não se deve apagar outros dispositivos constitucionais sob uma leitura isolada do inciso I. Base: Art. 5º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, I","origin":"authored_current_official_source"},{"q":"Se duas regras usam palavras idênticas, ainda pode ser necessário investigar seus efeitos e a situação dos grupos atingidos para avaliar igualdade.","a":true,"why":"A aparência textual não encerra toda análise de tratamento discriminatório. É preciso compreender a relação entre critérios, finalidade e consequências relevantes. Base: Art. 5º, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput","origin":"authored_current_official_source"},{"q":"Toda diferenciação que beneficie determinado grupo dispensa fundamento jurídico por se declarar uma ação afirmativa.","a":false,"why":"A finalidade declarada não supre base normativa nem exame de compatibilidade. O rótulo não concede validade automática à política. Base: Art. 5º, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput","origin":"authored_current_official_source"},{"q":"Reserva de vagas e adaptação de acessibilidade em prova são providências distintas, embora possam atuar juntas na proteção de pessoas com deficiência.","a":true,"why":"Uma organiza a disputa de vagas; a outra enfrenta barreiras de participação. Não se devem tratar as duas como uma única regra numérica. Base: Art. 37, VIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, VIII","origin":"authored_current_official_source"},{"q":"Estar abrangido por reserva de vagas elimina, automaticamente, todos os requisitos legítimos para o exercício do cargo.","a":false,"why":"A reserva não afasta indistintamente requisitos constitucionais e legais pertinentes. É necessário distinguir critério de acesso e requisito funcional válido. Base: Art. 37, I e VIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, I e VIII","origin":"authored_current_official_source"},{"q":"Um requisito de ingresso deve ser analisado conforme seu fundamento e sua relação com o cargo, sem concluir que qualquer distinção é válida por constar do edital.","a":true,"why":"O edital não fica acima da Constituição e da lei. A inserção formal de uma exigência não elimina controle de sua legitimidade. Base: Art. 5º, caput e I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput e I","origin":"authored_current_official_source"},{"q":"A proteção constitucional da vida significa que a própria Constituição não contempla nenhuma exceção à vedação da pena de morte.","a":false,"why":"O inciso XLVII, a, prevê a exceção de guerra declarada. A leitura deve distinguir proteção da vida e formulação literal dessa regra penal. Base: Art. 5º, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput","origin":"authored_current_official_source"},{"q":"A vedação de tratamento desumano ou degradante protege a pessoa mesmo quando ela é suspeita de infração.","a":true,"why":"A condição de suspeito não retira a proteção constitucional. Apuração de responsabilidade deve observar as garantias pertinentes. Base: Art. 5º, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, III","origin":"authored_current_official_source"},{"q":"Toda diferença de renda ou situação social pode ser ignorada obrigatoriamente ao desenhar políticas de proteção, porque a igualdade só admite critérios abstratamente idênticos.","a":false,"why":"A compreensão material da igualdade considera diferenças relevantes. Isso não dispensa base jurídica nem autoriza discriminação arbitrária. Base: Art. 5º, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput","origin":"authored_current_official_source"},{"q":"A análise de uma política de inclusão deve identificar quem é comparado, qual tratamento difere e qual finalidade constitucional se pretende alcançar.","a":true,"why":"Esse método evita decidir apenas por palavras de ordem. Os fatos e o fundamento normativo continuam necessários. Base: Art. 5º, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput","origin":"authored_current_official_source"},{"q":"O art. 37, VIII, fixa diretamente em seu texto um percentual único de reserva para todos os cargos e empregos do país.","a":false,"why":"O dispositivo atribui à lei a reserva percentual e os critérios. Não contém um número nacional único que dispense a legislação aplicável. Base: Art. 37, VIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, VIII","origin":"authored_current_official_source"},{"q":"Uma justificativa que trate homens e mulheres como sujeitos de direitos e obrigações deve respeitar a igualdade constitucional, sem presumir incapacidade genérica de um grupo.","a":true,"why":"O inciso I rejeita a desigualdade arbitrária. Regras específicas precisam de fundamento no sistema constitucional e legal. Base: Art. 5º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, I","origin":"authored_current_official_source"},{"q":"A proibição de tortura só protege quem já tenha sido condenado, não alcançando a fase anterior ao processo.","a":false,"why":"A garantia não depende de condenação prévia. O enunciado cria limitação que o inciso III não estabelece. Base: Art. 5º, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, III","origin":"authored_current_official_source"},{"q":"Uma aula sobre igualdade deve evitar substituir o exame da legislação atual de cotas por um percentual histórico sem indicar sua vigência e âmbito.","a":true,"why":"A regra concreta depende do regime e do período pertinentes. Preservar a precisão temporal evita aplicar automaticamente política já alterada. Base: Art. 5º, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput","origin":"authored_current_official_source"},{"q":"Reconhecer uma proteção diferenciada em favor de pessoa vulnerável exige concluir que todos os demais direitos dos outros grupos foram eliminados.","a":false,"why":"Direitos e medidas de proteção devem ser interpretados no conjunto constitucional. Uma medida específica não extingue indiscriminadamente as garantias dos demais. Base: Art. 5º, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, caput","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"8d33a1ee-87c7-5181-b8fa-e4d68167174b","material_slug":"constitucional-vida-igualdade","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"d8c35ff1a2173369d60fe87a80a8e94caafc64e7fad7c474d27e09c0d981d800","content":{"cases":[{"id":"reserva","title":"Reserva de vagas não é dispensa de requisitos","scenario":"Um concurso prevê reserva de vagas a pessoas com deficiência. Um participante conclui que o beneficiário pode ignorar qualquer requisito legítimo do cargo.","question":"A existência da reserva produz essa dispensa geral?","steps":["Localize a autorização constitucional de reserva e critérios legais.","Distinga acesso diferenciado e capacidade ou requisito funcional legítimo.","Confira a legislação atual e o edital, sujeitos à Constituição."],"conclusion":"Não. Reserva de vagas e requisitos válidos precisam ser analisados conjuntamente.","pitfall":"Tratar a inclusão como eliminação automática de toda condição de ingresso.","variation":{"scenario":"A barreira discutida é ausência de adaptação de acessibilidade na prova.","answer":"Agora é necessário avaliar a adaptação de participação, que não se confunde com o percentual de vagas reservadas."},"articles":["Art. 37, VIII"]},{"id":"sancao","title":"Gravidade não cria exceção nova","scenario":"Uma proposta de lei ordinária pretende instituir pena de morte para crime considerado extremamente grave, fora de guerra declarada.","question":"A gravidade permite ampliar a exceção constitucional?","steps":["Leia a vedação e sua exceção expressa.","Diferencie opinião sobre gravidade e autorização constitucional.","Considere a posição da lei ordinária diante da Constituição."],"conclusion":"Não. O legislador ordinário não cria livremente nova exceção ao inciso XLVII, a.","pitfall":"Usar um argumento de conveniência para apagar o limite constitucional.","variation":{"scenario":"O enunciado passa a mencionar guerra declarada nos termos constitucionais.","answer":"A exceção expressa deve ser examinada com suas condições; isso não dispensa a legislação e as garantias pertinentes."},"articles":["Art. 5º, XLVII, a"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"72edad0a-53e2-5289-999d-5192b8da78c2","slug":"constitucional-liberdades-constitucionais","discipline":"Direito Constitucional","topic_label":"Liberdades constitucionais","sort_order":12,"title":"Liberdades: expressão, crença, reunião, associação e profissão","summary":"Leitura orientada de liberdades: expressão, crença, reunião, associação e profissão. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Seis perguntas antes de responder\n\n| Liberdade | O que conferir no art. 5º |\n| --- | --- |\n| Ação | Obrigação de fazer ou não fazer depende de lei, conforme o inciso II |\n| Expressão | Manifestação do pensamento é livre, mas o anonimato é vedado; resposta e reparação têm disciplina própria |\n| Crença | Consciência, culto, proteção aos locais de culto e assistência religiosa não significam religião estatal obrigatória |\n| Locomoção | O inciso XV fala em tempo de paz e nos termos da lei; não cria imunidade tributária para bens transportados |\n| Reunião | Pacífica, sem armas, em local aberto ao público, sem frustrar outra anteriormente convocada e com prévio aviso |\n| Associação | Finalidade lícita, vedação de caráter paramilitar e proteção contra interferência estatal indevida |\n\n## Aviso não é autorização\n\nO art. 5º, XVI, dispensa autorização para reunião nas condições constitucionais, mas prevê prévio aviso à autoridade competente. São categorias distintas: não transforme o aviso em licença discricionária, nem apague os demais requisitos.\n\nA liberdade associativa também tem requisitos próprios. A criação de associações independe de autorização, e ninguém pode ser compelido a associar-se ou permanecer associado. Suspender atividades exige decisão judicial; dissolução compulsória exige também trânsito em julgado.\n\n## Crença e dever legal\n\nO art. 5º, VIII, não concede dispensa automática de qualquer obrigação: examine a obrigação legal a todos imposta e a prestação alternativa fixada em lei. O art. 19, I, veda estabelecimento ou subvenção de cultos, embaraço ao funcionamento e relações de dependência ou aliança, ressalvada a colaboração de interesse público na forma da lei.\n\n## Profissão e comunicação\n\nA liberdade profissional admite qualificações previstas em lei, mas isso não autoriza qualquer restrição arbitrária. Expressão intelectual, artística, científica e de comunicação é livre de censura ou licença, conforme o inciso IX. A proteção da expressão não elimina direito de resposta e indenização nas hipóteses constitucionais.\n\nLeia o direito com suas condições. Para violação de locomoção, dados ou direito líquido e certo, a escolha do instrumento deve ser estudada em [Remédios constitucionais](/dashboard/library/constitucional-remedios-constitucionais), sem usar o mesmo remédio para toda liberdade.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Uma reunião pacífica e sem armas em local aberto ao público dispensa autorização, mas ainda deve observar os requisitos constitucionais, inclusive o prévio aviso.","a":true,"why":"Dispensa de autorização não significa ausência de condições. Também não se deve frustrar reunião anteriormente convocada para o mesmo local. Base: Art. 5º, XVI."},{"q":"O prévio aviso previsto para reunião equivale a licença discricionária que a autoridade pode negar sem fundamento.","a":false,"why":"O texto distingue aviso de autorização, que é dispensada nas condições constitucionais. O aviso não pode ser usado para apagar a liberdade garantida. Base: Art. 5º, XVI."},{"q":"Uma associação de finalidade lícita pode ser criada sem autorização estatal, observada a vedação constitucional ao caráter paramilitar.","a":true,"why":"Liberdade associativa e limites expressos convivem. A dispensa de autorização não legitima finalidade ilícita nem organização paramilitar. Base: Art. 5º, XVII e XVIII."},{"q":"Uma autoridade administrativa pode dissolver compulsoriamente associação por decisão própria, desde que apresente relatório detalhado.","a":false,"why":"A dissolução compulsória exige decisão judicial com trânsito em julgado. Fundamentação administrativa não substitui essa reserva. Base: Art. 5º, XIX."},{"q":"Suspender atividades e dissolver compulsoriamente uma associação exigem decisão judicial, mas a Constituição acrescenta trânsito em julgado para a dissolução.","a":true,"why":"A diferença entre as duas medidas é expressa. Não se deve exigir ou dispensar o mesmo marco sem distinguir a providência. Base: Art. 5º, XIX."},{"q":"Depois de ingressar livremente em associação, a pessoa fica constitucionalmente obrigada a permanecer associada por tempo indefinido.","a":false,"why":"Ninguém pode ser compelido a associar-se ou permanecer associado. O ingresso inicial não elimina a garantia de saída. Base: Art. 5º, XX."},{"q":"A proteção da manifestação do pensamento convive com vedação ao anonimato, direito de resposta e reparação nas hipóteses constitucionais.","a":true,"why":"Liberdade de expressão não significa imunidade absoluta a consequências jurídicas. É necessário analisar o caso e as garantias envolvidas. Base: Art. 5º, IV e V."},{"q":"A atividade artística pode ser submetida, como regra geral, a licença prévia de censura apenas por ser dirigida ao público.","a":false,"why":"O inciso IX protege a expressão artística independentemente de censura ou licença. O enunciado inverte a regra constitucional. Base: Art. 5º, IX."},{"q":"A proteção de consciência e crença inclui o livre exercício dos cultos e a proteção legal aos locais de culto e liturgias.","a":true,"why":"O Estado deve observar as garantias constitucionais; laicidade não autoriza, por si só, embaraçar toda prática religiosa. Base: Art. 5º, VI."},{"q":"Laicidade constitucional significa que o poder público está autorizado a impedir genericamente o funcionamento de qualquer culto.","a":false,"why":"O art. 19 veda embaraço ao funcionamento, além das relações e práticas que especifica. Laicidade não é proibição geral de religião. Base: Art. 19, I."},{"q":"A assistência religiosa pode ser assegurada em entidades civis e militares de internação coletiva, nos termos da lei.","a":true,"why":"O texto não limita a garantia a instituições militares. A disciplina legal deve ser considerada no caso concreto. Base: Art. 5º, VII."},{"q":"A alegação de crença religiosa afasta automaticamente qualquer obrigação legal a todos imposta, mesmo com recusa da prestação alternativa fixada em lei.","a":false,"why":"O inciso VIII contém condições e não cria dispensa irrestrita. É preciso examinar obrigação e prestação alternativa. Base: Art. 5º, VIII."},{"q":"Liberdade de locomoção em tempo de paz, nos termos da lei, não significa que transportar bens gere imunidade tributária automática.","a":true,"why":"A liberdade de deslocamento não elimina indistintamente obrigações legais sobre bens. São questões jurídicas distintas. Base: Art. 5º, XV."},{"q":"A liberdade profissional torna necessariamente inválida toda exigência legal de qualificação, sem examinar seu fundamento.","a":false,"why":"O texto admite qualificações profissionais estabelecidas em lei. A legitimidade de uma exigência depende de análise constitucional, não de uma proibição abstrata de toda qualificação. Base: Art. 5º, XIII."},{"q":"A regra de que ninguém é obrigado a fazer ou deixar de fazer algo senão em virtude de lei exige identificar a base jurídica da imposição.","a":true,"why":"Não basta a preferência de um agente para criar dever indistinto ao particular. Também é preciso compreender o alcance da norma aplicável. Base: Art. 5º, II."},{"q":"O acesso à informação e o sigilo da fonte, quando necessário ao exercício profissional, autorizam concluir que qualquer pessoa possa ocultar qualquer ato ilícito sob esse nome.","a":false,"why":"A garantia tem âmbito e finalidade próprios. O enunciado amplia o sigilo da fonte para uma imunidade geral que o texto não estabelece. Base: Art. 5º, XIV."},{"q":"A vedação de interferência estatal no funcionamento associativo impede tratar toda associação privada como órgão subordinado à administração.","a":true,"why":"A liberdade tem proteção própria, observados os limites constitucionais. Não significa ausência de responsabilidade por condutas ilícitas. Base: Art. 5º, XVIII."},{"q":"Basta que a reunião seja sem armas para afastar os requisitos de caráter pacífico e de não frustrar outra anteriormente convocada.","a":false,"why":"Os requisitos são cumulativos. Cumprir apenas um deles não torna irrelevantes as demais condições do inciso XVI. Base: Art. 5º, XVI."},{"q":"Direito de resposta proporcional ao agravo e indenização por dano podem coexistir, conforme a disciplina constitucional.","a":true,"why":"O inciso V usa garantia de resposta além da indenização cabível. Não se deve transformar uma providência em exclusão automática da outra. Base: Art. 5º, V."},{"q":"A Constituição proíbe sem qualquer ressalva toda colaboração de interesse público entre poder público e organizações religiosas.","a":false,"why":"O inciso I ressalva colaboração de interesse público na forma da lei. A ressalva não autoriza, por outro lado, religião oficial ou dependência vedada. Base: Art. 19, I."}],"flashcards":[{"f":"Aviso para reunião é autorização?","b":"Não. A Constituição distingue os dois e exige os demais requisitos da reunião."},{"f":"Dissolver associação e suspender atividade têm o mesmo marco?","b":"Ambas exigem decisão judicial; a dissolução compulsória exige trânsito em julgado."},{"f":"É obrigatório permanecer associado?","b":"Não. O art. 5º, XX, protege contra associação ou permanência compulsória."},{"f":"Crença dispensa automaticamente todo dever legal?","b":"Não. Examine o art. 5º, VIII, e a prestação alternativa fixada em lei."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-liberdades-constitucionais","subject":"Direito Constitucional","topic_label":"Liberdades constitucionais","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"Uma reunião pacífica e sem armas em local aberto ao público dispensa autorização, mas ainda deve observar os requisitos constitucionais, inclusive o prévio aviso.","a":true,"why":"Dispensa de autorização não significa ausência de condições. Também não se deve frustrar reunião anteriormente convocada para o mesmo local. Base: Art. 5º, XVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XVI","origin":"authored_current_official_source"},{"q":"O prévio aviso previsto para reunião equivale a licença discricionária que a autoridade pode negar sem fundamento.","a":false,"why":"O texto distingue aviso de autorização, que é dispensada nas condições constitucionais. O aviso não pode ser usado para apagar a liberdade garantida. Base: Art. 5º, XVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XVI","origin":"authored_current_official_source"},{"q":"Uma associação de finalidade lícita pode ser criada sem autorização estatal, observada a vedação constitucional ao caráter paramilitar.","a":true,"why":"Liberdade associativa e limites expressos convivem. A dispensa de autorização não legitima finalidade ilícita nem organização paramilitar. Base: Art. 5º, XVII e XVIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XVII e XVIII","origin":"authored_current_official_source"},{"q":"Uma autoridade administrativa pode dissolver compulsoriamente associação por decisão própria, desde que apresente relatório detalhado.","a":false,"why":"A dissolução compulsória exige decisão judicial com trânsito em julgado. Fundamentação administrativa não substitui essa reserva. Base: Art. 5º, XIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XIX","origin":"authored_current_official_source"},{"q":"Suspender atividades e dissolver compulsoriamente uma associação exigem decisão judicial, mas a Constituição acrescenta trânsito em julgado para a dissolução.","a":true,"why":"A diferença entre as duas medidas é expressa. Não se deve exigir ou dispensar o mesmo marco sem distinguir a providência. Base: Art. 5º, XIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XIX","origin":"authored_current_official_source"},{"q":"Depois de ingressar livremente em associação, a pessoa fica constitucionalmente obrigada a permanecer associada por tempo indefinido.","a":false,"why":"Ninguém pode ser compelido a associar-se ou permanecer associado. O ingresso inicial não elimina a garantia de saída. Base: Art. 5º, XX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XX","origin":"authored_current_official_source"},{"q":"A proteção da manifestação do pensamento convive com vedação ao anonimato, direito de resposta e reparação nas hipóteses constitucionais.","a":true,"why":"Liberdade de expressão não significa imunidade absoluta a consequências jurídicas. É necessário analisar o caso e as garantias envolvidas. Base: Art. 5º, IV e V.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, IV e V","origin":"authored_current_official_source"},{"q":"A atividade artística pode ser submetida, como regra geral, a licença prévia de censura apenas por ser dirigida ao público.","a":false,"why":"O inciso IX protege a expressão artística independentemente de censura ou licença. O enunciado inverte a regra constitucional. Base: Art. 5º, IX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, IX","origin":"authored_current_official_source"},{"q":"A proteção de consciência e crença inclui o livre exercício dos cultos e a proteção legal aos locais de culto e liturgias.","a":true,"why":"O Estado deve observar as garantias constitucionais; laicidade não autoriza, por si só, embaraçar toda prática religiosa. Base: Art. 5º, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, VI","origin":"authored_current_official_source"},{"q":"Laicidade constitucional significa que o poder público está autorizado a impedir genericamente o funcionamento de qualquer culto.","a":false,"why":"O art. 19 veda embaraço ao funcionamento, além das relações e práticas que especifica. Laicidade não é proibição geral de religião. Base: Art. 19, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 19, I","origin":"authored_current_official_source"},{"q":"A assistência religiosa pode ser assegurada em entidades civis e militares de internação coletiva, nos termos da lei.","a":true,"why":"O texto não limita a garantia a instituições militares. A disciplina legal deve ser considerada no caso concreto. Base: Art. 5º, VII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, VII","origin":"authored_current_official_source"},{"q":"A alegação de crença religiosa afasta automaticamente qualquer obrigação legal a todos imposta, mesmo com recusa da prestação alternativa fixada em lei.","a":false,"why":"O inciso VIII contém condições e não cria dispensa irrestrita. É preciso examinar obrigação e prestação alternativa. Base: Art. 5º, VIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, VIII","origin":"authored_current_official_source"},{"q":"Liberdade de locomoção em tempo de paz, nos termos da lei, não significa que transportar bens gere imunidade tributária automática.","a":true,"why":"A liberdade de deslocamento não elimina indistintamente obrigações legais sobre bens. São questões jurídicas distintas. Base: Art. 5º, XV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XV","origin":"authored_current_official_source"},{"q":"A liberdade profissional torna necessariamente inválida toda exigência legal de qualificação, sem examinar seu fundamento.","a":false,"why":"O texto admite qualificações profissionais estabelecidas em lei. A legitimidade de uma exigência depende de análise constitucional, não de uma proibição abstrata de toda qualificação. Base: Art. 5º, XIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XIII","origin":"authored_current_official_source"},{"q":"A regra de que ninguém é obrigado a fazer ou deixar de fazer algo senão em virtude de lei exige identificar a base jurídica da imposição.","a":true,"why":"Não basta a preferência de um agente para criar dever indistinto ao particular. Também é preciso compreender o alcance da norma aplicável. Base: Art. 5º, II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, II","origin":"authored_current_official_source"},{"q":"O acesso à informação e o sigilo da fonte, quando necessário ao exercício profissional, autorizam concluir que qualquer pessoa possa ocultar qualquer ato ilícito sob esse nome.","a":false,"why":"A garantia tem âmbito e finalidade próprios. O enunciado amplia o sigilo da fonte para uma imunidade geral que o texto não estabelece. Base: Art. 5º, XIV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XIV","origin":"authored_current_official_source"},{"q":"A vedação de interferência estatal no funcionamento associativo impede tratar toda associação privada como órgão subordinado à administração.","a":true,"why":"A liberdade tem proteção própria, observados os limites constitucionais. Não significa ausência de responsabilidade por condutas ilícitas. Base: Art. 5º, XVIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XVIII","origin":"authored_current_official_source"},{"q":"Basta que a reunião seja sem armas para afastar os requisitos de caráter pacífico e de não frustrar outra anteriormente convocada.","a":false,"why":"Os requisitos são cumulativos. Cumprir apenas um deles não torna irrelevantes as demais condições do inciso XVI. Base: Art. 5º, XVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XVI","origin":"authored_current_official_source"},{"q":"Direito de resposta proporcional ao agravo e indenização por dano podem coexistir, conforme a disciplina constitucional.","a":true,"why":"O inciso V usa garantia de resposta além da indenização cabível. Não se deve transformar uma providência em exclusão automática da outra. Base: Art. 5º, V.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, V","origin":"authored_current_official_source"},{"q":"A Constituição proíbe sem qualquer ressalva toda colaboração de interesse público entre poder público e organizações religiosas.","a":false,"why":"O inciso I ressalva colaboração de interesse público na forma da lei. A ressalva não autoriza, por outro lado, religião oficial ou dependência vedada. Base: Art. 19, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 19, I","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"69e03f4b-3bea-5054-9a06-e4819de75041","material_slug":"constitucional-liberdades-constitucionais","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"176ba36b086fc46b5da71f53fae646ff2a9b27da3fc23788328aa9c8645d3130","content":{"cases":[{"id":"aviso","title":"A reunião avisada e a autorização exigida","scenario":"Um grupo comunica reunião pacífica e sem armas em praça, sem conflito com outra anteriormente convocada. A autoridade exige licença política para concordar com as ideias defendidas.","question":"O prévio aviso transforma a reunião em autorização discricionária?","steps":["Confira os requisitos constitucionais da reunião.","Separe aviso e autorização.","Não acrescente condição de concordância ideológica da autoridade."],"conclusion":"Não. O inciso XVI dispensa autorização nas condições que estabelece.","pitfall":"Ler aviso como poder de aprovar ou rejeitar previamente a opinião do grupo.","variation":{"scenario":"Há outra reunião anteriormente convocada para o mesmo local e a nova a frustraria.","answer":"Esse fato exige examinar condição constitucional expressa que não estava presente no caso inicial."},"articles":["Art. 5º, XVI"]},{"id":"associacao","title":"Fechar associação por portaria","scenario":"Uma autoridade manda dissolver definitivamente associação por portaria, sem decisão judicial.","question":"A fundamentação da portaria substitui a reserva judicial?","steps":["Identifique a medida: dissolução compulsória.","Leia a exigência de decisão judicial e trânsito em julgado.","Distinga dissolução de suspensão de atividades."],"conclusion":"Não. A portaria não satisfaz a condição do art. 5º, XIX.","pitfall":"Supor que toda restrição associativa tem o mesmo órgão e o mesmo marco.","variation":{"scenario":"A medida pretendida é suspensão de atividades, determinada judicialmente.","answer":"A Constituição exige decisão judicial também nessa hipótese, mas acrescenta trânsito em julgado expressamente à dissolução."},"articles":["Art. 5º, XIX"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"628bf3f3-9eb9-5669-9061-a5a5440f96f3","slug":"constitucional-propriedade-funcao-social","discipline":"Direito Constitucional","topic_label":"Propriedade e função social","sort_order":13,"title":"Propriedade: função social, desapropriação e requisição","summary":"Leitura orientada de propriedade: função social, desapropriação e requisição. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Garantia e função social caminham juntas\n\nO art. 5º garante propriedade e exige atendimento à função social. Ter o bem não dispensa os limites constitucionais e legais; invocar função social também não autoriza tomar qualquer bem sem procedimento ou hipótese normativa.\n\n| Instituto | Ponto central |\n| --- | --- |\n| Desapropriação ordinária | Necessidade ou utilidade pública, ou interesse social; justa e prévia indenização em dinheiro, ressalvados os casos constitucionais |\n| Requisição | Uso de propriedade particular por autoridade competente em iminente perigo público; indenização ulterior se houver dano |\n| Desapropriações com regime constitucional específico | Leia os arts. 182 e 184; não aplique automaticamente a forma de pagamento da hipótese ordinária |\n| Expropriação do art. 243 | Hipóteses constitucionais específicas, sem indenização, observada a disciplina aplicável; não confundir com qualquer irregularidade no imóvel |\n\n## Cuidado com duas trocas comuns\n\nRequisitar não significa sempre transferir definitivamente a propriedade. E a indenização da requisição não é automaticamente prévia: a Constituição condiciona a indenização ulterior à existência de dano.\n\nO art. 5º, XXVI, protege a pequena propriedade rural definida em lei, trabalhada pela família, contra penhora por débitos decorrentes de sua atividade produtiva. Não generalize esse recorte para todo imóvel rural ou toda dívida. O regime do bem de família tem legislação própria; não deve ser reduzido a essa única disposição.\n\n## Autoria, herança e propriedade imaterial\n\nO art. 5º, XXVII, protege o direito exclusivo dos autores e sua transmissão aos herdeiros pelo tempo fixado em lei. Os incisos XXVIII e XXIX disciplinam outras proteções autorais e industriais. Usar uma ideia ou informação pública não equivale a receber autorização para republicar a redação e a apresentação de uma apostila.\n\nO inciso XXX garante herança. Para bens de estrangeiros situados no Brasil, o inciso XXXI contém regra própria em benefício de cônjuge ou filhos brasileiros, sem afastar lei pessoal mais favorável.\n\n**Para resolver:** identifique o instituto antes de decorar o momento ou a forma de indenização. A mesma palavra “intervenção” não torna requisição, desapropriação e expropriação equivalentes.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"A garantia da propriedade não elimina a exigência de função social, e a função social não autoriza qualquer tomada arbitrária do bem.","a":true,"why":"As duas disposições devem ser lidas em conjunto. Limitações e intervenções exigem fundamento e procedimento pertinentes. Base: Art. 5º, XXII e XXIII."},{"q":"Toda desapropriação constitucional deve ser indenizada previamente em dinheiro, sem qualquer ressalva no próprio texto.","a":false,"why":"A regra ordinária traz ressalva para os casos previstos na Constituição. É necessário distinguir hipóteses e regimes de pagamento. Base: Art. 5º, XXIV."},{"q":"Em iminente perigo público, o uso de propriedade particular pode gerar indenização ulterior se houver dano, conforme a hipótese constitucional.","a":true,"why":"A requisição não tem a mesma lógica de indenização prévia da desapropriação ordinária. O dano é condição expressa da indenização nesse inciso. Base: Art. 5º, XXV."},{"q":"A requisição administrativa transfere obrigatoriamente a propriedade e exige indenização prévia mesmo que nenhum dano ocorra.","a":false,"why":"O texto permite uso da propriedade e prevê indenização ulterior se houver dano. O enunciado troca natureza, momento e condição. Base: Art. 5º, XXV."},{"q":"A proteção da pequena propriedade rural contra penhora tem requisitos de definição legal, trabalho familiar e relação da dívida com a atividade produtiva.","a":true,"why":"A garantia não deve ser ampliada automaticamente a todo imóvel rural ou qualquer débito. É preciso conferir o recorte constitucional. Base: Art. 5º, XXVI."},{"q":"Qualquer grande propriedade rural fica impenhorável por toda dívida apenas porque pertence a uma família.","a":false,"why":"O dispositivo trata de pequena propriedade definida em lei e de condições específicas. O enunciado elimina requisitos essenciais. Base: Art. 5º, XXVI."},{"q":"O direito exclusivo dos autores sobre utilização, publicação e reprodução tem proteção constitucional e transmissão aos herdeiros pelo tempo fixado em lei.","a":true,"why":"A existência de informação relevante em uma obra não concede autorização geral para republicar sua redação. Ideia e expressão protegida precisam ser distinguidas. Base: Art. 5º, XXVII."},{"q":"A compra de uma apostila concede, por esse simples fato, direito constitucional de reproduzir comercialmente todo o texto de seu autor.","a":false,"why":"A garantia de autoria não é transferida indistintamente pela aquisição de um exemplar. Titularidade do suporte e direitos de reprodução são questões distintas. Base: Art. 5º, XXVII."},{"q":"A proteção constitucional a inventos industriais tem referência ao interesse social e ao desenvolvimento tecnológico e econômico.","a":true,"why":"Não se trata de garantia textual sem finalidade ou limites. A lei e o recorte constitucional disciplinam a proteção. Base: Art. 5º, XXIX."},{"q":"O direito de herança é incompatível com a Constituição porque todo bem deve voltar automaticamente ao Estado na morte do titular.","a":false,"why":"O inciso XXX garante herança. O enunciado nega diretamente uma proteção constitucional expressa. Base: Art. 5º, XXX."},{"q":"Na sucessão de bens de estrangeiro situados no Brasil, a Constituição contém proteção específica a cônjuge ou filhos brasileiros, sem afastar lei pessoal mais favorável.","a":true,"why":"A regra não deve ser reduzida a aplicação sempre prejudicial da lei brasileira. É necessário considerar a ressalva de favorecimento. Base: Art. 5º, XXXI."},{"q":"Qualquer descumprimento de função social de qualquer bem permite aplicar automaticamente a expropriação sem indenização do art. 243.","a":false,"why":"O artigo tem hipóteses específicas e disciplina própria. Não é consequência universal de toda irregularidade patrimonial. Base: Art. 243."},{"q":"Ao analisar intervenção na propriedade urbana, é inadequado aplicar automaticamente o mesmo regime de toda desapropriação ordinária.","a":true,"why":"A Constituição prevê instrumentos e condições específicos. Identificar a hipótese vem antes de definir forma de pagamento e procedimento. Base: Art. 182, § 4º."},{"q":"O regime constitucional de reforma agrária pode ser explicado apagando suas particularidades e afirmando indenização sempre idêntica à hipótese ordinária.","a":false,"why":"O art. 184 estabelece disciplina específica. A classificação do instituto é necessária para não misturar regimes constitucionais diferentes. Base: Art. 184."},{"q":"Se o uso emergencial de propriedade não causar dano, o inciso XXV não permite presumir indenização obrigatória pelo mesmo fundamento.","a":true,"why":"A indenização ulterior está condicionada a dano. O enunciado deve informar os fatos relevantes em vez de assumir prejuízo inexistente. Base: Art. 5º, XXV."},{"q":"A função social elimina integralmente a proteção constitucional da titularidade privada.","a":false,"why":"A Constituição garante a propriedade e exige função social. Uma disposição não apaga por inteiro a outra. Base: Art. 5º, XXII e XXIII."},{"q":"O texto constitucional protege, nos termos legais, participações individuais em obras coletivas e aspectos relacionados à imagem e voz.","a":true,"why":"A proteção não se limita ao autor de livro isolado. É necessário observar o âmbito do inciso e a legislação pertinente. Base: Art. 5º, XXVIII."},{"q":"Direitos autorais e proteção industrial são um único instituto com requisitos e duração necessariamente iguais.","a":false,"why":"A Constituição os trata em incisos distintos e remete à disciplina legal. Não se devem importar automaticamente prazo e requisitos de um para o outro. Base: Art. 5º, XXVII e XXIX."},{"q":"Identificar se houve desapropriação ou requisição é indispensável antes de responder sobre indenização prévia ou ulterior.","a":true,"why":"A troca dos institutos é fonte de erro. A hipótese e seus requisitos determinam o regime aplicável. Base: Art. 5º, XXIV e XXV."},{"q":"A proteção da pequena propriedade rural, por si só, contém toda a legislação de bem de família e substitui qualquer outra norma sobre o tema.","a":false,"why":"É uma garantia constitucional com recorte próprio. Outros regimes de proteção patrimonial não são integralmente definidos por esse inciso. Base: Art. 5º, XXVI."}],"flashcards":[{"f":"Como é a indenização na requisição do art. 5º, XXV?","b":"Ulterior, se houver dano, na hipótese de iminente perigo público."},{"f":"A função social extingue a propriedade?","b":"Não. Garantia de propriedade e função social devem ser lidas conjuntamente."},{"f":"Pequena propriedade rural é todo imóvel rural?","b":"Não. A proteção constitucional exige os requisitos específicos do inciso XXVI."},{"f":"Toda desapropriação tem o mesmo pagamento?","b":"Não. A Constituição prevê hipóteses e regimes específicos além da regra ordinária."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-propriedade-funcao-social","subject":"Direito Constitucional","topic_label":"Propriedade e função social","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"A garantia da propriedade não elimina a exigência de função social, e a função social não autoriza qualquer tomada arbitrária do bem.","a":true,"why":"As duas disposições devem ser lidas em conjunto. Limitações e intervenções exigem fundamento e procedimento pertinentes. Base: Art. 5º, XXII e XXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXII e XXIII","origin":"authored_current_official_source"},{"q":"Toda desapropriação constitucional deve ser indenizada previamente em dinheiro, sem qualquer ressalva no próprio texto.","a":false,"why":"A regra ordinária traz ressalva para os casos previstos na Constituição. É necessário distinguir hipóteses e regimes de pagamento. Base: Art. 5º, XXIV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXIV","origin":"authored_current_official_source"},{"q":"Em iminente perigo público, o uso de propriedade particular pode gerar indenização ulterior se houver dano, conforme a hipótese constitucional.","a":true,"why":"A requisição não tem a mesma lógica de indenização prévia da desapropriação ordinária. O dano é condição expressa da indenização nesse inciso. Base: Art. 5º, XXV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXV","origin":"authored_current_official_source"},{"q":"A requisição administrativa transfere obrigatoriamente a propriedade e exige indenização prévia mesmo que nenhum dano ocorra.","a":false,"why":"O texto permite uso da propriedade e prevê indenização ulterior se houver dano. O enunciado troca natureza, momento e condição. Base: Art. 5º, XXV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXV","origin":"authored_current_official_source"},{"q":"A proteção da pequena propriedade rural contra penhora tem requisitos de definição legal, trabalho familiar e relação da dívida com a atividade produtiva.","a":true,"why":"A garantia não deve ser ampliada automaticamente a todo imóvel rural ou qualquer débito. É preciso conferir o recorte constitucional. Base: Art. 5º, XXVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXVI","origin":"authored_current_official_source"},{"q":"Qualquer grande propriedade rural fica impenhorável por toda dívida apenas porque pertence a uma família.","a":false,"why":"O dispositivo trata de pequena propriedade definida em lei e de condições específicas. O enunciado elimina requisitos essenciais. Base: Art. 5º, XXVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXVI","origin":"authored_current_official_source"},{"q":"O direito exclusivo dos autores sobre utilização, publicação e reprodução tem proteção constitucional e transmissão aos herdeiros pelo tempo fixado em lei.","a":true,"why":"A existência de informação relevante em uma obra não concede autorização geral para republicar sua redação. Ideia e expressão protegida precisam ser distinguidas. Base: Art. 5º, XXVII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXVII","origin":"authored_current_official_source"},{"q":"A compra de uma apostila concede, por esse simples fato, direito constitucional de reproduzir comercialmente todo o texto de seu autor.","a":false,"why":"A garantia de autoria não é transferida indistintamente pela aquisição de um exemplar. Titularidade do suporte e direitos de reprodução são questões distintas. Base: Art. 5º, XXVII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXVII","origin":"authored_current_official_source"},{"q":"A proteção constitucional a inventos industriais tem referência ao interesse social e ao desenvolvimento tecnológico e econômico.","a":true,"why":"Não se trata de garantia textual sem finalidade ou limites. A lei e o recorte constitucional disciplinam a proteção. Base: Art. 5º, XXIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXIX","origin":"authored_current_official_source"},{"q":"O direito de herança é incompatível com a Constituição porque todo bem deve voltar automaticamente ao Estado na morte do titular.","a":false,"why":"O inciso XXX garante herança. O enunciado nega diretamente uma proteção constitucional expressa. Base: Art. 5º, XXX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXX","origin":"authored_current_official_source"},{"q":"Na sucessão de bens de estrangeiro situados no Brasil, a Constituição contém proteção específica a cônjuge ou filhos brasileiros, sem afastar lei pessoal mais favorável.","a":true,"why":"A regra não deve ser reduzida a aplicação sempre prejudicial da lei brasileira. É necessário considerar a ressalva de favorecimento. Base: Art. 5º, XXXI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXXI","origin":"authored_current_official_source"},{"q":"Qualquer descumprimento de função social de qualquer bem permite aplicar automaticamente a expropriação sem indenização do art. 243.","a":false,"why":"O artigo tem hipóteses específicas e disciplina própria. Não é consequência universal de toda irregularidade patrimonial. Base: Art. 243.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 243","origin":"authored_current_official_source"},{"q":"Ao analisar intervenção na propriedade urbana, é inadequado aplicar automaticamente o mesmo regime de toda desapropriação ordinária.","a":true,"why":"A Constituição prevê instrumentos e condições específicos. Identificar a hipótese vem antes de definir forma de pagamento e procedimento. Base: Art. 182, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 182, § 4º","origin":"authored_current_official_source"},{"q":"O regime constitucional de reforma agrária pode ser explicado apagando suas particularidades e afirmando indenização sempre idêntica à hipótese ordinária.","a":false,"why":"O art. 184 estabelece disciplina específica. A classificação do instituto é necessária para não misturar regimes constitucionais diferentes. Base: Art. 184.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 184","origin":"authored_current_official_source"},{"q":"Se o uso emergencial de propriedade não causar dano, o inciso XXV não permite presumir indenização obrigatória pelo mesmo fundamento.","a":true,"why":"A indenização ulterior está condicionada a dano. O enunciado deve informar os fatos relevantes em vez de assumir prejuízo inexistente. Base: Art. 5º, XXV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXV","origin":"authored_current_official_source"},{"q":"A função social elimina integralmente a proteção constitucional da titularidade privada.","a":false,"why":"A Constituição garante a propriedade e exige função social. Uma disposição não apaga por inteiro a outra. Base: Art. 5º, XXII e XXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXII e XXIII","origin":"authored_current_official_source"},{"q":"O texto constitucional protege, nos termos legais, participações individuais em obras coletivas e aspectos relacionados à imagem e voz.","a":true,"why":"A proteção não se limita ao autor de livro isolado. É necessário observar o âmbito do inciso e a legislação pertinente. Base: Art. 5º, XXVIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXVIII","origin":"authored_current_official_source"},{"q":"Direitos autorais e proteção industrial são um único instituto com requisitos e duração necessariamente iguais.","a":false,"why":"A Constituição os trata em incisos distintos e remete à disciplina legal. Não se devem importar automaticamente prazo e requisitos de um para o outro. Base: Art. 5º, XXVII e XXIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXVII e XXIX","origin":"authored_current_official_source"},{"q":"Identificar se houve desapropriação ou requisição é indispensável antes de responder sobre indenização prévia ou ulterior.","a":true,"why":"A troca dos institutos é fonte de erro. A hipótese e seus requisitos determinam o regime aplicável. Base: Art. 5º, XXIV e XXV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXIV e XXV","origin":"authored_current_official_source"},{"q":"A proteção da pequena propriedade rural, por si só, contém toda a legislação de bem de família e substitui qualquer outra norma sobre o tema.","a":false,"why":"É uma garantia constitucional com recorte próprio. Outros regimes de proteção patrimonial não são integralmente definidos por esse inciso. Base: Art. 5º, XXVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXVI","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"868e9206-4810-5ca6-b1f8-208583bdeca1","material_slug":"constitucional-propriedade-funcao-social","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"318f0090d2000c542009eac31b4c53856f4a2f2c9ebc409d337caf275570566a","content":{"cases":[{"id":"requisicao","title":"Equipamento utilizado no perigo público","scenario":"Em iminente perigo público, a autoridade competente utiliza equipamento particular. O equipamento é devolvido sem dano, nos fatos informados.","question":"O inciso XXV impõe indenização prévia automática?","steps":["Identifique a requisição, sem confundi-la com desapropriação.","Leia o momento ulterior da indenização.","Verifique a condição de ocorrência de dano."],"conclusion":"Não. O fundamento do inciso XXV condiciona indenização ulterior a dano.","pitfall":"Importar a regra ordinária de desapropriação para qualquer uso emergencial.","variation":{"scenario":"O uso causa dano comprovado ao equipamento.","answer":"A condição para examinar a indenização ulterior passa a estar presente; será necessário apurar o dano e os demais elementos pertinentes."},"articles":["Art. 5º, XXV"]},{"id":"rural","title":"Pequena propriedade e dívida concreta","scenario":"Um pequeno imóvel rural definido em lei é trabalhado pela família. A dívida decorre da própria atividade produtiva.","question":"Quais elementos precisam ser conferidos na proteção do inciso XXVI?","steps":["Identifique a qualificação legal da pequena propriedade.","Verifique o trabalho familiar.","Relacione a dívida à atividade produtiva, sem ampliar a hipótese para toda obrigação."],"conclusion":"O conjunto dos requisitos é relevante; a simples localização rural não basta.","pitfall":"Aplicar uma proteção patrimonial específica como imunidade de todo imóvel a qualquer dívida.","variation":{"scenario":"O enunciado troca o imóvel por uma grande propriedade não enquadrada na definição legal.","answer":"A premissa central da garantia do inciso XXVI deixou de estar demonstrada. Outros regimes precisam de fundamento próprio."},"articles":["Art. 5º, XXVI"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"a0032af3-beb5-52da-8a05-7470d2784acb","slug":"constitucional-seguranca-juridica-processo","discipline":"Direito Constitucional","topic_label":"Segurança jurídica e garantias processuais","sort_order":14,"title":"Segurança jurídica: domicílio, defesa, processo e sanções","summary":"Leitura orientada de segurança jurídica: domicílio, defesa, processo e sanções. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Segurança jurídica não é somente atividade policial\n\nEste módulo trata das garantias do art. 5º: proteção do domicílio, acesso à Justiça, defesa, legalidade das sanções e limites ao poder de punir. A organização das polícias é assunto constitucional distinto, no art. 144.\n\n## Domicílio e comunicações\n\nO art. 5º, XI, permite ingresso sem consentimento em flagrante delito, desastre ou para prestar socorro; por determinação judicial, durante o dia. A condição temporal da ordem judicial não deve ser transportada mecanicamente às outras hipóteses. Não se presume válida qualquer entrada só porque foi praticada por agente público.\n\nO inciso XII protege comunicações e prevê a exceção constitucional para interceptação telefônica mediante ordem judicial, nas hipóteses e na forma legais, para investigação criminal ou instrução processual penal. Não trate correspondência, interceptação telefônica e dados armazenados como uma única técnica. O tema de dados pessoais tem [material próprio](/dashboard/library/constitucional-privacidade-dados).\n\n## Defesa e acesso à Justiça\n\n| Garantia | Distinção útil |\n| --- | --- |\n| Devido processo | Privação de liberdade ou bens exige observância do devido processo legal |\n| Contraditório e ampla defesa | Abrangem litigantes em processo judicial ou administrativo e acusados em geral |\n| Juiz natural | Julgamento pela autoridade competente; vedação de juízo ou tribunal de exceção |\n| Inafastabilidade | Lesão **ou ameaça** a direito pode ser submetida ao Judiciário |\n| Duração razoável | Vale no âmbito judicial e administrativo, sem autorizar eliminar defesa |\n| Segurança temporal | A lei não prejudicará direito adquirido, ato jurídico perfeito e coisa julgada |\n\nO art. 5º, LVI, veda provas obtidas por meios ilícitos. O inciso LX permite restringir publicidade quando defesa da intimidade ou interesse social o exigirem. Publicidade, acesso à informação e gratuidade possuem recortes próprios: o registro civil de nascimento e a certidão de óbito são gratuitos para os reconhecidamente pobres, nos termos legais; o texto não torna gratuito todo ato cartorário para qualquer finalidade.\n\n## Sanções: não misture categorias\n\nImprescritibilidade, inafiançabilidade e insuscetibilidade de graça ou anistia são características diferentes. Leia separadamente os incisos XLII, XLIII e XLIV; não conclua que todo crime inafiançável seja imprescritível. Observe também anterioridade penal, retroatividade benéfica, individualização e limites de penas.\n\nA Súmula Vinculante 25 do STF afasta prisão civil do depositário infiel em qualquer modalidade de depósito. Repetir isoladamente a parte final do art. 5º, LXVII, sem essa orientação, conduz a resposta desatualizada. Isso não elimina a hipótese própria de obrigação alimentícia nem autoriza prisão civil por dívida comum.\n\nPara prisão cautelar, execução penal e regras processuais detalhadas, use os materiais próprios de Processo Penal e a jurisprudência atual aplicável; um quadro constitucional não substitui essa análise.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"STF — Súmula Vinculante 25 e precedentes representativos","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"A referência constitucional ao período diurno está associada ao ingresso por determinação judicial, sem transformar socorro em hipótese proibida durante a noite.","a":true,"why":"O texto distingue fundamentos de ingresso. É errado transferir automaticamente a condição temporal da ordem judicial a desastre, flagrante ou socorro. Base: Art. 5º, XI."},{"q":"Sem consentimento do morador, qualquer ingresso em casa exige sempre ordem judicial, inclusive para prestar socorro em emergência.","a":false,"why":"O inciso XI prevê exceções expressas, incluindo prestar socorro. A exigência absoluta de ordem elimina indevidamente essas hipóteses. Base: Art. 5º, XI."},{"q":"Uma aula deve distinguir interceptação telefônica de acesso a dados armazenados, em vez de supor que a mesma frase constitucional resolva indistintamente qualquer técnica.","a":true,"why":"Objeto, medida e fundamento importam. O inciso XII e a legislação aplicável precisam ser analisados segundo o caso concreto. Base: Art. 5º, XII."},{"q":"O Judiciário só pode apreciar lesão já consumada, sendo constitucionalmente vedado examinar ameaça a direito.","a":false,"why":"O texto contempla lesão ou ameaça. A proteção não depende de esperar a consumação de todo dano. Base: Art. 5º, XXXV."},{"q":"Privação de bens exige devido processo, e contraditório e ampla defesa não ficam restritos ao processo penal.","a":true,"why":"As garantias alcançam os âmbitos indicados na Constituição. Não é correto excluir genericamente processos administrativos ou litígios civis. Base: Art. 5º, LIV e LV."},{"q":"Por ocorrer na administração, um processo com litigantes pode excluir sempre contraditório e ampla defesa.","a":false,"why":"O inciso LV abrange processo judicial ou administrativo e acusados em geral. A natureza administrativa não cria dispensa absoluta dessas garantias. Base: Art. 5º, LV."},{"q":"Duração razoável do processo e meios de celeridade devem conviver com as garantias de defesa.","a":true,"why":"A Constituição não autoriza eliminar defesa apenas para acelerar o resultado. Celeridade é direito com aplicação nos âmbitos judicial e administrativo. Base: Art. 5º, LXXVIII."},{"q":"Uma lei posterior pode ignorar automaticamente coisa julgada porque toda lei nova prevalece sobre qualquer situação anterior.","a":false,"why":"O inciso XXXVI protege direito adquirido, ato jurídico perfeito e coisa julgada. A aplicação temporal não se resolve por preferência genérica pela novidade. Base: Art. 5º, XXXVI."},{"q":"Vedação de tribunal de exceção e exigência de autoridade competente ajudam a identificar o juiz natural.","a":true,"why":"Não se deve criar julgador de exceção para alcançar resultado desejado em caso específico. A competência deve ser examinada segundo o sistema constitucional. Base: Art. 5º, XXXVII e LIII."},{"q":"Prova obtida por meio ilícito se torna constitucionalmente admissível apenas porque pode acelerar a condenação.","a":false,"why":"O inciso LVI estabelece inadmissibilidade. Conveniência do resultado não substitui análise das garantias e do regime de prova. Base: Art. 5º, LVI."},{"q":"A publicidade dos atos processuais admite restrição nas hipóteses de defesa da intimidade ou interesse social previstas no texto.","a":true,"why":"Publicidade não significa exposição irrestrita de qualquer informação em toda situação. A restrição também exige fundamento pertinente. Base: Art. 5º, LX."},{"q":"A Constituição declara gratuitamente disponível qualquer certidão cartorária para qualquer pessoa e finalidade, sem condições.","a":false,"why":"O inciso LXXVI tem recorte de reconhecida pobreza e refere-se a registro de nascimento e certidão de óbito. Outras gratuidades dependem de fundamento próprio. Base: Art. 5º, LXXVI."},{"q":"Inafiançabilidade e imprescritibilidade são características distintas, e uma não deve ser presumida apenas pela presença da outra.","a":true,"why":"Os incisos possuem redações e objetos diferentes. A classificação exige leitura de cada hipótese, não uma equivalência automática. Base: Art. 5º, XLII a XLIV."},{"q":"A menção constitucional à inafiançabilidade de determinados crimes permite afirmar que todos eles são necessariamente imprescritíveis pelo mesmo inciso.","a":false,"why":"O inciso XLIII não estabelece essa equivalência. É preciso distinguir as características previstas nos diferentes dispositivos. Base: Art. 5º, XLIII."},{"q":"Uma questão atual não deve autorizar prisão civil de depositário infiel apenas por repetir isoladamente a parte final do art. 5º, LXVII.","a":true,"why":"A Súmula Vinculante 25 considera ilícita essa prisão em qualquer modalidade de depósito. A orientação deve acompanhar a leitura do texto constitucional. Base: Súmula Vinculante 25."},{"q":"A vedação à prisão civil do depositário infiel autoriza concluir que não existe nenhuma hipótese própria de prisão civil relacionada a alimentos.","a":false,"why":"A orientação trata do depositário infiel e não elimina o regime próprio do inadimplemento alimentar. Os fundamentos jurídicos precisam ser separados. Base: Súmula Vinculante 25."},{"q":"Anterioridade penal e retroatividade da lei mais benéfica devem ser consideradas em conjunto ao analisar mudança legislativa.","a":true,"why":"Não há crime sem lei anterior que o defina, e a lei penal não retroage salvo para beneficiar. Aplicar sempre a lei mais nova é método incorreto. Base: Art. 5º, XXXIX e XL."},{"q":"A Constituição admite pena de caráter perpétuo sempre que o crime for inafiançável.","a":false,"why":"A vedação de pena perpétua não é afastada genericamente por inafiançabilidade. São categorias constitucionais distintas. Base: Art. 5º, XLVII."},{"q":"Direito de petição em defesa de direitos ou contra ilegalidade e certidões para os fins constitucionais independem do pagamento de taxas.","a":true,"why":"A garantia tem finalidades indicadas no texto. Não deve ser confundida com gratuidade universal de qualquer documento ou processo. Base: Art. 5º, XXXIV."},{"q":"O princípio de que ninguém será considerado culpado antes do trânsito em julgado dispensa examinar os requisitos próprios de uma prisão cautelar.","a":false,"why":"Presunção de não culpabilidade e cautelares não se resolvem por identidade automática. A medida concreta exige fundamento legal e constitucional pertinente. Base: Art. 5º, LVII."}],"flashcards":[{"f":"A ameaça precisa consumar-se para acesso à Justiça?","b":"Não. O art. 5º, XXXV, abrange lesão ou ameaça."},{"f":"Inafiançável significa sempre imprescritível?","b":"Não. São características distintas, com hipóteses constitucionais próprias."},{"f":"Pode haver prisão civil de depositário infiel?","b":"Não, segundo a Súmula Vinculante 25, qualquer que seja a modalidade de depósito."},{"f":"Celeridade elimina defesa?","b":"Não. Duração razoável deve conviver com as garantias do processo."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-seguranca-juridica-processo","subject":"Direito Constitucional","topic_label":"Segurança jurídica e garantias processuais","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"},{"url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","sha256":"bc86006e17122d1adbcb84afabff011071c4d7aa66f1fdfb642aa303fefe8861","checked_at":"2026-10-24T20:54:31.843369+00:00"}],"items":[{"q":"A referência constitucional ao período diurno está associada ao ingresso por determinação judicial, sem transformar socorro em hipótese proibida durante a noite.","a":true,"why":"O texto distingue fundamentos de ingresso. É errado transferir automaticamente a condição temporal da ordem judicial a desastre, flagrante ou socorro. Base: Art. 5º, XI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XI","origin":"authored_current_official_source"},{"q":"Sem consentimento do morador, qualquer ingresso em casa exige sempre ordem judicial, inclusive para prestar socorro em emergência.","a":false,"why":"O inciso XI prevê exceções expressas, incluindo prestar socorro. A exigência absoluta de ordem elimina indevidamente essas hipóteses. Base: Art. 5º, XI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XI","origin":"authored_current_official_source"},{"q":"Uma aula deve distinguir interceptação telefônica de acesso a dados armazenados, em vez de supor que a mesma frase constitucional resolva indistintamente qualquer técnica.","a":true,"why":"Objeto, medida e fundamento importam. O inciso XII e a legislação aplicável precisam ser analisados segundo o caso concreto. Base: Art. 5º, XII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XII","origin":"authored_current_official_source"},{"q":"O Judiciário só pode apreciar lesão já consumada, sendo constitucionalmente vedado examinar ameaça a direito.","a":false,"why":"O texto contempla lesão ou ameaça. A proteção não depende de esperar a consumação de todo dano. Base: Art. 5º, XXXV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXXV","origin":"authored_current_official_source"},{"q":"Privação de bens exige devido processo, e contraditório e ampla defesa não ficam restritos ao processo penal.","a":true,"why":"As garantias alcançam os âmbitos indicados na Constituição. Não é correto excluir genericamente processos administrativos ou litígios civis. Base: Art. 5º, LIV e LV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LIV e LV","origin":"authored_current_official_source"},{"q":"Por ocorrer na administração, um processo com litigantes pode excluir sempre contraditório e ampla defesa.","a":false,"why":"O inciso LV abrange processo judicial ou administrativo e acusados em geral. A natureza administrativa não cria dispensa absoluta dessas garantias. Base: Art. 5º, LV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LV","origin":"authored_current_official_source"},{"q":"Duração razoável do processo e meios de celeridade devem conviver com as garantias de defesa.","a":true,"why":"A Constituição não autoriza eliminar defesa apenas para acelerar o resultado. Celeridade é direito com aplicação nos âmbitos judicial e administrativo. Base: Art. 5º, LXXVIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXVIII","origin":"authored_current_official_source"},{"q":"Uma lei posterior pode ignorar automaticamente coisa julgada porque toda lei nova prevalece sobre qualquer situação anterior.","a":false,"why":"O inciso XXXVI protege direito adquirido, ato jurídico perfeito e coisa julgada. A aplicação temporal não se resolve por preferência genérica pela novidade. Base: Art. 5º, XXXVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXXVI","origin":"authored_current_official_source"},{"q":"Vedação de tribunal de exceção e exigência de autoridade competente ajudam a identificar o juiz natural.","a":true,"why":"Não se deve criar julgador de exceção para alcançar resultado desejado em caso específico. A competência deve ser examinada segundo o sistema constitucional. Base: Art. 5º, XXXVII e LIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXXVII e LIII","origin":"authored_current_official_source"},{"q":"Prova obtida por meio ilícito se torna constitucionalmente admissível apenas porque pode acelerar a condenação.","a":false,"why":"O inciso LVI estabelece inadmissibilidade. Conveniência do resultado não substitui análise das garantias e do regime de prova. Base: Art. 5º, LVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LVI","origin":"authored_current_official_source"},{"q":"A publicidade dos atos processuais admite restrição nas hipóteses de defesa da intimidade ou interesse social previstas no texto.","a":true,"why":"Publicidade não significa exposição irrestrita de qualquer informação em toda situação. A restrição também exige fundamento pertinente. Base: Art. 5º, LX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LX","origin":"authored_current_official_source"},{"q":"A Constituição declara gratuitamente disponível qualquer certidão cartorária para qualquer pessoa e finalidade, sem condições.","a":false,"why":"O inciso LXXVI tem recorte de reconhecida pobreza e refere-se a registro de nascimento e certidão de óbito. Outras gratuidades dependem de fundamento próprio. Base: Art. 5º, LXXVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXVI","origin":"authored_current_official_source"},{"q":"Inafiançabilidade e imprescritibilidade são características distintas, e uma não deve ser presumida apenas pela presença da outra.","a":true,"why":"Os incisos possuem redações e objetos diferentes. A classificação exige leitura de cada hipótese, não uma equivalência automática. Base: Art. 5º, XLII a XLIV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XLII a XLIV","origin":"authored_current_official_source"},{"q":"A menção constitucional à inafiançabilidade de determinados crimes permite afirmar que todos eles são necessariamente imprescritíveis pelo mesmo inciso.","a":false,"why":"O inciso XLIII não estabelece essa equivalência. É preciso distinguir as características previstas nos diferentes dispositivos. Base: Art. 5º, XLIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XLIII","origin":"authored_current_official_source"},{"q":"Uma questão atual não deve autorizar prisão civil de depositário infiel apenas por repetir isoladamente a parte final do art. 5º, LXVII.","a":true,"why":"A Súmula Vinculante 25 considera ilícita essa prisão em qualquer modalidade de depósito. A orientação deve acompanhar a leitura do texto constitucional. Base: Súmula Vinculante 25.","source_url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","article":"Súmula Vinculante 25","origin":"authored_current_official_source"},{"q":"A vedação à prisão civil do depositário infiel autoriza concluir que não existe nenhuma hipótese própria de prisão civil relacionada a alimentos.","a":false,"why":"A orientação trata do depositário infiel e não elimina o regime próprio do inadimplemento alimentar. Os fundamentos jurídicos precisam ser separados. Base: Súmula Vinculante 25.","source_url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","article":"Súmula Vinculante 25","origin":"authored_current_official_source"},{"q":"Anterioridade penal e retroatividade da lei mais benéfica devem ser consideradas em conjunto ao analisar mudança legislativa.","a":true,"why":"Não há crime sem lei anterior que o defina, e a lei penal não retroage salvo para beneficiar. Aplicar sempre a lei mais nova é método incorreto. Base: Art. 5º, XXXIX e XL.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXXIX e XL","origin":"authored_current_official_source"},{"q":"A Constituição admite pena de caráter perpétuo sempre que o crime for inafiançável.","a":false,"why":"A vedação de pena perpétua não é afastada genericamente por inafiançabilidade. São categorias constitucionais distintas. Base: Art. 5º, XLVII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XLVII","origin":"authored_current_official_source"},{"q":"Direito de petição em defesa de direitos ou contra ilegalidade e certidões para os fins constitucionais independem do pagamento de taxas.","a":true,"why":"A garantia tem finalidades indicadas no texto. Não deve ser confundida com gratuidade universal de qualquer documento ou processo. Base: Art. 5º, XXXIV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, XXXIV","origin":"authored_current_official_source"},{"q":"O princípio de que ninguém será considerado culpado antes do trânsito em julgado dispensa examinar os requisitos próprios de uma prisão cautelar.","a":false,"why":"Presunção de não culpabilidade e cautelares não se resolvem por identidade automática. A medida concreta exige fundamento legal e constitucional pertinente. Base: Art. 5º, LVII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LVII","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"},{"title":"STF — Súmula Vinculante 25 e precedentes representativos","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268","sha256":"bc86006e17122d1adbcb84afabff011071c4d7aa66f1fdfb642aa303fefe8861"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"e07425ae-1ab4-592a-aa8d-283ebfe31fea","material_slug":"constitucional-seguranca-juridica-processo","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"3fee57db72c264348a01a56a8d98ebdf3399bb7dac3a772c4bc805f3df1bd449","content":{"cases":[{"id":"socorro","title":"Socorro durante a noite","scenario":"Um pedido real de socorro exige ingresso em residência durante a noite, sem possibilidade de obter consentimento no cenário descrito.","question":"É correto negar toda hipótese constitucional de ingresso apenas pelo horário?","steps":["Identifique o fundamento informado: socorro.","Leia as exceções do art. 5º, XI.","Separe a condição diurna da determinação judicial das outras hipóteses."],"conclusion":"Não. O texto não restringe a prestação de socorro ao período diurno.","pitfall":"Confundir todas as hipóteses de ingresso com cumprimento de ordem judicial.","variation":{"scenario":"Não há socorro, desastre, flagrante ou consentimento; existe apenas ordem judicial.","answer":"A condição temporal da hipótese judicial torna-se relevante. A conclusão do caso inicial não pode ser reaproveitada sem os mesmos fatos."},"articles":["Art. 5º, XI"]},{"id":"deposito","title":"O recorte antigo sobre depositário","scenario":"Um resumo autoriza prisão civil do depositário infiel citando apenas a parte final do art. 5º, LXVII.","question":"A resposta está atualizada com a orientação vinculante?","steps":["Identifique a modalidade de prisão civil.","Consulte a Súmula Vinculante 25 no STF.","Distinga depósito de obrigação alimentar."],"conclusion":"Não. O STF considera ilícita a prisão civil de depositário infiel em qualquer modalidade de depósito.","pitfall":"Ensinar o texto isolado sem a orientação que afasta sua aplicação nessa hipótese.","variation":{"scenario":"A obrigação discutida passa a ser alimentar, com regime e pressupostos próprios.","answer":"A Súmula sobre depósito não resolve essa outra hipótese. É necessário analisar o título e o procedimento pertinentes."},"articles":["Art. 5º, LXVII","Súmula Vinculante 25"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"STF — Súmula Vinculante 25 e precedentes representativos","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"ce365e6c-e01d-5e9e-afea-522b8d908759","slug":"constitucional-remedios-constitucionais","discipline":"Direito Constitucional","topic_label":"Remédios constitucionais","sort_order":15,"title":"Remédios constitucionais: escolha, requisitos e limites","summary":"Leitura orientada de remédios constitucionais: escolha, requisitos e limites. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Escolha pelo direito e pelo problema\n\n| Instrumento | Problema central |\n| --- | --- |\n| Habeas corpus | Violência ou coação, atual ou ameaçada, à liberdade de locomoção por ilegalidade ou abuso de poder |\n| Habeas data | Conhecimento ou retificação de informações sobre o próprio impetrante, nos registros constitucionalmente previstos |\n| Mandado de segurança | Direito líquido e certo não amparado por habeas corpus ou habeas data, diante do ato previsto na Constituição |\n| Mandado de injunção | Falta de norma regulamentadora que inviabiliza o exercício de direito, liberdade ou prerrogativa constitucional abrangida |\n| Ação popular | Cidadão busca anular ato lesivo aos bens e valores previstos no art. 5º, LXXIII |\n\n## Informação pública não é sempre habeas data\n\nQuerer informação sobre política pública ou sobre outra pessoa não equivale a pedir acesso aos próprios dados. O habeas data tem âmbito específico e a Lei 9.507/1997 exige comprovar recusa ou decurso do prazo pertinente, conforme a providência. Não confunda essa exigência com esgotamento de todos os recursos administrativos.\n\n## Segurança exige prova adequada\n\nDireito líquido e certo exige suporte documental apto, sem a dilação probatória própria de outras ações. A Lei 12.016/2009 prevê prazo de 120 dias contado da ciência do ato impugnado para requerer mandado de segurança. O marco não é uma data escolhida pelo interessado. Regime de liminares e outras questões controvertidas exigem jurisprudência atual; este módulo não reproduz vedações legais antigas sem essa conferência.\n\nNo mandado de segurança coletivo, confira os legitimados do art. 5º, LXX: partido com representação no Congresso e organização sindical, entidade de classe ou associação nas condições constitucionais. Não transforme legitimidade coletiva em autorização irrestrita para qualquer pessoa jurídica.\n\n## Injunção não é somente uma declaração abstrata\n\nA Lei 13.300/2016 disciplina a omissão total ou parcial e permite definir condições para exercício do direito nas hipóteses legais. Não ensine que toda decisão apenas comunica a mora e nada pode concretizar. Também não afirme que o juiz substitui permanentemente o legislador em qualquer assunto.\n\n## Gratuidade e legitimidade\n\nHabeas corpus e habeas data são gratuitos, conforme o art. 5º, LXXVII. A ação popular pode ser proposta por cidadão; pessoa jurídica não se torna cidadã para esse fim. A isenção do autor popular tem ressalva de comprovada má-fé. Não estenda automaticamente a mesma gratuidade a todo remédio constitucional.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.507/1997 — habeas data","url":"https://www.planalto.gov.br/ccivil_03/Leis/L9507.htm"},{"title":"Lei 13.300/2016 — mandado de injunção","url":"https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm"},{"title":"Lei 12.016/2009 — mandado de segurança","url":"https://www.planalto.gov.br/ccivil_03/_Ato2007-2010/2009/Lei/L12016.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Se o problema apresentado é ameaça ilegal à locomoção, a análise do habeas corpus é mais adequada que escolher habeas data apenas por também ser remédio constitucional.","a":true,"why":"Os instrumentos protegem objetos distintos. A escolha começa pelo direito atingido e pelas condições da ameaça ou coação. Base: Art. 5º, LXVIII."},{"q":"Habeas data é instrumento constitucional genérico para obter qualquer dado de qualquer outra pessoa.","a":false,"why":"O texto trata de informações relativas à pessoa do impetrante nos registros previstos. Não é acesso irrestrito a dados de terceiros. Base: Art. 5º, LXXII."},{"q":"Na ação de habeas data, a exigência legal de demonstrar recusa ou decurso do prazo pertinente não equivale a esgotar todo recurso administrativo possível.","a":true,"why":"É necessário conferir a providência e os requisitos legais. A lei não deve ser substituída por uma regra genérica de exaurimento administrativo total. Base: Art. 8º, parágrafo único."},{"q":"Mandado de segurança substitui automaticamente habeas corpus e habeas data sempre que o interessado preferir seu nome.","a":false,"why":"O inciso LXIX delimita direito não amparado por esses dois instrumentos. A preferência pessoal não elimina a especificidade constitucional. Base: Art. 5º, LXIX."},{"q":"Para o prazo legal de requerer mandado de segurança, a ciência do ato impugnado é marco relevante, não a data que o interessado escolhe para começar a contar.","a":true,"why":"A Lei 12.016 prevê 120 dias da ciência do ato. O enunciado deve identificar o marco e a situação concreta, sem inventar prorrogação genérica. Base: Art. 23."},{"q":"O prazo indicado na Lei 12.016 para requerer mandado de segurança é, como regra textual, de 120 meses.","a":false,"why":"A lei prevê 120 dias. Trocar a unidade de tempo altera radicalmente a disciplina do prazo. Base: Art. 23."},{"q":"A expressão direito líquido e certo exige examinar o suporte probatório, não apenas a convicção subjetiva do impetrante.","a":true,"why":"O instrumento não se destina indistintamente a qualquer controvérsia que dependa de ampla produção probatória. É preciso verificar a adequação da via. Base: Art. 5º, LXIX."},{"q":"Qualquer associação criada no mesmo dia possui legitimidade coletiva irrestrita pelo simples fato de registrar um nome.","a":false,"why":"A Constituição exige condições próprias para associações, além do objeto de defesa dos interesses. Não há autorização coletiva universal sem requisitos. Base: Art. 5º, LXX."},{"q":"Partido político com representação no Congresso Nacional está entre os legitimados constitucionais para mandado de segurança coletivo.","a":true,"why":"A representação é condição textual dessa hipótese. Não se presume a mesma legitimidade constitucional para todo agrupamento sem representação. Base: Art. 5º, LXX, a."},{"q":"Pessoa jurídica pode propor ação popular como cidadã apenas porque tem patrimônio e pode sofrer prejuízo.","a":false,"why":"A legitimidade constitucional é do cidadão. A personalidade jurídica e o interesse econômico não transformam uma entidade em cidadã para essa ação. Base: Art. 5º, LXXIII."},{"q":"A isenção do autor de ação popular tem ressalva de comprovada má-fé.","a":true,"why":"A gratuidade constitucional não legitima atuação de má-fé sem consequências. A ressalva deve acompanhar o estudo da garantia. Base: Art. 5º, LXXIII."},{"q":"Todos os remédios constitucionais são declarados gratuitos, de modo indistinto, pelo mesmo inciso que menciona habeas corpus e habeas data.","a":false,"why":"O inciso LXXVII nomeia essas duas ações. Outros instrumentos têm regimes próprios; não se deve ampliar automaticamente a mesma regra. Base: Art. 5º, LXXVII."},{"q":"A falta parcial de norma pode ser relevante para mandado de injunção quando a regulamentação for insuficiente para tornar viável o exercício constitucional protegido.","a":true,"why":"A Lei 13.300 contempla omissão parcial e disciplina as providências. Não exige que toda a matéria esteja completamente sem qualquer texto normativo. Base: Arts. 2º e 8º."},{"q":"A lei atual obriga toda decisão de injunção a limitar-se a uma comunicação sem jamais estabelecer condições de exercício do direito.","a":false,"why":"A Lei 13.300 prevê providências de concretização nas condições legais. O enunciado reproduz uma redução indevida dos efeitos possíveis. Base: Art. 8º."},{"q":"Os efeitos subjetivos da decisão de injunção devem ser examinados conforme a lei, sem presumir que toda decisão tenha automaticamente alcance irrestrito para qualquer pessoa.","a":true,"why":"A lei contém disciplina própria e hipóteses de ampliação. O alcance não deve ser inventado a partir do simples nome da ação. Base: Art. 9º."},{"q":"Mandado de injunção é remédio destinado a corrigir qualquer insatisfação com lei que já permite plenamente exercer o direito.","a":false,"why":"O objeto é falta de norma regulamentadora que inviabilize o exercício nas condições constitucionais. Insatisfação genérica com conteúdo legal não basta. Base: Art. 5º, LXXI."},{"q":"Um pedido de retificação dos próprios dados em banco de caráter público exige distinguir a providência específica de simples acesso a informação pública genérica.","a":true,"why":"O habeas data possui objeto próprio. O caso deve ser enquadrado pelo titular da informação, natureza do registro e finalidade do pedido. Base: Art. 5º, LXXII."},{"q":"Ação popular protege exclusivamente o patrimônio financeiro, sem alcançar moralidade administrativa, meio ambiente ou patrimônio histórico e cultural.","a":false,"why":"O inciso LXXIII enumera esses bens e valores. Reduzir o objeto a dinheiro elimina parte expressa da proteção. Base: Art. 5º, LXXIII."},{"q":"A garantia do habeas corpus contempla tanto sofrimento atual quanto ameaça de violência ou coação à liberdade de locomoção.","a":true,"why":"A tutela constitucional não exige esperar a consumação de toda restrição. O enunciado deve informar ilegalidade ou abuso e o vínculo com locomoção. Base: Art. 5º, LXVIII."},{"q":"Mandado de segurança e mandado de injunção são nomes intercambiáveis para o mesmo problema constitucional.","a":false,"why":"Um enfrenta o ato violador de direito líquido e certo nas condições próprias; o outro, omissão normativa impeditiva. A escolha depende do problema identificado. Base: Art. 5º, LXIX e LXXI."}],"flashcards":[{"f":"Qual garantia se liga à locomoção ameaçada ilegalmente?","b":"Habeas corpus, nas condições do art. 5º, LXVIII."},{"f":"Habeas data é acesso genérico a dados de terceiros?","b":"Não. Seu objeto constitucional se refere às informações sobre o próprio impetrante."},{"f":"Qual é o problema central do mandado de injunção?","b":"Falta de regulamentação que inviabiliza o exercício constitucional protegido."},{"f":"Pessoa jurídica é cidadã para ação popular?","b":"Não. O inciso LXXIII tem legitimidade própria do cidadão."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-remedios-constitucionais","subject":"Direito Constitucional","topic_label":"Remédios constitucionais","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/Leis/L9507.htm","sha256":"40a296f0fd3180b5a7d550e53b1f12b81f480c2ad018c5919e5be692d1a2a6d0","checked_at":"2026-10-24T20:54:30.185012+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm","sha256":"9492a18c98cca6062aff17c9ae9dc32125d9431a1a3e2d0cfdca234815fa39e2","checked_at":"2026-10-24T20:54:30.132001+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/_Ato2007-2010/2009/Lei/L12016.htm","sha256":"e5e2c723ffd948ac102f7116c1f7c03fd86133b13a11e16c6ca09f3212259c6f","checked_at":"2026-10-24T20:54:29.930924+00:00"}],"items":[{"q":"Se o problema apresentado é ameaça ilegal à locomoção, a análise do habeas corpus é mais adequada que escolher habeas data apenas por também ser remédio constitucional.","a":true,"why":"Os instrumentos protegem objetos distintos. A escolha começa pelo direito atingido e pelas condições da ameaça ou coação. Base: Art. 5º, LXVIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXVIII","origin":"authored_current_official_source"},{"q":"Habeas data é instrumento constitucional genérico para obter qualquer dado de qualquer outra pessoa.","a":false,"why":"O texto trata de informações relativas à pessoa do impetrante nos registros previstos. Não é acesso irrestrito a dados de terceiros. Base: Art. 5º, LXXII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXII","origin":"authored_current_official_source"},{"q":"Na ação de habeas data, a exigência legal de demonstrar recusa ou decurso do prazo pertinente não equivale a esgotar todo recurso administrativo possível.","a":true,"why":"É necessário conferir a providência e os requisitos legais. A lei não deve ser substituída por uma regra genérica de exaurimento administrativo total. Base: Art. 8º, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Leis/L9507.htm","article":"Art. 8º, parágrafo único","origin":"authored_current_official_source"},{"q":"Mandado de segurança substitui automaticamente habeas corpus e habeas data sempre que o interessado preferir seu nome.","a":false,"why":"O inciso LXIX delimita direito não amparado por esses dois instrumentos. A preferência pessoal não elimina a especificidade constitucional. Base: Art. 5º, LXIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXIX","origin":"authored_current_official_source"},{"q":"Para o prazo legal de requerer mandado de segurança, a ciência do ato impugnado é marco relevante, não a data que o interessado escolhe para começar a contar.","a":true,"why":"A Lei 12.016 prevê 120 dias da ciência do ato. O enunciado deve identificar o marco e a situação concreta, sem inventar prorrogação genérica. Base: Art. 23.","source_url":"https://www.planalto.gov.br/ccivil_03/_Ato2007-2010/2009/Lei/L12016.htm","article":"Art. 23","origin":"authored_current_official_source"},{"q":"O prazo indicado na Lei 12.016 para requerer mandado de segurança é, como regra textual, de 120 meses.","a":false,"why":"A lei prevê 120 dias. Trocar a unidade de tempo altera radicalmente a disciplina do prazo. Base: Art. 23.","source_url":"https://www.planalto.gov.br/ccivil_03/_Ato2007-2010/2009/Lei/L12016.htm","article":"Art. 23","origin":"authored_current_official_source"},{"q":"A expressão direito líquido e certo exige examinar o suporte probatório, não apenas a convicção subjetiva do impetrante.","a":true,"why":"O instrumento não se destina indistintamente a qualquer controvérsia que dependa de ampla produção probatória. É preciso verificar a adequação da via. Base: Art. 5º, LXIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXIX","origin":"authored_current_official_source"},{"q":"Qualquer associação criada no mesmo dia possui legitimidade coletiva irrestrita pelo simples fato de registrar um nome.","a":false,"why":"A Constituição exige condições próprias para associações, além do objeto de defesa dos interesses. Não há autorização coletiva universal sem requisitos. Base: Art. 5º, LXX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXX","origin":"authored_current_official_source"},{"q":"Partido político com representação no Congresso Nacional está entre os legitimados constitucionais para mandado de segurança coletivo.","a":true,"why":"A representação é condição textual dessa hipótese. Não se presume a mesma legitimidade constitucional para todo agrupamento sem representação. Base: Art. 5º, LXX, a.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXX, a","origin":"authored_current_official_source"},{"q":"Pessoa jurídica pode propor ação popular como cidadã apenas porque tem patrimônio e pode sofrer prejuízo.","a":false,"why":"A legitimidade constitucional é do cidadão. A personalidade jurídica e o interesse econômico não transformam uma entidade em cidadã para essa ação. Base: Art. 5º, LXXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXIII","origin":"authored_current_official_source"},{"q":"A isenção do autor de ação popular tem ressalva de comprovada má-fé.","a":true,"why":"A gratuidade constitucional não legitima atuação de má-fé sem consequências. A ressalva deve acompanhar o estudo da garantia. Base: Art. 5º, LXXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXIII","origin":"authored_current_official_source"},{"q":"Todos os remédios constitucionais são declarados gratuitos, de modo indistinto, pelo mesmo inciso que menciona habeas corpus e habeas data.","a":false,"why":"O inciso LXXVII nomeia essas duas ações. Outros instrumentos têm regimes próprios; não se deve ampliar automaticamente a mesma regra. Base: Art. 5º, LXXVII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXVII","origin":"authored_current_official_source"},{"q":"A falta parcial de norma pode ser relevante para mandado de injunção quando a regulamentação for insuficiente para tornar viável o exercício constitucional protegido.","a":true,"why":"A Lei 13.300 contempla omissão parcial e disciplina as providências. Não exige que toda a matéria esteja completamente sem qualquer texto normativo. Base: Arts. 2º e 8º.","source_url":"https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm","article":"Arts. 2º e 8º","origin":"authored_current_official_source"},{"q":"A lei atual obriga toda decisão de injunção a limitar-se a uma comunicação sem jamais estabelecer condições de exercício do direito.","a":false,"why":"A Lei 13.300 prevê providências de concretização nas condições legais. O enunciado reproduz uma redução indevida dos efeitos possíveis. Base: Art. 8º.","source_url":"https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm","article":"Art. 8º","origin":"authored_current_official_source"},{"q":"Os efeitos subjetivos da decisão de injunção devem ser examinados conforme a lei, sem presumir que toda decisão tenha automaticamente alcance irrestrito para qualquer pessoa.","a":true,"why":"A lei contém disciplina própria e hipóteses de ampliação. O alcance não deve ser inventado a partir do simples nome da ação. Base: Art. 9º.","source_url":"https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm","article":"Art. 9º","origin":"authored_current_official_source"},{"q":"Mandado de injunção é remédio destinado a corrigir qualquer insatisfação com lei que já permite plenamente exercer o direito.","a":false,"why":"O objeto é falta de norma regulamentadora que inviabilize o exercício nas condições constitucionais. Insatisfação genérica com conteúdo legal não basta. Base: Art. 5º, LXXI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXI","origin":"authored_current_official_source"},{"q":"Um pedido de retificação dos próprios dados em banco de caráter público exige distinguir a providência específica de simples acesso a informação pública genérica.","a":true,"why":"O habeas data possui objeto próprio. O caso deve ser enquadrado pelo titular da informação, natureza do registro e finalidade do pedido. Base: Art. 5º, LXXII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXII","origin":"authored_current_official_source"},{"q":"Ação popular protege exclusivamente o patrimônio financeiro, sem alcançar moralidade administrativa, meio ambiente ou patrimônio histórico e cultural.","a":false,"why":"O inciso LXXIII enumera esses bens e valores. Reduzir o objeto a dinheiro elimina parte expressa da proteção. Base: Art. 5º, LXXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXIII","origin":"authored_current_official_source"},{"q":"A garantia do habeas corpus contempla tanto sofrimento atual quanto ameaça de violência ou coação à liberdade de locomoção.","a":true,"why":"A tutela constitucional não exige esperar a consumação de toda restrição. O enunciado deve informar ilegalidade ou abuso e o vínculo com locomoção. Base: Art. 5º, LXVIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXVIII","origin":"authored_current_official_source"},{"q":"Mandado de segurança e mandado de injunção são nomes intercambiáveis para o mesmo problema constitucional.","a":false,"why":"Um enfrenta o ato violador de direito líquido e certo nas condições próprias; o outro, omissão normativa impeditiva. A escolha depende do problema identificado. Base: Art. 5º, LXIX e LXXI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXIX e LXXI","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"},{"title":"Lei 9.507/1997 — habeas data","url":"https://www.planalto.gov.br/ccivil_03/Leis/L9507.htm","sha256":"40a296f0fd3180b5a7d550e53b1f12b81f480c2ad018c5919e5be692d1a2a6d0"},{"title":"Lei 13.300/2016 — mandado de injunção","url":"https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm","sha256":"9492a18c98cca6062aff17c9ae9dc32125d9431a1a3e2d0cfdca234815fa39e2"},{"title":"Lei 12.016/2009 — mandado de segurança","url":"https://www.planalto.gov.br/ccivil_03/_Ato2007-2010/2009/Lei/L12016.htm","sha256":"e5e2c723ffd948ac102f7116c1f7c03fd86133b13a11e16c6ca09f3212259c6f"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"404fa67e-de9d-5bdc-80e9-0a6b1d084a3b","material_slug":"constitucional-remedios-constitucionais","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"99ee33489f6609c76418c61182e26f796864c558e69a6df6c25decded2ed327a","content":{"cases":[{"id":"dados","title":"Seus dados ou dados de terceiros?","scenario":"Uma pessoa pede acesso a informações relativas a ela própria em banco de caráter público e enfrenta a recusa pertinente.","question":"O objeto é o mesmo de uma consulta genérica sobre outra pessoa?","steps":["Identifique o titular das informações.","Confira natureza do banco e providência desejada.","Examine os requisitos da Lei 9.507, inclusive demonstração de recusa ou prazo pertinente."],"conclusion":"Não. O habeas data tem objeto próprio ligado à pessoa do impetrante.","pitfall":"Transformá-lo em acesso universal a qualquer banco sobre qualquer terceiro.","variation":{"scenario":"O pedido busca estatística pública sobre um programa, sem dados pessoais do requerente.","answer":"A via precisa ser reavaliada pelas regras de acesso à informação e outros instrumentos pertinentes, sem presumir habeas data."},"articles":["Art. 5º, LXXII","Lei 9.507/1997, art. 8º"]},{"id":"escolha","title":"Omissão normativa ou ato lesivo?","scenario":"Um direito não pode ser exercido porque falta norma regulamentadora. O requerente escolhe mandado de segurança sem analisar o tipo de problema.","question":"Qual distinção deve ser feita antes de escolher o instrumento?","steps":["Investigue se existe omissão normativa impeditiva.","Separe essa hipótese do ato que viola direito líquido e certo.","Consulte a disciplina atual do mandado de injunção e as condições do direito discutido."],"conclusion":"A escolha depende do problema constitucional; mandado de segurança e de injunção não são intercambiáveis.","pitfall":"Escolher pelo nome mais conhecido, ignorando a causa do impedimento.","variation":{"scenario":"A norma existe e o direito é exercitável, mas uma autoridade pratica ato ilegal comprovável documentalmente.","answer":"O exame passa ao ato e à adequação da via de proteção, incluindo a eventual hipótese de mandado de segurança."},"articles":["Art. 5º, LXIX","Art. 5º, LXXI"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"title":"Lei 9.507/1997 — habeas data","url":"https://www.planalto.gov.br/ccivil_03/Leis/L9507.htm"},{"title":"Lei 13.300/2016 — mandado de injunção","url":"https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm"},{"title":"Lei 12.016/2009 — mandado de segurança","url":"https://www.planalto.gov.br/ccivil_03/_Ato2007-2010/2009/Lei/L12016.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"a103e03c-6df9-50ff-a014-12685209e6f2","slug":"constitucional-direitos-sociais-trabalho","discipline":"Direito Constitucional","topic_label":"Proteção social e direitos dos trabalhadores","sort_order":16,"title":"Direitos sociais e trabalhistas: Constituição atual","summary":"Leitura orientada de direitos sociais e trabalhistas: constituição atual. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Direitos sociais não se limitam ao contrato de trabalho\n\nO art. 6º reúne educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância e assistência aos desamparados. Seu parágrafo único prevê renda básica familiar ao brasileiro em vulnerabilidade social, nas condições legais e observadas as regras fiscais e orçamentárias. Essa previsão não autoriza inventar valor ou afirmar pagamento automático sem regulamentação.\n\n## Leia cada proteção com seus requisitos\n\n| Tema do art. 7º | Recorte constitucional |\n| --- | --- |\n| Jornada normal | Até oito horas diárias e 44 semanais, com as possibilidades constitucionais de compensação e redução |\n| Hora extraordinária | Adicional de, no mínimo, 50% |\n| Férias | Acréscimo de pelo menos um terço sobre o salário normal |\n| Licença à gestante | 120 dias, sem prejuízo do emprego e do salário, conforme o inciso XVIII |\n| Trabalho do menor | Vedação de trabalho noturno, perigoso ou insalubre a menores de 18; qualquer trabalho a menores de 16, salvo aprendiz a partir de 14 |\n| Salário | Proteções próprias, inclusive irredutibilidade com ressalva de convenção ou acordo coletivo |\n\nNão substitua essas regras por jornadas, idades ou benefícios retirados de um resumo antigo. A Constituição não afirma que toda vantagem trabalhista vale indistintamente para qualquer vínculo público ou privado.\n\n## Trabalhadores domésticos e servidores\n\nO parágrafo único do art. 7º distingue direitos assegurados e direitos sujeitos às condições estabelecidas em lei. A leitura precisa considerar a ampliação constitucional já ocorrida; não use uma lista histórica curta como se fosse a atual. Para servidor ocupante de cargo público, o art. 39, § 3º, remete a incisos determinados, sem importar automaticamente todos os direitos do art. 7º.\n\n## Organização coletiva\n\nO art. 8º protege associação profissional ou sindical, afasta autorização estatal para fundação de sindicato, ressalvado o registro, e veda interferência e intervenção públicas. Isso não elimina a regra constitucional de unicidade na mesma base territorial, que não pode ser inferior à área de um município.\n\nO art. 9º garante greve e reserva à lei serviços essenciais e necessidades inadiáveis. Não confunda essa disciplina com autorização irrestrita de greve para toda carreira pública. Os arts. 10 e 11 contêm previsões de participação; a representação em empresa com mais de duzentos empregados busca entendimento direto com os empregadores.\n\nConsulte [Administração pública constitucional](/dashboard/library/constitucional-administracao-publica-constituicao) para distinguir vínculos e garantias dos servidores. Nacionalidade e direitos políticos permanecem em módulos separados.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Uma lista atual de direitos sociais deve considerar transporte e alimentação, em vez de repetir uma enumeração histórica que os omita.","a":true,"why":"O art. 6º atual inclui esses direitos. Um quadro antigo precisa ser confrontado com a redação vigente antes de ser usado como lista completa. Base: Art. 6º."},{"q":"A previsão constitucional de renda básica familiar fixa, por si só, valor mensal único e dispensa toda condição legal de acesso.","a":false,"why":"O parágrafo remete a normas e requisitos legais e observa legislação fiscal e orçamentária. Não contém esse valor automático universal. Base: Art. 6º, parágrafo único."},{"q":"A jornada constitucional normal tem referência de oito horas diárias e 44 semanais, com possibilidades constitucionais de compensação e redução.","a":true,"why":"A leitura precisa incluir a ressalva e distinguir jornada normal de serviço extraordinário. Não basta decorar um número isolado. Base: Art. 7º, XIII."},{"q":"O adicional constitucional mínimo do serviço extraordinário é de apenas 10% sobre a remuneração normal.","a":false,"why":"O inciso XVI estabelece, no mínimo, 50%. A unidade e o percentual integram o conteúdo da garantia. Base: Art. 7º, XVI."},{"q":"Férias anuais remuneradas têm acréscimo constitucional de pelo menos um terço sobre o salário normal.","a":true,"why":"Não se trata de substituir todo o salário por um terço. O acréscimo deve ser lido como proteção adicional. Base: Art. 7º, XVII."},{"q":"A Constituição afirma que a irredutibilidade salarial não admite nenhuma ressalva relacionada à negociação coletiva.","a":false,"why":"O inciso VI ressalva convenção ou acordo coletivo. A afirmação absoluta omite condição expressa do texto. Base: Art. 7º, VI."},{"q":"O aprendiz pode ser admitido a partir dos quatorze anos, sem que isso afaste a vedação de trabalho noturno, perigoso ou insalubre a menores de dezoito.","a":true,"why":"As faixas e vedações não são intercambiáveis. A exceção de aprendizagem não elimina as demais proteções. Base: Art. 7º, XXXIII."},{"q":"A autorização de aprendizagem aos quatorze anos libera, automaticamente, qualquer atividade perigosa ao adolescente.","a":false,"why":"O inciso mantém vedação de trabalho perigoso, noturno ou insalubre a menores de dezoito. A aprendizagem não cria essa liberação geral. Base: Art. 7º, XXXIII."},{"q":"A licença constitucional à gestante tem duração de 120 dias sem prejuízo do emprego e do salário, sem impedir que outros regimes tragam proteções adicionais válidas.","a":true,"why":"A referência constitucional não deve ser reduzida por tabela antiga. Também não significa que todo regime tenha apenas essa disciplina e nenhuma ampliação. Base: Art. 7º, XVIII."},{"q":"Os trabalhadores domésticos continuam sujeitos apenas a uma lista curta histórica, sendo desnecessário conferir a redação atual do parágrafo único.","a":false,"why":"O texto constitucional foi ampliado e distingue direitos e condições. A atualização é necessária para não ensinar um recorte superado como regime atual completo. Base: Art. 7º, parágrafo único."},{"q":"A remissão de direitos ao servidor ocupante de cargo público não significa importação automática de todos os incisos do art. 7º.","a":true,"why":"O art. 39, § 3º, enumera direitos específicos. É necessário identificar o vínculo e os incisos efetivamente remetidos. Base: Art. 39, § 3º."},{"q":"A fundação de sindicato depende, em regra constitucional, de autorização política discricionária do Estado.","a":false,"why":"O art. 8º afasta autorização, ressalvado o registro, e veda interferência e intervenção públicas. Registro não é licença política irrestrita. Base: Art. 8º, I."},{"q":"A liberdade sindical deve ser estudada com a regra constitucional de unicidade na mesma base territorial.","a":true,"why":"A proteção de organização não elimina o limite expresso. A base territorial não pode ser inferior à área de um município. Base: Art. 8º, II."},{"q":"A base territorial sindical pode ser livremente inferior à área de um bairro, pois a Constituição não prevê limite mínimo.","a":false,"why":"O inciso II fixa área não inferior à de um município. O enunciado apaga esse parâmetro constitucional. Base: Art. 8º, II."},{"q":"O sindicato tem atribuição constitucional de defender direitos e interesses coletivos ou individuais da categoria, inclusive em questões judiciais e administrativas.","a":true,"why":"A atuação não se limita a reuniões internas. O alcance concreto deve observar a Constituição e a disciplina aplicável. Base: Art. 8º, III."},{"q":"A previsão de greve autoriza concluir que não existem serviços essenciais nem necessidades inadiáveis a considerar.","a":false,"why":"O § 1º reserva à lei esses temas. A garantia não elimina todas as condições de continuidade e proteção da comunidade. Base: Art. 9º."},{"q":"Abusos no exercício da greve podem sujeitar os responsáveis às penas da lei.","a":true,"why":"A Constituição reconhece o direito e também consequências para abusos. Não se presume imunidade total por usar a palavra greve. Base: Art. 9º, § 2º."},{"q":"A representação prevista no art. 11 deve ser obrigatoriamente eleita em qualquer empresa com apenas um empregado.","a":false,"why":"O dispositivo se refere a empresas de mais de duzentos empregados e à finalidade de entendimento direto. A escala foi ampliada indevidamente no enunciado. Base: Art. 11."},{"q":"A participação de trabalhadores e empregadores em colegiados públicos tem recorte ligado aos interesses profissionais ou previdenciários discutidos.","a":true,"why":"A previsão constitucional não deve ser transformada em assento indistinto em todo órgão público de qualquer matéria. Base: Art. 10."},{"q":"Direitos sociais são sinônimo exclusivo de férias e remuneração, sem abranger educação, saúde ou assistência.","a":false,"why":"O art. 6º contém um conjunto mais amplo de proteções. O contrato de trabalho é apenas parte do estudo social constitucional. Base: Art. 6º."}],"flashcards":[{"f":"Aprendiz de 14 anos pode realizar atividade perigosa?","b":"A exceção etária de aprendizagem não afasta a vedação a menores de 18 em trabalho perigoso, noturno ou insalubre."},{"f":"Qual é o mínimo constitucional do adicional extraordinário?","b":"Cinquenta por cento sobre a remuneração normal."},{"f":"Todos os direitos do art. 7º valem automaticamente para qualquer servidor?","b":"Não. Confira o vínculo e a remissão específica do art. 39, § 3º."},{"f":"Base sindical pode ser menor que um município?","b":"Não, conforme o limite do art. 8º, II."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-direitos-sociais-trabalho","subject":"Direito Constitucional","topic_label":"Proteção social e direitos dos trabalhadores","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"Uma lista atual de direitos sociais deve considerar transporte e alimentação, em vez de repetir uma enumeração histórica que os omita.","a":true,"why":"O art. 6º atual inclui esses direitos. Um quadro antigo precisa ser confrontado com a redação vigente antes de ser usado como lista completa. Base: Art. 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 6º","origin":"authored_current_official_source"},{"q":"A previsão constitucional de renda básica familiar fixa, por si só, valor mensal único e dispensa toda condição legal de acesso.","a":false,"why":"O parágrafo remete a normas e requisitos legais e observa legislação fiscal e orçamentária. Não contém esse valor automático universal. Base: Art. 6º, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 6º, parágrafo único","origin":"authored_current_official_source"},{"q":"A jornada constitucional normal tem referência de oito horas diárias e 44 semanais, com possibilidades constitucionais de compensação e redução.","a":true,"why":"A leitura precisa incluir a ressalva e distinguir jornada normal de serviço extraordinário. Não basta decorar um número isolado. Base: Art. 7º, XIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 7º, XIII","origin":"authored_current_official_source"},{"q":"O adicional constitucional mínimo do serviço extraordinário é de apenas 10% sobre a remuneração normal.","a":false,"why":"O inciso XVI estabelece, no mínimo, 50%. A unidade e o percentual integram o conteúdo da garantia. Base: Art. 7º, XVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 7º, XVI","origin":"authored_current_official_source"},{"q":"Férias anuais remuneradas têm acréscimo constitucional de pelo menos um terço sobre o salário normal.","a":true,"why":"Não se trata de substituir todo o salário por um terço. O acréscimo deve ser lido como proteção adicional. Base: Art. 7º, XVII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 7º, XVII","origin":"authored_current_official_source"},{"q":"A Constituição afirma que a irredutibilidade salarial não admite nenhuma ressalva relacionada à negociação coletiva.","a":false,"why":"O inciso VI ressalva convenção ou acordo coletivo. A afirmação absoluta omite condição expressa do texto. Base: Art. 7º, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 7º, VI","origin":"authored_current_official_source"},{"q":"O aprendiz pode ser admitido a partir dos quatorze anos, sem que isso afaste a vedação de trabalho noturno, perigoso ou insalubre a menores de dezoito.","a":true,"why":"As faixas e vedações não são intercambiáveis. A exceção de aprendizagem não elimina as demais proteções. Base: Art. 7º, XXXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 7º, XXXIII","origin":"authored_current_official_source"},{"q":"A autorização de aprendizagem aos quatorze anos libera, automaticamente, qualquer atividade perigosa ao adolescente.","a":false,"why":"O inciso mantém vedação de trabalho perigoso, noturno ou insalubre a menores de dezoito. A aprendizagem não cria essa liberação geral. Base: Art. 7º, XXXIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 7º, XXXIII","origin":"authored_current_official_source"},{"q":"A licença constitucional à gestante tem duração de 120 dias sem prejuízo do emprego e do salário, sem impedir que outros regimes tragam proteções adicionais válidas.","a":true,"why":"A referência constitucional não deve ser reduzida por tabela antiga. Também não significa que todo regime tenha apenas essa disciplina e nenhuma ampliação. Base: Art. 7º, XVIII.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 7º, XVIII","origin":"authored_current_official_source"},{"q":"Os trabalhadores domésticos continuam sujeitos apenas a uma lista curta histórica, sendo desnecessário conferir a redação atual do parágrafo único.","a":false,"why":"O texto constitucional foi ampliado e distingue direitos e condições. A atualização é necessária para não ensinar um recorte superado como regime atual completo. Base: Art. 7º, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 7º, parágrafo único","origin":"authored_current_official_source"},{"q":"A remissão de direitos ao servidor ocupante de cargo público não significa importação automática de todos os incisos do art. 7º.","a":true,"why":"O art. 39, § 3º, enumera direitos específicos. É necessário identificar o vínculo e os incisos efetivamente remetidos. Base: Art. 39, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 39, § 3º","origin":"authored_current_official_source"},{"q":"A fundação de sindicato depende, em regra constitucional, de autorização política discricionária do Estado.","a":false,"why":"O art. 8º afasta autorização, ressalvado o registro, e veda interferência e intervenção públicas. Registro não é licença política irrestrita. Base: Art. 8º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 8º, I","origin":"authored_current_official_source"},{"q":"A liberdade sindical deve ser estudada com a regra constitucional de unicidade na mesma base territorial.","a":true,"why":"A proteção de organização não elimina o limite expresso. A base territorial não pode ser inferior à área de um município. Base: Art. 8º, II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 8º, II","origin":"authored_current_official_source"},{"q":"A base territorial sindical pode ser livremente inferior à área de um bairro, pois a Constituição não prevê limite mínimo.","a":false,"why":"O inciso II fixa área não inferior à de um município. O enunciado apaga esse parâmetro constitucional. Base: Art. 8º, II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 8º, II","origin":"authored_current_official_source"},{"q":"O sindicato tem atribuição constitucional de defender direitos e interesses coletivos ou individuais da categoria, inclusive em questões judiciais e administrativas.","a":true,"why":"A atuação não se limita a reuniões internas. O alcance concreto deve observar a Constituição e a disciplina aplicável. Base: Art. 8º, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 8º, III","origin":"authored_current_official_source"},{"q":"A previsão de greve autoriza concluir que não existem serviços essenciais nem necessidades inadiáveis a considerar.","a":false,"why":"O § 1º reserva à lei esses temas. A garantia não elimina todas as condições de continuidade e proteção da comunidade. Base: Art. 9º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 9º","origin":"authored_current_official_source"},{"q":"Abusos no exercício da greve podem sujeitar os responsáveis às penas da lei.","a":true,"why":"A Constituição reconhece o direito e também consequências para abusos. Não se presume imunidade total por usar a palavra greve. Base: Art. 9º, § 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 9º, § 2º","origin":"authored_current_official_source"},{"q":"A representação prevista no art. 11 deve ser obrigatoriamente eleita em qualquer empresa com apenas um empregado.","a":false,"why":"O dispositivo se refere a empresas de mais de duzentos empregados e à finalidade de entendimento direto. A escala foi ampliada indevidamente no enunciado. Base: Art. 11.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 11","origin":"authored_current_official_source"},{"q":"A participação de trabalhadores e empregadores em colegiados públicos tem recorte ligado aos interesses profissionais ou previdenciários discutidos.","a":true,"why":"A previsão constitucional não deve ser transformada em assento indistinto em todo órgão público de qualquer matéria. Base: Art. 10.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 10","origin":"authored_current_official_source"},{"q":"Direitos sociais são sinônimo exclusivo de férias e remuneração, sem abranger educação, saúde ou assistência.","a":false,"why":"O art. 6º contém um conjunto mais amplo de proteções. O contrato de trabalho é apenas parte do estudo social constitucional. Base: Art. 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 6º","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"30319e71-1e2d-5d1d-8378-08815fd2ca13","material_slug":"constitucional-direitos-sociais-trabalho","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"a4d679ed580f0b698f8bb59fcbce07af154ad35bd02e5c031c14aa53c43b5606","content":{"cases":[{"id":"adolescente","title":"Aprendizagem e trabalho perigoso","scenario":"Um contrato de aprendizagem pretende colocar adolescente de quinze anos em atividade perigosa e alega que a exceção etária resolve todo o problema.","question":"A possibilidade de aprendizagem afasta a outra vedação?","steps":["Separe idade mínima geral, aprendizagem e atividades vedadas.","Leia o limite de dezoito anos para trabalho noturno, perigoso ou insalubre.","Não use uma exceção para eliminar proteção distinta."],"conclusion":"Não. A aprendizagem não libera atividade perigosa ao menor de dezoito.","pitfall":"Usar apenas a idade mínima de aprendizagem como resposta completa.","variation":{"scenario":"A atividade é compatível com as proteções do adolescente e a aprendizagem observa a disciplina legal.","answer":"A objeção específica do perigo não está demonstrada, mas os demais requisitos legais continuam necessários."},"articles":["Art. 7º, XXXIII"]},{"id":"vinculo","title":"Empregado privado e servidor público","scenario":"Um quadro transfere todo o art. 7º, sem exceção, para qualquer cargo e contratação pública.","question":"Qual etapa foi omitida?","steps":["Identifique o vínculo e o destinatário da norma.","Leia a remissão específica do art. 39, § 3º.","Não transforme um rol de incisos determinados em importação irrestrita de todos os direitos."],"conclusion":"É necessário conferir os direitos remetidos e o regime aplicável; os vínculos não são automaticamente idênticos.","pitfall":"Usar a expressão trabalhador para apagar distinções constitucionais de regime.","variation":{"scenario":"O exemplo passa a tratar de trabalhador doméstico.","answer":"A referência passa ao parágrafo único do art. 7º e à legislação pertinente, com suas condições próprias."},"articles":["Art. 7º, parágrafo único","Art. 39, § 3º"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"1cd66f17-8cf4-583f-aced-2e422e141f17","slug":"constitucional-organizacao-estado-competencias","discipline":"Direito Constitucional","topic_label":"Organização do Estado","sort_order":17,"title":"Organização do Estado: entes, bens e competências","summary":"Leitura orientada de organização do estado: entes, bens e competências. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Comece pelo ente e pela espécie de competência\n\nUnião, estados, Distrito Federal e municípios são autônomos nos termos da Constituição. Territórios federais integram a União. A base conceitual da Federação já está em [Princípios fundamentais](/dashboard/library/constitucional-principios-fundamentais-federacao-republica); aqui o foco é a distribuição das atribuições.\n\n| Texto constitucional | Pergunta de prova |\n| --- | --- |\n| Art. 21 | Qual atribuição material cabe à União? |\n| Art. 22 | Qual matéria legislativa é privativa da União? Há autorização constitucional de delegação? |\n| Art. 23 | Há competência material comum entre os entes? |\n| Art. 24 | Há legislação concorrente, com normas gerais e suplementação? |\n| Arts. 25, 30 e 32 | Qual papel cabe a estado, município ou Distrito Federal? |\n\nUma matéria constar no art. 23 não significa que todo ente possa editar qualquer lei sobre ela. Competência administrativa e legislativa são dimensões diferentes.\n\n## Normas gerais não eliminam toda atuação estadual\n\nNa competência concorrente, a União estabelece normas gerais; a competência suplementar dos estados permanece. Sem lei federal de normas gerais, os estados exercem competência legislativa plena para atender peculiaridades. Lei federal superveniente suspende a eficácia da lei estadual no que lhe for contrário; a Constituição não usa “revoga integralmente toda lei estadual”.\n\nO município legisla sobre interesse local e suplementa a legislação federal e estadual no que couber. O art. 24 não enumera municípios entre seus titulares, mas isso não apaga as atribuições municipais do art. 30.\n\n## Organização e patrimônio\n\nOs arts. 20 e 26 distinguem bens da União e dos estados. Não suponha que um bem seja municipal apenas por estar localizado em um município. A criação de regiões metropolitanas depende de lei complementar estadual, nos termos do art. 25, § 3º; não cria automaticamente um novo ente federativo soberano.\n\nBrasília é a capital federal. O Distrito Federal não pode ser dividido em municípios e recebe competências legislativas estaduais e municipais. Constituição estadual e leis orgânicas têm regimes distintos.\n\n## Intervenção é excepcional\n\nOs arts. 34 a 36 estabelecem hipóteses, iniciativa e procedimentos próprios de intervenção. A autonomia é a regra; discordância política genérica não autoriza intervenção. Leia a hipótese concreta antes de identificar quem solicita, requisita ou decreta e quais controles incidem.\n\nA legislação posterior deve ser confrontada com esse mapa de competências. Exemplos de delegação, competências ambientais ou urbanísticas não autorizam concluir que toda matéria segue um único modelo.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Antes de afirmar quem pode editar uma lei, o candidato deve distinguir competência material de competência legislativa.","a":true,"why":"Atuar administrativamente e legislar não são a mesma atribuição. Os artigos constitucionais distribuem espécies diferentes de competência. Base: Arts. 21 a 24."},{"q":"Uma matéria ser de competência material comum significa que qualquer ente pode legislar livremente sobre qualquer aspecto dela.","a":false,"why":"Competência administrativa comum não é autorização legislativa universal. É preciso consultar também a repartição legislativa pertinente. Base: Art. 23."},{"q":"Na legislação concorrente, a União estabelece normas gerais sem excluir a competência suplementar dos estados.","a":true,"why":"A atuação federal não elimina toda disciplina estadual. É necessário identificar o âmbito das normas gerais e da suplementação. Base: Art. 24, §§ 1º e 2º."},{"q":"A ausência de lei federal de normas gerais impede por completo a atuação legislativa estadual na matéria concorrente.","a":false,"why":"O § 3º permite competência legislativa plena dos estados para atender a peculiaridades. O enunciado inverte a solução constitucional. Base: Art. 24, § 3º."},{"q":"A lei federal superveniente de normas gerais suspende a eficácia da lei estadual no que lhe for contrário.","a":true,"why":"A Constituição não diz revogação integral automática. O alcance do conflito é parte necessária da análise. Base: Art. 24, § 4º."},{"q":"Toda lei federal superveniente revoga integralmente qualquer lei estadual anterior sobre matéria concorrente, mesmo sem contradição.","a":false,"why":"O dispositivo trata de suspensão da eficácia no que for contrário. A generalização elimina tanto o limite material quanto a técnica constitucional. Base: Art. 24, § 4º."},{"q":"A ausência dos municípios na enumeração do art. 24 não elimina suas competências de interesse local e de suplementação no que couber.","a":true,"why":"O art. 30 contém atribuições próprias. É inadequado decidir toda atuação municipal olhando apenas uma lista de outro artigo. Base: Art. 30, I e II."},{"q":"A Constituição proíbe qualquer autorização aos estados para legislar sobre questões específicas das matérias do art. 22.","a":false,"why":"O parágrafo único admite autorização por lei complementar. A previsão não deve ser confundida com delegação irrestrita de toda a competência. Base: Art. 22, parágrafo único."},{"q":"A autorização constitucional de delegação do art. 22 se refere a questões específicas e exige lei complementar.","a":true,"why":"A espécie normativa e o recorte da autorização importam. Não basta um ato administrativo genérico para transferir toda matéria. Base: Art. 22, parágrafo único."},{"q":"Brasília é um território federal autônomo por ser a capital do país.","a":false,"why":"Brasília é a capital federal; territórios integram a União. As categorias constitucionais não se tornam equivalentes pela função de capital. Base: Art. 18, §§ 1º e 2º."},{"q":"A instituição de região metropolitana depende de lei complementar estadual nas condições constitucionais.","a":true,"why":"O agrupamento visa integrar funções públicas de interesse comum. Não cria automaticamente novo ente federativo soberano. Base: Art. 25, § 3º."},{"q":"Criar região metropolitana transforma os municípios envolvidos em um novo país com soberania própria.","a":false,"why":"A Constituição trata de organização e funções de interesse comum. Não há autorização de secessão nem criação de soberania pelo instituto. Base: Art. 25, § 3º."},{"q":"Localizar fisicamente um bem em um município não basta para classificá-lo como bem municipal.","a":true,"why":"A Constituição distribui bens por critérios próprios. O território onde o bem se situa não resolve sozinho sua titularidade. Base: Arts. 20 e 26."},{"q":"O Distrito Federal precisa ser dividido em municípios antes de exercer competências legislativas municipais.","a":false,"why":"O art. 32 veda essa divisão e atribui competências ao próprio Distrito Federal. Não se exige criar municípios para exercê-las. Base: Art. 32."},{"q":"Criação, incorporação, fusão e desmembramento de municípios exigem examinar as condições constitucionais próprias, não apenas vontade de uma autoridade local.","a":true,"why":"A disciplina inclui lei estadual, período determinado por lei complementar federal e consultas e estudos previstos. Não é decisão unilateral simples. Base: Art. 18, § 4º."},{"q":"Uma divergência política genérica entre governador e presidente autoriza, por si só, intervenção federal.","a":false,"why":"A intervenção depende das hipóteses e procedimentos constitucionais. Autonomia não pode ser afastada apenas por discordância política. Base: Art. 34."},{"q":"Identificar a hipótese de intervenção deve preceder a resposta sobre solicitação, requisição, decretação e controle.","a":true,"why":"Os caminhos variam conforme o fundamento constitucional. Usar um único procedimento para toda intervenção gera erro. Base: Arts. 34 a 36."},{"q":"As competências estaduais reservadas permitem ao estado exercer qualquer atribuição expressamente vedada pela Constituição.","a":false,"why":"A reserva alcança o que não é vedado. O enunciado troca o sentido da cláusula e ignora a supremacia constitucional. Base: Art. 25, § 1º."},{"q":"As vedações constitucionais aos entes devem ser observadas juntamente com suas competências.","a":true,"why":"Ter atribuição administrativa não elimina proibições constitucionais. Competência e limite precisam ser lidos no mesmo sistema. Base: Art. 19."},{"q":"Autonomia constitucional significa que cada ente pode ignorar integralmente a repartição de competências dos demais.","a":false,"why":"A autonomia existe nos termos da Constituição. Não equivale a poder soberano sem limites ou a autorização para invadir qualquer atribuição. Base: Art. 18."}],"flashcards":[{"f":"Competência material comum é liberdade legislativa universal?","b":"Não. Execução administrativa e atribuição legislativa precisam ser distinguidas."},{"f":"Lei federal superveniente revoga toda lei estadual concorrente?","b":"O art. 24, § 4º, fala em suspender eficácia no que for contrário."},{"f":"Município pode suplementar legislação?","b":"Sim, no que couber, conforme art. 30, II, além de legislar sobre interesse local."},{"f":"Região metropolitana vira novo ente soberano?","b":"Não. Tem organização e finalidade próprias no art. 25, § 3º."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-organizacao-estado-competencias","subject":"Direito Constitucional","topic_label":"Organização do Estado","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"Antes de afirmar quem pode editar uma lei, o candidato deve distinguir competência material de competência legislativa.","a":true,"why":"Atuar administrativamente e legislar não são a mesma atribuição. Os artigos constitucionais distribuem espécies diferentes de competência. Base: Arts. 21 a 24.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 21 a 24","origin":"authored_current_official_source"},{"q":"Uma matéria ser de competência material comum significa que qualquer ente pode legislar livremente sobre qualquer aspecto dela.","a":false,"why":"Competência administrativa comum não é autorização legislativa universal. É preciso consultar também a repartição legislativa pertinente. Base: Art. 23.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 23","origin":"authored_current_official_source"},{"q":"Na legislação concorrente, a União estabelece normas gerais sem excluir a competência suplementar dos estados.","a":true,"why":"A atuação federal não elimina toda disciplina estadual. É necessário identificar o âmbito das normas gerais e da suplementação. Base: Art. 24, §§ 1º e 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 24, §§ 1º e 2º","origin":"authored_current_official_source"},{"q":"A ausência de lei federal de normas gerais impede por completo a atuação legislativa estadual na matéria concorrente.","a":false,"why":"O § 3º permite competência legislativa plena dos estados para atender a peculiaridades. O enunciado inverte a solução constitucional. Base: Art. 24, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 24, § 3º","origin":"authored_current_official_source"},{"q":"A lei federal superveniente de normas gerais suspende a eficácia da lei estadual no que lhe for contrário.","a":true,"why":"A Constituição não diz revogação integral automática. O alcance do conflito é parte necessária da análise. Base: Art. 24, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 24, § 4º","origin":"authored_current_official_source"},{"q":"Toda lei federal superveniente revoga integralmente qualquer lei estadual anterior sobre matéria concorrente, mesmo sem contradição.","a":false,"why":"O dispositivo trata de suspensão da eficácia no que for contrário. A generalização elimina tanto o limite material quanto a técnica constitucional. Base: Art. 24, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 24, § 4º","origin":"authored_current_official_source"},{"q":"A ausência dos municípios na enumeração do art. 24 não elimina suas competências de interesse local e de suplementação no que couber.","a":true,"why":"O art. 30 contém atribuições próprias. É inadequado decidir toda atuação municipal olhando apenas uma lista de outro artigo. Base: Art. 30, I e II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 30, I e II","origin":"authored_current_official_source"},{"q":"A Constituição proíbe qualquer autorização aos estados para legislar sobre questões específicas das matérias do art. 22.","a":false,"why":"O parágrafo único admite autorização por lei complementar. A previsão não deve ser confundida com delegação irrestrita de toda a competência. Base: Art. 22, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 22, parágrafo único","origin":"authored_current_official_source"},{"q":"A autorização constitucional de delegação do art. 22 se refere a questões específicas e exige lei complementar.","a":true,"why":"A espécie normativa e o recorte da autorização importam. Não basta um ato administrativo genérico para transferir toda matéria. Base: Art. 22, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 22, parágrafo único","origin":"authored_current_official_source"},{"q":"Brasília é um território federal autônomo por ser a capital do país.","a":false,"why":"Brasília é a capital federal; territórios integram a União. As categorias constitucionais não se tornam equivalentes pela função de capital. Base: Art. 18, §§ 1º e 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 18, §§ 1º e 2º","origin":"authored_current_official_source"},{"q":"A instituição de região metropolitana depende de lei complementar estadual nas condições constitucionais.","a":true,"why":"O agrupamento visa integrar funções públicas de interesse comum. Não cria automaticamente novo ente federativo soberano. Base: Art. 25, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 25, § 3º","origin":"authored_current_official_source"},{"q":"Criar região metropolitana transforma os municípios envolvidos em um novo país com soberania própria.","a":false,"why":"A Constituição trata de organização e funções de interesse comum. Não há autorização de secessão nem criação de soberania pelo instituto. Base: Art. 25, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 25, § 3º","origin":"authored_current_official_source"},{"q":"Localizar fisicamente um bem em um município não basta para classificá-lo como bem municipal.","a":true,"why":"A Constituição distribui bens por critérios próprios. O território onde o bem se situa não resolve sozinho sua titularidade. Base: Arts. 20 e 26.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 20 e 26","origin":"authored_current_official_source"},{"q":"O Distrito Federal precisa ser dividido em municípios antes de exercer competências legislativas municipais.","a":false,"why":"O art. 32 veda essa divisão e atribui competências ao próprio Distrito Federal. Não se exige criar municípios para exercê-las. Base: Art. 32.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 32","origin":"authored_current_official_source"},{"q":"Criação, incorporação, fusão e desmembramento de municípios exigem examinar as condições constitucionais próprias, não apenas vontade de uma autoridade local.","a":true,"why":"A disciplina inclui lei estadual, período determinado por lei complementar federal e consultas e estudos previstos. Não é decisão unilateral simples. Base: Art. 18, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 18, § 4º","origin":"authored_current_official_source"},{"q":"Uma divergência política genérica entre governador e presidente autoriza, por si só, intervenção federal.","a":false,"why":"A intervenção depende das hipóteses e procedimentos constitucionais. Autonomia não pode ser afastada apenas por discordância política. Base: Art. 34.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 34","origin":"authored_current_official_source"},{"q":"Identificar a hipótese de intervenção deve preceder a resposta sobre solicitação, requisição, decretação e controle.","a":true,"why":"Os caminhos variam conforme o fundamento constitucional. Usar um único procedimento para toda intervenção gera erro. Base: Arts. 34 a 36.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 34 a 36","origin":"authored_current_official_source"},{"q":"As competências estaduais reservadas permitem ao estado exercer qualquer atribuição expressamente vedada pela Constituição.","a":false,"why":"A reserva alcança o que não é vedado. O enunciado troca o sentido da cláusula e ignora a supremacia constitucional. Base: Art. 25, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 25, § 1º","origin":"authored_current_official_source"},{"q":"As vedações constitucionais aos entes devem ser observadas juntamente com suas competências.","a":true,"why":"Ter atribuição administrativa não elimina proibições constitucionais. Competência e limite precisam ser lidos no mesmo sistema. Base: Art. 19.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 19","origin":"authored_current_official_source"},{"q":"Autonomia constitucional significa que cada ente pode ignorar integralmente a repartição de competências dos demais.","a":false,"why":"A autonomia existe nos termos da Constituição. Não equivale a poder soberano sem limites ou a autorização para invadir qualquer atribuição. Base: Art. 18.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 18","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"8dc59e9c-9be8-57d9-a086-6e09b4cb97d2","material_slug":"constitucional-organizacao-estado-competencias","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"7c81e00db6f4af024e0a7dae57adf7846b0b958b6b16f2e793e2e4621a883558","content":{"cases":[{"id":"concorrente","title":"A lei federal que chegou depois","scenario":"Um estado editou norma para peculiaridades locais na ausência de normas gerais federais, em matéria concorrente. Depois surge lei federal de normas gerais parcialmente incompatível.","question":"A Constituição exige revogação automática de toda a lei estadual?","steps":["Identifique a competência concorrente.","Confira a atuação estadual na ausência da lei federal.","Aplique a suspensão de eficácia somente no que for contrário à lei federal superveniente."],"conclusion":"Não. O art. 24, § 4º, prevê suspensão de eficácia na parte conflitante.","pitfall":"Trocar suspensão parcial de eficácia por revogação integral.","variation":{"scenario":"A norma estadual não conflita com as normas gerais supervenientes.","answer":"Não se presume a suspensão daquilo que não é contrário apenas pela existência de lei federal."},"articles":["Art. 24, §§ 3º e 4º"]},{"id":"material","title":"Atuar e legislar não são a mesma coisa","scenario":"Um órgão conclui que a competência material comum para cuidar de certo serviço permite a qualquer ente editar qualquer regra legislativa sobre toda a matéria.","question":"A conclusão decorre automaticamente do art. 23?","steps":["Separe execução administrativa e produção de normas legislativas.","Localize a distribuição legislativa nos artigos pertinentes.","Confira competências específicas e eventual suplementação."],"conclusion":"Não. A competência comum não substitui toda a repartição legislativa.","pitfall":"Resolver atribuição legislativa citando apenas uma competência material.","variation":{"scenario":"O município fundamenta lei em interesse local e suplementação no que couber.","answer":"Essas atribuições do art. 30 devem ser examinadas especificamente; não são idênticas à conclusão genérica do caso inicial."},"articles":["Art. 23","Art. 30"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"861a268d-7a76-5cc4-811c-927140655aae","slug":"constitucional-administracao-publica-constituicao","discipline":"Direito Constitucional","topic_label":"Administração pública constitucional","sort_order":18,"title":"Administração pública na Constituição: princípios, ingresso e vínculos","summary":"Leitura orientada de administração pública na constituição: princípios, ingresso e vínculos. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Princípios aplicáveis a todos os Poderes\n\nO caput do art. 37 exige legalidade, impessoalidade, moralidade, publicidade e eficiência na administração direta e indireta de qualquer Poder, na União, estados, Distrito Federal e municípios. Não são deveres exclusivos do Executivo federal.\n\nLegalidade não é autorização para agir sem competência. Impessoalidade afasta favorecimento e promoção pessoal; moralidade não se resume a evitar crime. Publicidade deve conviver com sigilos constitucionalmente legítimos. Eficiência não permite ignorar procedimento, direitos ou controles.\n\n## Concurso, confiança e contratação temporária\n\n| Situação | O que conferir |\n| --- | --- |\n| Cargo ou emprego público | Regra de concurso de provas ou de provas e títulos, conforme natureza e complexidade |\n| Cargo em comissão | Exceção constitucional de livre nomeação e exoneração nos termos legais |\n| Função de confiança | Exercício exclusivo por servidor ocupante de cargo efetivo |\n| Comissão e confiança | Destinação a direção, chefia e assessoramento; não servem indistintamente a toda tarefa permanente |\n| Contratação temporária | Hipóteses legais de necessidade temporária de excepcional interesse público |\n\nO concurso tem validade de até dois anos, prorrogável uma vez por igual período. A prioridade do aprovado durante o prazo constitucional não equivale a proibição absoluta de realizar qualquer concurso novo.\n\n## Organização, responsabilidade e aprofundamento\n\nO art. 37, XIX, distingue criação de autarquia por lei específica de autorização para instituição de outras entidades. O § 1º veda publicidade com promoção pessoal de autoridades e servidores; o § 6º trata da responsabilidade das pessoas jurídicas nele previstas e do regresso em caso de dolo ou culpa.\n\nOs temas completos de [atos administrativos](/dashboard/library/administrativo-atos-administrativos-requisitos-atributos), [controle](/dashboard/library/administrativo-controle-da-administracao-publica), [improbidade](/dashboard/library/administrativo-improbidade-lei-8429-reforma-14230) e [responsabilidade civil](/dashboard/library/administrativo-responsabilidade-civil-do-estado) já têm materiais próprios. Não substitua a Lei de Improbidade reformada por um quadro antigo.\n\n## Servidor não é uma categoria única\n\nO art. 41 condiciona estabilidade a três anos de efetivo exercício para nomeado em cargo efetivo por concurso, com avaliação especial. Estabilidade não se confunde com vitaliciedade de magistrado nem alcança automaticamente todo contratado.\n\nO art. 40 contém regras previdenciárias atuais, com distinções de ente, idade, regime e legislação. Não reutilize fórmulas anteriores à reforma como regra universal. Para regime de pessoal, consulte também a redação atual do art. 39 e a legislação pertinente ao ente. Não se presume conversão automática de vínculos existentes nem identidade de regime para toda contratação.\n\nA acumulação permitida teve atualização na EC 138/2025: consulte o [módulo específico](/dashboard/library/constitucional-acumulacao-ec138-casos), que evita repetir a antiga restrição de professor com cargo apenas técnico ou científico. Exercício de mandato eletivo e remuneração devem ser resolvidos pelas condições do art. 38.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Os princípios expressos do art. 37 alcançam administração direta e indireta de qualquer Poder e dos diferentes entes federativos.","a":true,"why":"Não são exclusivos do Executivo federal. O âmbito constitucional impede reduzir a exigência a um único órgão ou esfera. Base: Art. 37, caput."},{"q":"Eficiência permite afastar toda exigência de legalidade quando a autoridade julga o resultado conveniente.","a":false,"why":"Os princípios devem ser observados em conjunto. Eficiência não cria autorização geral para agir sem competência ou violar direitos. Base: Art. 37, caput."},{"q":"Publicidade de programas públicos não pode caracterizar promoção pessoal de autoridades ou servidores.","a":true,"why":"O caráter educativo, informativo ou de orientação social deve ser preservado. A divulgação institucional não é patrimônio promocional do agente. Base: Art. 37, § 1º."},{"q":"A regra de concurso pode ser afastada para todo cargo permanente apenas porque a administração lhe atribui um nome de confiança.","a":false,"why":"As exceções constitucionais têm condições próprias. Mudar a denominação não dispensa o exame da natureza e das atribuições. Base: Art. 37, II."},{"q":"Funções de confiança são exercidas exclusivamente por servidores ocupantes de cargo efetivo.","a":true,"why":"A regra não é idêntica à de todo cargo em comissão. É necessário distinguir as duas formas constitucionais de organização. Base: Art. 37, V."},{"q":"Cargos em comissão e funções de confiança podem ser destinados indistintamente a qualquer tarefa operacional permanente.","a":false,"why":"A Constituição os destina a direção, chefia e assessoramento. O enunciado elimina a delimitação funcional expressa. Base: Art. 37, V."},{"q":"A validade do concurso é de até dois anos e admite uma prorrogação por igual período.","a":true,"why":"O prazo inicial pode ser inferior a dois anos. Não há autorização constitucional para prorrogações sucessivas ilimitadas. Base: Art. 37, III."},{"q":"Um concurso com validade inicial de um ano pode receber, pela mesma regra, três prorrogações de dois anos.","a":false,"why":"O texto prevê uma prorrogação por igual período. O enunciado altera quantidade e duração. Base: Art. 37, III."},{"q":"Contratação por tempo determinado exige hipótese legal de necessidade temporária de excepcional interesse público.","a":true,"why":"Não é substituto genérico de todo concurso. A necessidade e o fundamento precisam corresponder à disciplina constitucional e legal. Base: Art. 37, IX."},{"q":"Uma autarquia pode ser criada por simples contrato privado sem lei específica, desde que seja considerada eficiente.","a":false,"why":"O inciso XIX exige lei específica para criação de autarquia. Conveniência administrativa não substitui a espécie normativa. Base: Art. 37, XIX."},{"q":"A redação constitucional distingue a criação de autarquia da autorização para instituir empresa pública ou sociedade de economia mista.","a":true,"why":"Não se deve usar a mesma fórmula para toda entidade. A lei específica tem papel distinto conforme a categoria. Base: Art. 37, XIX."},{"q":"O direito de regresso contra o agente prescinde sempre de dolo ou culpa porque a responsabilidade do Estado é tratada no mesmo parágrafo.","a":false,"why":"O § 6º assegura regresso nos casos de dolo ou culpa. A análise do ente e a do agente não se confundem automaticamente. Base: Art. 37, § 6º."},{"q":"Estabilidade do art. 41 exige os requisitos constitucionais, incluindo três anos de efetivo exercício e avaliação especial de desempenho.","a":true,"why":"A garantia está ligada ao cargo efetivo provido por concurso. Não decorre apenas de passar algum tempo em qualquer contratação pública. Base: Art. 41."},{"q":"Qualquer ocupante exclusivamente de cargo em comissão torna-se estável pelo simples decurso de três anos.","a":false,"why":"A garantia do art. 41 tem destinatários e requisitos próprios. Não alcança automaticamente essa hipótese pelo tempo isolado. Base: Art. 41."},{"q":"Servidor abrangido pelo art. 38 investido no mandato de prefeito deve afastar-se do cargo, emprego ou função, com a opção de remuneração prevista.","a":true,"why":"O texto distingue essa situação do vereador com compatibilidade. Não se deve usar a mesma solução de acumulação para todo mandato. Base: Art. 38, II."},{"q":"O vereador abrangido pelo art. 38 pode acumular os exercícios independentemente de compatibilidade de horários.","a":false,"why":"A compatibilidade é condição expressa. Se ela não existe, aplica-se a regra constitucional pertinente, não uma dispensa geral. Base: Art. 38, III."},{"q":"Após a EC 138/2025, a hipótese de professor com outro cargo de qualquer natureza ainda depende de compatibilidade de horários e das condições constitucionais.","a":true,"why":"A atualização ampliou a natureza do outro cargo, não eliminou todos os limites. O módulo específico de acumulação aprofunda os casos. Base: Art. 37, XVI."},{"q":"A redação atual continua limitando necessariamente o segundo cargo do professor apenas a cargo técnico ou científico.","a":false,"why":"A EC 138/2025 passou a prever outro de qualquer natureza. Repetir a fórmula antiga como regra vigente desatualiza o conteúdo. Base: Art. 37, XVI, b."},{"q":"A análise de aposentadoria voluntária no regime próprio precisa distinguir a regra constitucional federal e as condições pertinentes aos demais entes.","a":true,"why":"A redação atual não autoriza importar uma fórmula histórica única para todo vínculo. Idade, regime e legislação aplicável devem ser identificados. Base: Art. 40, § 1º, III."},{"q":"Toda vantagem do art. 7º é automaticamente aplicável a qualquer vínculo público sem verificar a remissão constitucional.","a":false,"why":"O § 3º enumera direitos para o servidor ocupante de cargo público. Não há importação indistinta de todo o catálogo a qualquer contratação. Base: Art. 39, § 3º."}],"flashcards":[{"f":"Quais são os princípios expressos do art. 37?","b":"Legalidade, impessoalidade, moralidade, publicidade e eficiência."},{"f":"Função de confiança pode ser exercida por qualquer pessoa?","b":"O art. 37, V, exige servidor ocupante de cargo efetivo."},{"f":"Qual é a validade constitucional máxima ordinária do concurso?","b":"Até dois anos, prorrogável uma vez por igual período."},{"f":"Estabilidade é simples tempo em qualquer contratação?","b":"Não. O art. 41 possui destinatários e requisitos próprios, inclusive avaliação."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-administracao-publica-constituicao","subject":"Direito Constitucional","topic_label":"Administração pública constitucional","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"Os princípios expressos do art. 37 alcançam administração direta e indireta de qualquer Poder e dos diferentes entes federativos.","a":true,"why":"Não são exclusivos do Executivo federal. O âmbito constitucional impede reduzir a exigência a um único órgão ou esfera. Base: Art. 37, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, caput","origin":"authored_current_official_source"},{"q":"Eficiência permite afastar toda exigência de legalidade quando a autoridade julga o resultado conveniente.","a":false,"why":"Os princípios devem ser observados em conjunto. Eficiência não cria autorização geral para agir sem competência ou violar direitos. Base: Art. 37, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, caput","origin":"authored_current_official_source"},{"q":"Publicidade de programas públicos não pode caracterizar promoção pessoal de autoridades ou servidores.","a":true,"why":"O caráter educativo, informativo ou de orientação social deve ser preservado. A divulgação institucional não é patrimônio promocional do agente. Base: Art. 37, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, § 1º","origin":"authored_current_official_source"},{"q":"A regra de concurso pode ser afastada para todo cargo permanente apenas porque a administração lhe atribui um nome de confiança.","a":false,"why":"As exceções constitucionais têm condições próprias. Mudar a denominação não dispensa o exame da natureza e das atribuições. Base: Art. 37, II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, II","origin":"authored_current_official_source"},{"q":"Funções de confiança são exercidas exclusivamente por servidores ocupantes de cargo efetivo.","a":true,"why":"A regra não é idêntica à de todo cargo em comissão. É necessário distinguir as duas formas constitucionais de organização. Base: Art. 37, V.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, V","origin":"authored_current_official_source"},{"q":"Cargos em comissão e funções de confiança podem ser destinados indistintamente a qualquer tarefa operacional permanente.","a":false,"why":"A Constituição os destina a direção, chefia e assessoramento. O enunciado elimina a delimitação funcional expressa. Base: Art. 37, V.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, V","origin":"authored_current_official_source"},{"q":"A validade do concurso é de até dois anos e admite uma prorrogação por igual período.","a":true,"why":"O prazo inicial pode ser inferior a dois anos. Não há autorização constitucional para prorrogações sucessivas ilimitadas. Base: Art. 37, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, III","origin":"authored_current_official_source"},{"q":"Um concurso com validade inicial de um ano pode receber, pela mesma regra, três prorrogações de dois anos.","a":false,"why":"O texto prevê uma prorrogação por igual período. O enunciado altera quantidade e duração. Base: Art. 37, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, III","origin":"authored_current_official_source"},{"q":"Contratação por tempo determinado exige hipótese legal de necessidade temporária de excepcional interesse público.","a":true,"why":"Não é substituto genérico de todo concurso. A necessidade e o fundamento precisam corresponder à disciplina constitucional e legal. Base: Art. 37, IX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, IX","origin":"authored_current_official_source"},{"q":"Uma autarquia pode ser criada por simples contrato privado sem lei específica, desde que seja considerada eficiente.","a":false,"why":"O inciso XIX exige lei específica para criação de autarquia. Conveniência administrativa não substitui a espécie normativa. Base: Art. 37, XIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, XIX","origin":"authored_current_official_source"},{"q":"A redação constitucional distingue a criação de autarquia da autorização para instituir empresa pública ou sociedade de economia mista.","a":true,"why":"Não se deve usar a mesma fórmula para toda entidade. A lei específica tem papel distinto conforme a categoria. Base: Art. 37, XIX.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, XIX","origin":"authored_current_official_source"},{"q":"O direito de regresso contra o agente prescinde sempre de dolo ou culpa porque a responsabilidade do Estado é tratada no mesmo parágrafo.","a":false,"why":"O § 6º assegura regresso nos casos de dolo ou culpa. A análise do ente e a do agente não se confundem automaticamente. Base: Art. 37, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, § 6º","origin":"authored_current_official_source"},{"q":"Estabilidade do art. 41 exige os requisitos constitucionais, incluindo três anos de efetivo exercício e avaliação especial de desempenho.","a":true,"why":"A garantia está ligada ao cargo efetivo provido por concurso. Não decorre apenas de passar algum tempo em qualquer contratação pública. Base: Art. 41.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 41","origin":"authored_current_official_source"},{"q":"Qualquer ocupante exclusivamente de cargo em comissão torna-se estável pelo simples decurso de três anos.","a":false,"why":"A garantia do art. 41 tem destinatários e requisitos próprios. Não alcança automaticamente essa hipótese pelo tempo isolado. Base: Art. 41.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 41","origin":"authored_current_official_source"},{"q":"Servidor abrangido pelo art. 38 investido no mandato de prefeito deve afastar-se do cargo, emprego ou função, com a opção de remuneração prevista.","a":true,"why":"O texto distingue essa situação do vereador com compatibilidade. Não se deve usar a mesma solução de acumulação para todo mandato. Base: Art. 38, II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 38, II","origin":"authored_current_official_source"},{"q":"O vereador abrangido pelo art. 38 pode acumular os exercícios independentemente de compatibilidade de horários.","a":false,"why":"A compatibilidade é condição expressa. Se ela não existe, aplica-se a regra constitucional pertinente, não uma dispensa geral. Base: Art. 38, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 38, III","origin":"authored_current_official_source"},{"q":"Após a EC 138/2025, a hipótese de professor com outro cargo de qualquer natureza ainda depende de compatibilidade de horários e das condições constitucionais.","a":true,"why":"A atualização ampliou a natureza do outro cargo, não eliminou todos os limites. O módulo específico de acumulação aprofunda os casos. Base: Art. 37, XVI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, XVI","origin":"authored_current_official_source"},{"q":"A redação atual continua limitando necessariamente o segundo cargo do professor apenas a cargo técnico ou científico.","a":false,"why":"A EC 138/2025 passou a prever outro de qualquer natureza. Repetir a fórmula antiga como regra vigente desatualiza o conteúdo. Base: Art. 37, XVI, b.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 37, XVI, b","origin":"authored_current_official_source"},{"q":"A análise de aposentadoria voluntária no regime próprio precisa distinguir a regra constitucional federal e as condições pertinentes aos demais entes.","a":true,"why":"A redação atual não autoriza importar uma fórmula histórica única para todo vínculo. Idade, regime e legislação aplicável devem ser identificados. Base: Art. 40, § 1º, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 40, § 1º, III","origin":"authored_current_official_source"},{"q":"Toda vantagem do art. 7º é automaticamente aplicável a qualquer vínculo público sem verificar a remissão constitucional.","a":false,"why":"O § 3º enumera direitos para o servidor ocupante de cargo público. Não há importação indistinta de todo o catálogo a qualquer contratação. Base: Art. 39, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 39, § 3º","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"19670b88-37ed-5c63-8a67-45f0f0e891b2","material_slug":"constitucional-administracao-publica-constituicao","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"b8108999e5a6434931635e0c05df4fb91338aef21e9e9b7fa85755d2040ca9ee","content":{"cases":[{"id":"confianca","title":"O nome não dispensa concurso","scenario":"Um órgão dá o nome cargo de confiança a funções operacionais permanentes para afastar qualquer concurso.","question":"A etiqueta resolve a exigência constitucional?","steps":["Identifique as atribuições reais.","Leia a regra de concurso e suas exceções.","Confira a destinação de direção, chefia e assessoramento do art. 37, V."],"conclusion":"Não. A denominação isolada não transforma qualquer tarefa em hipótese válida de comissão ou confiança.","pitfall":"Examinar somente o nome escolhido pela administração.","variation":{"scenario":"A situação envolve função de confiança de direção a ser exercida por servidor efetivo.","answer":"A análise muda para os requisitos próprios dessa função, sem presumir identidade com qualquer comissão."},"articles":["Art. 37, II e V"]},{"id":"vereador","title":"Mandato e horário","scenario":"Servidor abrangido pelo art. 38 assume mandato de vereador, mas seus horários não são compatíveis. Ele usa um resumo que autoriza toda acumulação.","question":"Qual condição constitucional precisa ser examinada?","steps":["Identifique o mandato, evitando confundir prefeito e vereador.","Confira a compatibilidade exigida para vereador.","Na ausência da condição, observe a solução constitucional pertinente em vez de autorizar acumulação irrestrita."],"conclusion":"A possibilidade de manter os exercícios depende dos requisitos do art. 38.","pitfall":"Usar o título vereador como dispensa de compatibilidade.","variation":{"scenario":"Há compatibilidade real de horários.","answer":"A hipótese constitucional de compatibilidade deve ser analisada com a disciplina remuneratória própria, sem eliminar os demais requisitos."},"articles":["Art. 38, III"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"60ae35c3-4e84-5de1-9c03-63db9094b962","slug":"constitucional-judiciario-garantias-carreira","discipline":"Direito Constitucional","topic_label":"Judiciário: garantias e carreira","sort_order":19,"title":"Judiciário: estrutura, garantias e carreira","summary":"Leitura orientada de judiciário: estrutura, garantias e carreira. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Estrutura constitucional\n\nO art. 92 enumera órgãos do Judiciário, incluindo STF, CNJ, tribunais superiores e as estruturas federais e estaduais previstas. O CNJ integra o Judiciário, mas seu controle administrativo e disciplinar não o transforma em instância recursal comum de toda decisão judicial.\n\nFunção jurisdicional e atividades administrativas dos tribunais precisam ser separadas. Os arts. 96 e 99 protegem competências institucionais e autonomia, sem eliminar limites orçamentários e controles constitucionais.\n\n## Carreira e independência\n\n| Garantia | Condição relevante |\n| --- | --- |\n| Vitaliciedade | Em primeiro grau, adquirida após dois anos de exercício; a perda do cargo tem a disciplina constitucional própria |\n| Inamovibilidade | Não é absoluta; o texto prevê hipótese de interesse público com requisitos |\n| Irredutibilidade de subsídio | Tem as ressalvas constitucionais; não é imunidade a toda tributação ou limitação |\n| Ingresso na carreira | Cargo inicial de juiz substituto, concurso de provas e títulos e, entre outros requisitos, três anos de atividade jurídica para bacharel em Direito |\n\nPromoção por antiguidade e merecimento segue requisitos do art. 93. O quinto constitucional do art. 94 não significa reservar um quinto de todo cargo de qualquer tribunal, nem alterar o número constitucional de ministros do STF.\n\n## Vedações e controle\n\nO art. 95 veda atividades que comprometam a independência, incluindo atividade político-partidária e advocacia nas condições e prazos que especifica. A exceção de magistério não autoriza acumular indistintamente qualquer outro cargo público.\n\nA reserva de plenário do art. 97 exige maioria absoluta dos membros do tribunal ou do órgão especial para declaração de inconstitucionalidade de lei ou ato normativo. Não a confunda com a regra geral de qualquer decisão processual.\n\nSúmula vinculante exige o regime do art. 103-A: STF, decisões reiteradas sobre matéria constitucional e aprovação por dois terços dos membros, além dos demais requisitos. Nem toda súmula do STF ou STJ é vinculante.\n\n## Precatórios: não use tabelas históricas\n\nO art. 100 disciplina pagamentos devidos pela Fazenda Pública, distingue preferências e obrigações de pequeno valor e recebeu alterações recentes, inclusive em 2025. Este módulo não reaproveita prazos, índices ou tetos antigos da apostila. Para um cálculo ou execução concreta, é indispensável consultar a redação atual e o regime aplicável ao ente devedor.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"A presença do CNJ entre os órgãos do Judiciário não permite concluir que ele seja um tribunal recursal comum de toda decisão judicial.","a":true,"why":"O Conselho tem competências constitucionais próprias. Pertencer ao Judiciário não significa exercer a mesma função de todos os tribunais. Base: Art. 92."},{"q":"No primeiro grau, o juiz adquire vitaliciedade imediatamente na posse, sem o período constitucional de exercício.","a":false,"why":"O inciso I prevê aquisição após dois anos de exercício no primeiro grau. O regime não deve ser confundido com outras hipóteses de provimento. Base: Art. 95, I."},{"q":"Inamovibilidade não é garantia absolutamente sem exceção, pois a Constituição contempla interesse público nas condições indicadas.","a":true,"why":"É necessário ler a remissão ao art. 93, VIII. Nomear a garantia não elimina o procedimento e os requisitos da exceção. Base: Art. 95, II."},{"q":"Irredutibilidade de subsídio torna o magistrado imune a toda tributação por força dessa garantia isolada.","a":false,"why":"O próprio texto contém ressalvas constitucionais. A garantia remuneratória não cria imunidade tributária universal. Base: Art. 95, III."},{"q":"O ingresso na carreira da magistratura exige, entre os requisitos constitucionais, bacharelado em Direito e três anos de atividade jurídica.","a":true,"why":"O cargo inicial é juiz substituto, com concurso de provas e títulos e as demais condições. Não basta aprovação em qualquer seleção administrativa. Base: Art. 93, I."},{"q":"Três anos de atividade jurídica podem ser substituídos, como regra constitucional expressa, por três meses de qualquer trabalho sem relação jurídica.","a":false,"why":"O requisito constitucional é de três anos de atividade jurídica. A definição e a comprovação devem observar a disciplina pertinente, não uma substituição inventada. Base: Art. 93, I."},{"q":"O quinto constitucional exige analisar os tribunais e requisitos abrangidos, sem estendê-lo automaticamente a todo órgão judicial.","a":true,"why":"O art. 94 tem destinatários específicos. Não é uma regra de um quinto de qualquer cargo no Judiciário. Base: Art. 94."},{"q":"Um quinto das onze vagas do STF deve ser preenchido necessariamente pelo mesmo procedimento do art. 94.","a":false,"why":"A composição do STF tem disciplina própria. A fórmula do quinto não pode ser transportada indistintamente ao Supremo. Base: Art. 94."},{"q":"A exceção constitucional de magistério não autoriza ao juiz exercer livremente qualquer outro cargo público.","a":true,"why":"O dispositivo estabelece vedação e exceção específica. É preciso examinar a atividade, e não tratar a ressalva como permissão geral de acumulação. Base: Art. 95, parágrafo único, I."},{"q":"A Constituição assegura ao juiz a prática de atividade político-partidária como consequência necessária da independência judicial.","a":false,"why":"O texto a veda. Independência funcional não é autorização para ignorar impedimentos constitucionais. Base: Art. 95, parágrafo único, III."},{"q":"A declaração de inconstitucionalidade por tribunal exige o quórum constitucional do plenário ou órgão especial.","a":true,"why":"O art. 97 prevê maioria absoluta. A regra não se resume à maioria dos integrantes presentes de qualquer órgão fracionário. Base: Art. 97."},{"q":"A reserva de plenário significa que todo despacho processual simples precisa ser aprovado pela maioria absoluta de todo o tribunal.","a":false,"why":"A norma tem objeto específico: declaração de inconstitucionalidade nos termos constitucionais. Não universaliza o procedimento para qualquer ato. Base: Art. 97."},{"q":"Súmula vinculante tem requisitos próprios e não se confunde com toda súmula de jurisprudência.","a":true,"why":"A Constituição prevê STF, decisões reiteradas sobre matéria constitucional e aprovação por dois terços, além das demais condições. O nome súmula, sozinho, não basta. Base: Art. 103-A."},{"q":"Qualquer súmula aprovada pelo STJ se torna automaticamente vinculante pelo simples decurso de um ano.","a":false,"why":"O art. 103-A tem disciplina própria e não estabelece essa transformação automática. O enunciado cria órgão e prazo sem fundamento nesse dispositivo. Base: Art. 103-A."},{"q":"A autonomia administrativa e financeira dos tribunais deve ser lida com competências e limites constitucionais, sem presumir orçamento ilimitado.","a":true,"why":"A garantia institucional não elimina regras orçamentárias. É necessário distinguir proposta, execução e controles aplicáveis. Base: Arts. 96 e 99."},{"q":"Autonomia financeira significa que um tribunal pode fixar qualquer despesa sem observar os limites da lei de diretrizes orçamentárias.","a":false,"why":"A elaboração da proposta está sujeita aos limites constitucionais e orçamentários. Autonomia não equivale a ausência de regras. Base: Art. 99."},{"q":"O afastamento do cargo não libera imediatamente o magistrado para advogar no juízo ou tribunal de que se afastou, sem considerar o prazo constitucional.","a":true,"why":"O inciso V prevê três anos nas condições que especifica. Não se deve omitir o âmbito e o marco do afastamento. Base: Art. 95, parágrafo único, V."},{"q":"Uma tabela antiga de precatórios pode ser aplicada como regra atual completa sem conferir alterações constitucionais posteriores.","a":false,"why":"O regime recebeu alterações e exige leitura vigente e identificação do ente e da obrigação. Um quadro histórico não certifica a solução atual. Base: Art. 100."},{"q":"Juizados especiais e justiça de paz têm previsões constitucionais próprias, e não devem ser confundidos apenas porque aparecem no mesmo artigo.","a":true,"why":"O art. 98 distingue suas finalidades e organização. A proximidade textual não torna equivalentes as competências. Base: Art. 98."},{"q":"Vitaliciedade do magistrado em primeiro grau e estabilidade do servidor do art. 41 têm necessariamente o mesmo prazo e os mesmos destinatários.","a":false,"why":"A Constituição estabelece regimes diferentes, inclusive dois anos para vitaliciedade no primeiro grau e três anos nas condições do art. 41. As garantias não são sinônimas. Base: Art. 95, I; Art. 41."}],"flashcards":[{"f":"Vitaliciedade em primeiro grau nasce na posse?","b":"Não. O art. 95, I, prevê dois anos de exercício."},{"f":"Quinto constitucional se aplica automaticamente ao STF?","b":"Não. A composição e o procedimento do STF são próprios."},{"f":"Qual é o quórum da reserva de plenário?","b":"Maioria absoluta dos membros do tribunal ou do órgão especial, no âmbito do art. 97."},{"f":"Toda súmula é vinculante?","b":"Não. O art. 103-A estabelece regime próprio para súmula vinculante."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-judiciario-garantias-carreira","subject":"Direito Constitucional","topic_label":"Judiciário: garantias e carreira","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"A presença do CNJ entre os órgãos do Judiciário não permite concluir que ele seja um tribunal recursal comum de toda decisão judicial.","a":true,"why":"O Conselho tem competências constitucionais próprias. Pertencer ao Judiciário não significa exercer a mesma função de todos os tribunais. Base: Art. 92.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 92","origin":"authored_current_official_source"},{"q":"No primeiro grau, o juiz adquire vitaliciedade imediatamente na posse, sem o período constitucional de exercício.","a":false,"why":"O inciso I prevê aquisição após dois anos de exercício no primeiro grau. O regime não deve ser confundido com outras hipóteses de provimento. Base: Art. 95, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 95, I","origin":"authored_current_official_source"},{"q":"Inamovibilidade não é garantia absolutamente sem exceção, pois a Constituição contempla interesse público nas condições indicadas.","a":true,"why":"É necessário ler a remissão ao art. 93, VIII. Nomear a garantia não elimina o procedimento e os requisitos da exceção. Base: Art. 95, II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 95, II","origin":"authored_current_official_source"},{"q":"Irredutibilidade de subsídio torna o magistrado imune a toda tributação por força dessa garantia isolada.","a":false,"why":"O próprio texto contém ressalvas constitucionais. A garantia remuneratória não cria imunidade tributária universal. Base: Art. 95, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 95, III","origin":"authored_current_official_source"},{"q":"O ingresso na carreira da magistratura exige, entre os requisitos constitucionais, bacharelado em Direito e três anos de atividade jurídica.","a":true,"why":"O cargo inicial é juiz substituto, com concurso de provas e títulos e as demais condições. Não basta aprovação em qualquer seleção administrativa. Base: Art. 93, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 93, I","origin":"authored_current_official_source"},{"q":"Três anos de atividade jurídica podem ser substituídos, como regra constitucional expressa, por três meses de qualquer trabalho sem relação jurídica.","a":false,"why":"O requisito constitucional é de três anos de atividade jurídica. A definição e a comprovação devem observar a disciplina pertinente, não uma substituição inventada. Base: Art. 93, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 93, I","origin":"authored_current_official_source"},{"q":"O quinto constitucional exige analisar os tribunais e requisitos abrangidos, sem estendê-lo automaticamente a todo órgão judicial.","a":true,"why":"O art. 94 tem destinatários específicos. Não é uma regra de um quinto de qualquer cargo no Judiciário. Base: Art. 94.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 94","origin":"authored_current_official_source"},{"q":"Um quinto das onze vagas do STF deve ser preenchido necessariamente pelo mesmo procedimento do art. 94.","a":false,"why":"A composição do STF tem disciplina própria. A fórmula do quinto não pode ser transportada indistintamente ao Supremo. Base: Art. 94.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 94","origin":"authored_current_official_source"},{"q":"A exceção constitucional de magistério não autoriza ao juiz exercer livremente qualquer outro cargo público.","a":true,"why":"O dispositivo estabelece vedação e exceção específica. É preciso examinar a atividade, e não tratar a ressalva como permissão geral de acumulação. Base: Art. 95, parágrafo único, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 95, parágrafo único, I","origin":"authored_current_official_source"},{"q":"A Constituição assegura ao juiz a prática de atividade político-partidária como consequência necessária da independência judicial.","a":false,"why":"O texto a veda. Independência funcional não é autorização para ignorar impedimentos constitucionais. Base: Art. 95, parágrafo único, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 95, parágrafo único, III","origin":"authored_current_official_source"},{"q":"A declaração de inconstitucionalidade por tribunal exige o quórum constitucional do plenário ou órgão especial.","a":true,"why":"O art. 97 prevê maioria absoluta. A regra não se resume à maioria dos integrantes presentes de qualquer órgão fracionário. Base: Art. 97.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 97","origin":"authored_current_official_source"},{"q":"A reserva de plenário significa que todo despacho processual simples precisa ser aprovado pela maioria absoluta de todo o tribunal.","a":false,"why":"A norma tem objeto específico: declaração de inconstitucionalidade nos termos constitucionais. Não universaliza o procedimento para qualquer ato. Base: Art. 97.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 97","origin":"authored_current_official_source"},{"q":"Súmula vinculante tem requisitos próprios e não se confunde com toda súmula de jurisprudência.","a":true,"why":"A Constituição prevê STF, decisões reiteradas sobre matéria constitucional e aprovação por dois terços, além das demais condições. O nome súmula, sozinho, não basta. Base: Art. 103-A.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-A","origin":"authored_current_official_source"},{"q":"Qualquer súmula aprovada pelo STJ se torna automaticamente vinculante pelo simples decurso de um ano.","a":false,"why":"O art. 103-A tem disciplina própria e não estabelece essa transformação automática. O enunciado cria órgão e prazo sem fundamento nesse dispositivo. Base: Art. 103-A.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-A","origin":"authored_current_official_source"},{"q":"A autonomia administrativa e financeira dos tribunais deve ser lida com competências e limites constitucionais, sem presumir orçamento ilimitado.","a":true,"why":"A garantia institucional não elimina regras orçamentárias. É necessário distinguir proposta, execução e controles aplicáveis. Base: Arts. 96 e 99.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 96 e 99","origin":"authored_current_official_source"},{"q":"Autonomia financeira significa que um tribunal pode fixar qualquer despesa sem observar os limites da lei de diretrizes orçamentárias.","a":false,"why":"A elaboração da proposta está sujeita aos limites constitucionais e orçamentários. Autonomia não equivale a ausência de regras. Base: Art. 99.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 99","origin":"authored_current_official_source"},{"q":"O afastamento do cargo não libera imediatamente o magistrado para advogar no juízo ou tribunal de que se afastou, sem considerar o prazo constitucional.","a":true,"why":"O inciso V prevê três anos nas condições que especifica. Não se deve omitir o âmbito e o marco do afastamento. Base: Art. 95, parágrafo único, V.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 95, parágrafo único, V","origin":"authored_current_official_source"},{"q":"Uma tabela antiga de precatórios pode ser aplicada como regra atual completa sem conferir alterações constitucionais posteriores.","a":false,"why":"O regime recebeu alterações e exige leitura vigente e identificação do ente e da obrigação. Um quadro histórico não certifica a solução atual. Base: Art. 100.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 100","origin":"authored_current_official_source"},{"q":"Juizados especiais e justiça de paz têm previsões constitucionais próprias, e não devem ser confundidos apenas porque aparecem no mesmo artigo.","a":true,"why":"O art. 98 distingue suas finalidades e organização. A proximidade textual não torna equivalentes as competências. Base: Art. 98.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 98","origin":"authored_current_official_source"},{"q":"Vitaliciedade do magistrado em primeiro grau e estabilidade do servidor do art. 41 têm necessariamente o mesmo prazo e os mesmos destinatários.","a":false,"why":"A Constituição estabelece regimes diferentes, inclusive dois anos para vitaliciedade no primeiro grau e três anos nas condições do art. 41. As garantias não são sinônimas. Base: Art. 95, I; Art. 41.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 95, I; Art. 41","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"0d30d9d9-cc99-58db-b4a8-a36a7babd917","material_slug":"constitucional-judiciario-garantias-carreira","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"b2cd0bb93f9bdce79b14c96d8d6dbcacf0bfb95e627f0a7cf12ecebb07742a53","content":{"cases":[{"id":"garantias","title":"Estabilidade não é vitaliciedade","scenario":"Um esquema dá ao juiz de primeiro grau o prazo de três anos do servidor do art. 41 e chama as duas garantias de idênticas.","question":"Como separar os regimes?","steps":["Identifique o destinatário de cada dispositivo.","Leia os dois anos para vitaliciedade em primeiro grau.","Compare com três anos e demais condições da estabilidade do art. 41."],"conclusion":"Os regimes são distintos e não podem ser unificados apenas pelo objetivo de proteção funcional.","pitfall":"Transferir o prazo de uma carreira a outra sem ler a regra própria.","variation":{"scenario":"O enunciado passa a discutir servidor nomeado em cargo efetivo por concurso.","answer":"Agora a análise do art. 41 é pertinente, inclusive avaliação e demais condições; não se aplica vitaliciedade judicial."},"articles":["Art. 95, I","Art. 41"]},{"id":"vinculante","title":"Nem toda súmula vincula","scenario":"Um interessado chama uma súmula comum de vinculante apenas porque foi publicada por tribunal superior.","question":"O nome tribunal superior supre o art. 103-A?","steps":["Identifique o órgão que editou o enunciado.","Confira a natureza vinculante e os requisitos constitucionais.","Não transforme publicação ou repetição de decisões em equivalência automática ao procedimento próprio."],"conclusion":"Não. Súmula vinculante tem disciplina constitucional específica.","pitfall":"Tratar toda jurisprudência consolidada como enunciado vinculante do art. 103-A.","variation":{"scenario":"O STF aprova enunciado pelo procedimento constitucional, com os requisitos cabíveis.","answer":"A natureza vinculante pode então ser examinada a partir desses requisitos, e não do rótulo informal do interessado."},"articles":["Art. 103-A"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"01053ec7-48f5-56a3-b1cc-65dd24d35f09","slug":"constitucional-tribunais-competencias-cnj","discipline":"Direito Constitucional","topic_label":"Tribunais: composição e competências","sort_order":20,"title":"Tribunais e CNJ: composição, competências e controle","summary":"Leitura orientada de tribunais e cnj: composição, competências e controle. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Composição não é competência\n\n| Órgão | Referência constitucional atual |\n| --- | --- |\n| STF | Onze ministros; art. 101; guarda da Constituição no art. 102 |\n| STJ | No mínimo 33 ministros; arts. 104 e 105 |\n| TST | 27 ministros; art. 111-A |\n| TSE | No mínimo sete membros; art. 119 |\n| STM | Quinze ministros vitalícios; art. 123 |\n| CNJ | Quinze membros; art. 103-B; controle administrativo, financeiro e disciplinar nos termos constitucionais |\n\nAs palavras “no mínimo” importam: não transforme um piso constitucional em número necessariamente fixo.\n\n## Atualização obrigatória: idade de ingresso\n\nA EC 122/2022 alterou o limite superior de idade para ingresso nos tribunais abrangidos. Para STF e STJ, o texto atual exige mais de 35 e menos de 70 anos, além dos demais requisitos. O mesmo recorte etário consta do TST. TRFs e TRTs têm requisitos próprios, inclusive limite inferior diferente: não transporte a tabela de um tribunal para outro.\n\nA regra de escolha não é a idade de aposentadoria compulsória. Também não confunda “menos de 70” com permitir qualquer idade até completar 71.\n\nO cargo de ministro do STF é privativo de brasileiro nato (art. 12, § 3º). A Constituição não impõe essa mesma reserva de nacionalidade originária a todo ministro de todo tribunal.\n\n## Recursos e competência originária\n\nComece identificando o objeto e as partes, depois o órgão competente e a espécie processual. Competência originária não é sinônimo de competência recursal. O recurso extraordinário do art. 102 tem recorte constitucional; o especial do art. 105 tem hipóteses próprias relacionadas à lei federal. Não são uma terceira apelação indistinta.\n\n## CNJ: controle com âmbito definido\n\nO CNJ é presidido pelo presidente do STF e, em suas ausências e impedimentos, pelo vice-presidente do STF. O corregedor nacional é o ministro do STJ que integra o Conselho. O mandato constitucional dos membros é de dois anos, admitida uma recondução, observadas as regras pertinentes à composição.\n\nO Conselho pode apreciar a legalidade de atos administrativos e o cumprimento dos deveres funcionais nos termos do art. 103-B. Não pode ser descrito como órgão que substitui livremente o juiz na solução do mérito de qualquer processo. A presença de advogados e cidadãos na composição também impede chamá-lo de órgão composto exclusivamente por magistrados.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Uma tabela atual de ingresso no STF deve indicar onze ministros e idade superior a 35 e inferior a 70 anos, sem confundir ingresso com aposentadoria.","a":true,"why":"A EC 122 alterou o limite superior de ingresso. Os demais requisitos e o procedimento de escolha também devem ser observados. Base: Art. 101."},{"q":"A idade máxima de ingresso no STF continua necessariamente inferior a 65 anos, conforme a redação vigente.","a":false,"why":"A redação atual exige menos de 70. Manter 65 como limite vigente reproduz informação superada. Base: Art. 101."},{"q":"Ao estudar a composição do STF, a reserva do cargo de ministro a brasileiro nato deve acompanhar os requisitos do art. 101.","a":true,"why":"Não basta consultar somente o artigo de composição. A regra de nacionalidade está em outro ponto da Constituição. Base: Art. 12, § 3º, IV."},{"q":"O STJ tem constitucionalmente apenas 27 ministros, número fixado no mesmo artigo de composição do TST.","a":false,"why":"O STJ tem no mínimo 33 ministros. O TST possui disciplina e número próprios no art. 111-A. Base: Art. 104."},{"q":"A expressão no mínimo 33 impede tratar esse número como teto constitucional de ministros do STJ.","a":true,"why":"A escolha das palavras importa. Um piso não se transforma em limite máximo por conveniência de memorização. Base: Art. 104."},{"q":"A Constituição atual fixa o TST em 33 ministros e deixa seu número idêntico ao mínimo do STJ.","a":false,"why":"O TST compõe-se de 27 ministros. Copiar a informação de um tribunal para outro produz erro de composição. Base: Art. 111-A."},{"q":"O TSE tem no mínimo sete membros, com origens constitucionais diferentes entre STF, STJ e advocacia.","a":true,"why":"A composição não é formada exclusivamente por ministros de um único tribunal. O procedimento de escolha também varia conforme a origem. Base: Art. 119."},{"q":"Os sete membros mínimos do TSE são todos escolhidos obrigatoriamente entre ministros do STF.","a":false,"why":"A Constituição prevê três do STF, dois do STJ e dois da advocacia pelo procedimento próprio. O enunciado elimina essa diversidade. Base: Art. 119."},{"q":"O STM tem quinze ministros vitalícios e composição constitucional que distingue militares e civis.","a":true,"why":"Não se deve tratá-lo como órgão composto somente por militares. Os critérios de origem e nomeação constam do art. 123. Base: Art. 123."},{"q":"O CNJ possui quatorze membros e é presidido pelo Procurador-Geral da República.","a":false,"why":"O CNJ tem quinze membros e presidência do presidente do STF. A fórmula apresentada confunde-o com o CNMP. Base: Art. 103-B."},{"q":"A presidência do CNJ cabe ao presidente do STF, com a substituição constitucional pelo vice-presidente do STF em ausências e impedimentos.","a":true,"why":"A regra não entrega a presidência genericamente a qualquer conselheiro escolhido de forma informal. É necessário observar o texto atual. Base: Art. 103-B, § 1º."},{"q":"A função de corregedor nacional no CNJ deve ser exercida obrigatoriamente por um dos cidadãos indicados pela Câmara.","a":false,"why":"A Constituição a atribui ao ministro do STJ que integra o Conselho. As origens dos membros têm funções e requisitos próprios. Base: Art. 103-B, § 5º."},{"q":"A composição do CNJ não é exclusivamente de magistrados, pois inclui outros integrantes previstos na Constituição.","a":true,"why":"Advogados e cidadãos compõem o rol. O nome Conselho de Justiça não autoriza apagar essas categorias. Base: Art. 103-B."},{"q":"O CNJ pode, como instância recursal comum, substituir livremente o mérito de qualquer sentença apenas por discordar do juiz.","a":false,"why":"Suas competências constitucionais de controle não o transformam em recurso universal do mérito jurisdicional. É necessário distinguir ato administrativo e decisão judicial. Base: Art. 103-B, § 4º."},{"q":"Para escolher entre recurso extraordinário e especial, é preciso examinar as hipóteses constitucionais próprias, não apenas a vontade de recorrer mais uma vez.","a":true,"why":"Os recursos têm objetos e condições distintos. Nenhum deles é apelação genérica indiferente à matéria discutida. Base: Arts. 102 e 105."},{"q":"Competência originária e competência recursal são expressões equivalentes e podem ser trocadas sem efeito no enquadramento.","a":false,"why":"A distinção identifica como a causa chega ao órgão. Confundi-las altera a análise do procedimento e da atribuição constitucional. Base: Arts. 102 e 105."},{"q":"Os requisitos etários de TRFs e TRTs devem ser consultados em seus próprios artigos, sem copiar automaticamente o limite inferior do STF.","a":true,"why":"A Constituição estabelece requisitos específicos. A atualização do limite superior não torna todas as faixas idênticas. Base: Art. 107; Art. 115."},{"q":"Menos de setenta anos permite nomear livremente pessoa que já tenha completado setenta e um.","a":false,"why":"A expressão exige idade inferior a setenta no requisito de ingresso. Não pode ser convertida em idade inferior a setenta e dois. Base: Art. 101."},{"q":"O mandato constitucional do CNJ é de dois anos, admitida uma recondução, observadas as regras pertinentes à composição.","a":true,"why":"Não se deve usar essa informação para presumir mandato vitalício de todo conselheiro. A origem de cada membro também deve ser analisada. Base: Art. 103-B."},{"q":"A reserva constitucional de nacionalidade originária do ministro do STF se estende automaticamente a todo ministro de todo tribunal, sem consulta aos dispositivos próprios.","a":false,"why":"O rol constitucional de cargos privativos deve ser observado. Não existe essa extensão automática pelo simples uso do título ministro. Base: Art. 12, § 3º."}],"flashcards":[{"f":"Qual é a faixa etária atual para ingresso no STF?","b":"Mais de 35 e menos de 70 anos, com os demais requisitos constitucionais."},{"f":"STJ tem número necessariamente fixo em 33?","b":"Não. A Constituição diz no mínimo 33 ministros."},{"f":"Quantos membros tem o CNJ e quem o preside?","b":"Quinze; é presidido pelo presidente do STF, com a substituição constitucional."},{"f":"CNJ é recurso universal contra sentenças?","b":"Não. Seu controle administrativo e funcional tem âmbito próprio."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-tribunais-competencias-cnj","subject":"Direito Constitucional","topic_label":"Tribunais: composição e competências","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"Uma tabela atual de ingresso no STF deve indicar onze ministros e idade superior a 35 e inferior a 70 anos, sem confundir ingresso com aposentadoria.","a":true,"why":"A EC 122 alterou o limite superior de ingresso. Os demais requisitos e o procedimento de escolha também devem ser observados. Base: Art. 101.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 101","origin":"authored_current_official_source"},{"q":"A idade máxima de ingresso no STF continua necessariamente inferior a 65 anos, conforme a redação vigente.","a":false,"why":"A redação atual exige menos de 70. Manter 65 como limite vigente reproduz informação superada. Base: Art. 101.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 101","origin":"authored_current_official_source"},{"q":"Ao estudar a composição do STF, a reserva do cargo de ministro a brasileiro nato deve acompanhar os requisitos do art. 101.","a":true,"why":"Não basta consultar somente o artigo de composição. A regra de nacionalidade está em outro ponto da Constituição. Base: Art. 12, § 3º, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 3º, IV","origin":"authored_current_official_source"},{"q":"O STJ tem constitucionalmente apenas 27 ministros, número fixado no mesmo artigo de composição do TST.","a":false,"why":"O STJ tem no mínimo 33 ministros. O TST possui disciplina e número próprios no art. 111-A. Base: Art. 104.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 104","origin":"authored_current_official_source"},{"q":"A expressão no mínimo 33 impede tratar esse número como teto constitucional de ministros do STJ.","a":true,"why":"A escolha das palavras importa. Um piso não se transforma em limite máximo por conveniência de memorização. Base: Art. 104.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 104","origin":"authored_current_official_source"},{"q":"A Constituição atual fixa o TST em 33 ministros e deixa seu número idêntico ao mínimo do STJ.","a":false,"why":"O TST compõe-se de 27 ministros. Copiar a informação de um tribunal para outro produz erro de composição. Base: Art. 111-A.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 111-A","origin":"authored_current_official_source"},{"q":"O TSE tem no mínimo sete membros, com origens constitucionais diferentes entre STF, STJ e advocacia.","a":true,"why":"A composição não é formada exclusivamente por ministros de um único tribunal. O procedimento de escolha também varia conforme a origem. Base: Art. 119.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 119","origin":"authored_current_official_source"},{"q":"Os sete membros mínimos do TSE são todos escolhidos obrigatoriamente entre ministros do STF.","a":false,"why":"A Constituição prevê três do STF, dois do STJ e dois da advocacia pelo procedimento próprio. O enunciado elimina essa diversidade. Base: Art. 119.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 119","origin":"authored_current_official_source"},{"q":"O STM tem quinze ministros vitalícios e composição constitucional que distingue militares e civis.","a":true,"why":"Não se deve tratá-lo como órgão composto somente por militares. Os critérios de origem e nomeação constam do art. 123. Base: Art. 123.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 123","origin":"authored_current_official_source"},{"q":"O CNJ possui quatorze membros e é presidido pelo Procurador-Geral da República.","a":false,"why":"O CNJ tem quinze membros e presidência do presidente do STF. A fórmula apresentada confunde-o com o CNMP. Base: Art. 103-B.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-B","origin":"authored_current_official_source"},{"q":"A presidência do CNJ cabe ao presidente do STF, com a substituição constitucional pelo vice-presidente do STF em ausências e impedimentos.","a":true,"why":"A regra não entrega a presidência genericamente a qualquer conselheiro escolhido de forma informal. É necessário observar o texto atual. Base: Art. 103-B, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-B, § 1º","origin":"authored_current_official_source"},{"q":"A função de corregedor nacional no CNJ deve ser exercida obrigatoriamente por um dos cidadãos indicados pela Câmara.","a":false,"why":"A Constituição a atribui ao ministro do STJ que integra o Conselho. As origens dos membros têm funções e requisitos próprios. Base: Art. 103-B, § 5º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-B, § 5º","origin":"authored_current_official_source"},{"q":"A composição do CNJ não é exclusivamente de magistrados, pois inclui outros integrantes previstos na Constituição.","a":true,"why":"Advogados e cidadãos compõem o rol. O nome Conselho de Justiça não autoriza apagar essas categorias. Base: Art. 103-B.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-B","origin":"authored_current_official_source"},{"q":"O CNJ pode, como instância recursal comum, substituir livremente o mérito de qualquer sentença apenas por discordar do juiz.","a":false,"why":"Suas competências constitucionais de controle não o transformam em recurso universal do mérito jurisdicional. É necessário distinguir ato administrativo e decisão judicial. Base: Art. 103-B, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-B, § 4º","origin":"authored_current_official_source"},{"q":"Para escolher entre recurso extraordinário e especial, é preciso examinar as hipóteses constitucionais próprias, não apenas a vontade de recorrer mais uma vez.","a":true,"why":"Os recursos têm objetos e condições distintos. Nenhum deles é apelação genérica indiferente à matéria discutida. Base: Arts. 102 e 105.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 102 e 105","origin":"authored_current_official_source"},{"q":"Competência originária e competência recursal são expressões equivalentes e podem ser trocadas sem efeito no enquadramento.","a":false,"why":"A distinção identifica como a causa chega ao órgão. Confundi-las altera a análise do procedimento e da atribuição constitucional. Base: Arts. 102 e 105.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 102 e 105","origin":"authored_current_official_source"},{"q":"Os requisitos etários de TRFs e TRTs devem ser consultados em seus próprios artigos, sem copiar automaticamente o limite inferior do STF.","a":true,"why":"A Constituição estabelece requisitos específicos. A atualização do limite superior não torna todas as faixas idênticas. Base: Art. 107; Art. 115.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 107; Art. 115","origin":"authored_current_official_source"},{"q":"Menos de setenta anos permite nomear livremente pessoa que já tenha completado setenta e um.","a":false,"why":"A expressão exige idade inferior a setenta no requisito de ingresso. Não pode ser convertida em idade inferior a setenta e dois. Base: Art. 101.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 101","origin":"authored_current_official_source"},{"q":"O mandato constitucional do CNJ é de dois anos, admitida uma recondução, observadas as regras pertinentes à composição.","a":true,"why":"Não se deve usar essa informação para presumir mandato vitalício de todo conselheiro. A origem de cada membro também deve ser analisada. Base: Art. 103-B.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 103-B","origin":"authored_current_official_source"},{"q":"A reserva constitucional de nacionalidade originária do ministro do STF se estende automaticamente a todo ministro de todo tribunal, sem consulta aos dispositivos próprios.","a":false,"why":"O rol constitucional de cargos privativos deve ser observado. Não existe essa extensão automática pelo simples uso do título ministro. Base: Art. 12, § 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 3º","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"d1d32a57-1326-5000-83cd-a5e04ace4766","material_slug":"constitucional-tribunais-competencias-cnj","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"625653a617b04dd9069067b0aee614cd21419a37d5cb3dd5c612335e90d3d707","content":{"cases":[{"id":"idade","title":"Tabela anterior à EC 122","scenario":"Uma tabela impede candidatura ao STF de pessoa com 67 anos apenas porque o limite superior estaria em 65. Os demais requisitos ainda não foram examinados.","question":"Esse fundamento etário corresponde à redação atual?","steps":["Confira o texto atual do art. 101.","Distinga limite de ingresso e idade de aposentadoria.","Depois examine nacionalidade, demais requisitos e procedimento de escolha."],"conclusion":"Não. O limite superior atual de ingresso é menos de setenta; isso não basta, sozinho, para garantir nomeação.","pitfall":"Usar tabela histórica ou confundir requisito necessário com direito automático ao cargo.","variation":{"scenario":"A pessoa já tem setenta anos completos.","answer":"A condição menos de setenta não está preenchida; a conclusão sobre 67 anos não se estende automaticamente."},"articles":["Art. 101"]},{"id":"cnj","title":"Controle administrativo não é nova apelação","scenario":"Um litigante pede ao CNJ que rejulgue livremente o mérito de uma sentença porque discorda da interpretação do juiz.","question":"O Conselho é instância recursal universal?","steps":["Separe mérito jurisdicional e controle administrativo ou disciplinar.","Leia as competências do art. 103-B.","Identifique a via processual adequada sem criar atribuição não prevista."],"conclusion":"Não. Integrar o Judiciário não faz do CNJ recurso comum contra toda sentença.","pitfall":"Confundir controle de deveres funcionais com substituição geral da função de julgar.","variation":{"scenario":"A reclamação aponta possível irregularidade em ato administrativo do tribunal.","answer":"A natureza do ato mudou e pode exigir exame das competências de controle do Conselho, com os requisitos próprios."},"articles":["Art. 103-B"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"new","material":{"id":"52f20937-863d-598d-8d51-51db2d117b4b","slug":"constitucional-funcoes-essenciais-justica","discipline":"Direito Constitucional","topic_label":"Funções essenciais à Justiça","sort_order":21,"title":"Funções essenciais à Justiça: MP, advocacias e Defensoria","summary":"Leitura orientada de funções essenciais à justiça: mp, advocacias e defensoria. Confira as distinções do texto-base, resolva dois casos com variações e pratique com vinte exercícios comentados. Aprofundamentos já existentes são acessados por links.","body_md":"## Instituições distintas, finalidades distintas\n\n| Instituição | Núcleo constitucional |\n| --- | --- |\n| Ministério Público | Defesa da ordem jurídica, do regime democrático e dos interesses sociais e individuais indisponíveis |\n| Advocacia pública | Representação e consultoria nas esferas e condições constitucionais |\n| Advocacia | Função indispensável à administração da Justiça, com inviolabilidade nos limites legais |\n| Defensoria Pública | Orientação jurídica, promoção dos direitos humanos e defesa judicial e extrajudicial dos necessitados, nos termos constitucionais |\n\nEssas funções não se tornam órgãos jurisdicionais apenas por participarem da Justiça. O Ministério Público não integra o Poder Judiciário, e o advogado público não é defensor universal de qualquer interesse particular.\n\n## Ministério Público: unidade não é chefia nacional única\n\nUnidade, indivisibilidade e independência funcional são princípios do art. 127. O art. 128 distingue MPU e Ministérios Públicos dos estados. O MPU inclui MPF, MPT, MPM e MPDFT. Não existe subordinação de todos os Ministérios Públicos estaduais ao Procurador-Geral da República.\n\nO PGR chefia o MPU e tem o regime de escolha, aprovação pelo Senado e mandato do art. 128, § 1º. Procuradores-gerais estaduais têm disciplina própria: lista tríplice e condições do texto constitucional e da lei respectiva. Não use a mesma fórmula para todos os chefes.\n\n## CNMP e garantias\n\nO CNMP tem quatorze membros e é presidido pelo PGR, segundo o art. 130-A. Não confunda com os quinze membros do CNJ e sua presidência pelo presidente do STF. O controle administrativo, financeiro e funcional não converte o Conselho em tribunal de recursos judiciais.\n\nGarantias e vedações dos membros do MP devem ser lidas em conjunto. A independência funcional não autoriza descumprir a Constituição, ignorar atribuições ou praticar atividade político-partidária vedada.\n\n## AGU e Defensoria\n\nA AGU representa a União judicial e extrajudicialmente e exerce consultoria e assessoramento jurídico do Executivo conforme a disciplina constitucional. O advogado-geral é de livre nomeação presidencial dentre cidadãos com os requisitos do art. 131, § 1º; não se presume exigência de ser integrante da carreira ou aprovação pelo Senado.\n\nA Defensoria tem atuação individual e coletiva, judicial e extrajudicial. O art. 134 estabelece autonomia e princípios institucionais; não a reduza à defesa criminal ou à representação do governo. Garantia de assistência jurídica integral aos que comprovem insuficiência de recursos não é sinônimo de toda ação ser automaticamente gratuita para qualquer pessoa.\n","contest_name":"Polícia Civil do Piauí — Delegado de Polícia Civil — 2026","syllabus_topic_order":2,"source_note":"Elaboração própria, sem reprodução da redação, exercícios ou diagramação das apostilas. Fontes oficiais consultadas em 24/10/2026; confira o recorte nos links. Vínculo curricular: edital PCPI Delegado cadastrado. Aplicação em outros concursos depende do edital e da data de corte. Exercícios de fixação não são novas questões do catálogo global.","legal_basis":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"law_version_checked_at":"2026-10-24T20:54:33.563025+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00","quiz":[{"q":"Defesa da ordem jurídica, do regime democrático e dos interesses sociais e individuais indisponíveis integra o núcleo constitucional do Ministério Público.","a":true,"why":"Não se reduz a instituição à acusação criminal. O art. 127 descreve funções mais amplas e finalidade própria. Base: Art. 127."},{"q":"O Ministério Público integra o Poder Judiciário porque atua em processos e é essencial à Justiça.","a":false,"why":"Participar da Justiça não o torna órgão jurisdicional do rol do art. 92. A Constituição trata a instituição em capítulo próprio. Base: Arts. 92 e 127."},{"q":"Unidade, indivisibilidade e independência funcional devem ser estudadas como princípios institucionais do MP.","a":true,"why":"O conjunto não autoriza ignorar atribuições ou concluir que todos os membros se subordinam a uma única chefia nacional. Base: Art. 127, § 1º."},{"q":"Todos os Ministérios Públicos estaduais são órgãos hierarquicamente subordinados ao Procurador-Geral da República.","a":false,"why":"O art. 128 distingue MPU e MPs dos estados. O PGR chefia o MPU, não é chefe administrativo de todos os MPs estaduais. Base: Art. 128."},{"q":"O MPU inclui Ministério Público Federal, do Trabalho, Militar e do Distrito Federal e Territórios.","a":true,"why":"Não se deve excluir o MPDFT apenas por ele atuar no Distrito Federal. A localização não altera a enumeração constitucional. Base: Art. 128, I."},{"q":"O PGR é escolhido sem aprovação do Senado e recebe mandato constitucional vitalício.","a":false,"why":"Há aprovação por maioria absoluta do Senado e mandato de dois anos, permitida recondução. O enunciado altera duas condições centrais. Base: Art. 128, § 1º."},{"q":"A escolha do PGR e a dos procuradores-gerais estaduais não devem ser explicadas por uma única fórmula indiferenciada.","a":true,"why":"Os dispositivos estabelecem procedimentos próprios, incluindo diferenças de lista e aprovação. Identifique a chefia antes de aplicar a regra. Base: Art. 128, §§ 1º e 3º."},{"q":"O CNMP tem quinze membros e é presidido pelo presidente do STF, como se fosse o mesmo órgão do CNJ.","a":false,"why":"O CNMP tem quatorze membros e presidência do PGR. A proximidade de siglas não elimina suas diferenças constitucionais. Base: Art. 130-A."},{"q":"O controle administrativo, financeiro e de deveres funcionais do CNMP possui âmbito constitucional próprio.","a":true,"why":"Não é correto descrevê-lo como tribunal de recursos judiciais de todo processo em que o MP participe. É preciso identificar o ato controlado. Base: Art. 130-A."},{"q":"Independência funcional permite ao membro do MP exercer atividade político-partidária mesmo diante da vedação constitucional.","a":false,"why":"A garantia convive com vedações expressas. Independência não equivale a dispensa das regras constitucionais da instituição. Base: Art. 128, § 5º, II."},{"q":"A AGU representa a União judicial e extrajudicialmente e exerce consultoria e assessoramento do Executivo nos termos constitucionais.","a":true,"why":"As funções não significam representação particular indiscriminada de qualquer pessoa. O âmbito institucional precisa ser preservado. Base: Art. 131."},{"q":"A Constituição exige que o advogado-geral da União seja obrigatoriamente ministro do STF antes de sua nomeação.","a":false,"why":"O § 1º prevê livre nomeação presidencial entre cidadãos com os requisitos indicados. Não contém a condição inventada de ser ministro do Supremo. Base: Art. 131, § 1º."},{"q":"Não se deve presumir aprovação pelo Senado para o advogado-geral da União apenas por esse requisito existir em outras autoridades.","a":true,"why":"O dispositivo de escolha tem disciplina própria. Transferir uma regra de outro cargo sem fundamento gera erro. Base: Art. 131, § 1º."},{"q":"A inviolabilidade do advogado constitui autorização irrestrita para qualquer conduta, fora dos limites legais e da atividade profissional.","a":false,"why":"O art. 133 contém referência aos limites da lei. A garantia não é imunidade absoluta para todo comportamento pessoal. Base: Art. 133."},{"q":"A Defensoria Pública tem atuação constitucional individual e coletiva, judicial e extrajudicial.","a":true,"why":"Reduzi-la à defesa penal elimina parte de sua missão. Orientação jurídica e promoção de direitos humanos também integram o texto. Base: Art. 134."},{"q":"A finalidade constitucional da Defensoria é representar a União em qualquer cobrança tributária, substituindo integralmente a advocacia pública.","a":false,"why":"As instituições têm funções distintas. A Defensoria atua na proteção dos necessitados nas condições constitucionais, não como substituta genérica da AGU. Base: Art. 134."},{"q":"A autonomia e os princípios institucionais da Defensoria precisam ser considerados na análise de sua organização.","a":true,"why":"Não é adequado tratá-la como atividade privada informal ou subordiná-la sem exame às regras de outra instituição. Base: Art. 134, §§ 2º a 4º."},{"q":"A assistência jurídica integral e gratuita exige concluir que toda pessoa, em qualquer situação econômica, tem automaticamente toda demanda custeada.","a":false,"why":"O inciso LXXIV se refere aos que comprovarem insuficiência de recursos. A garantia não deve ser ampliada sem considerar seu recorte e a disciplina aplicável. Base: Art. 5º, LXXIV."},{"q":"Vitaliciedade, inamovibilidade e irredutibilidade dos membros do MP possuem requisitos e ressalvas constitucionais.","a":true,"why":"Não se deve interpretar o nome da garantia como dispensa de responsabilidade ou proibição absoluta de qualquer medida constitucionalmente prevista. Base: Art. 128, § 5º."},{"q":"CNMP e CNJ são o mesmo colegiado, com nome variável conforme o processo discutido.","a":false,"why":"São conselhos distintos, com composição, presidência e atribuições próprias. A matéria controlada não transforma um no outro. Base: Art. 130-A; Art. 103-B."}],"flashcards":[{"f":"O PGR chefia todos os MPs estaduais?","b":"Não. Ele chefia o MPU; a estrutura dos MPs estaduais é distinta."},{"f":"CNMP e CNJ têm a mesma composição?","b":"Não. CNMP: 14 membros e presidência do PGR. CNJ: 15 e presidência do presidente do STF."},{"f":"A AGU tem a mesma finalidade da Defensoria?","b":"Não. Representação da União e defesa dos necessitados são missões diferentes."},{"f":"Defensoria atua só em processos penais?","b":"Não. A Constituição prevê proteção individual e coletiva, judicial e extrajudicial."}],"practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-funcoes-essenciais-justica","subject":"Direito Constitucional","topic_label":"Funções essenciais à Justiça","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Fixação autoral do recorte indicado, com dispositivos oficiais conferidos e tópico da edição PCPI Delegado cadastrada. Não são questões da editora ou da banca; a conferência atual não altera o corte temporal de provas históricas. Casos são hipotéticos e não certificam auditoria integral de jurisprudência.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"Defesa da ordem jurídica, do regime democrático e dos interesses sociais e individuais indisponíveis integra o núcleo constitucional do Ministério Público.","a":true,"why":"Não se reduz a instituição à acusação criminal. O art. 127 descreve funções mais amplas e finalidade própria. Base: Art. 127.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 127","origin":"authored_current_official_source"},{"q":"O Ministério Público integra o Poder Judiciário porque atua em processos e é essencial à Justiça.","a":false,"why":"Participar da Justiça não o torna órgão jurisdicional do rol do art. 92. A Constituição trata a instituição em capítulo próprio. Base: Arts. 92 e 127.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Arts. 92 e 127","origin":"authored_current_official_source"},{"q":"Unidade, indivisibilidade e independência funcional devem ser estudadas como princípios institucionais do MP.","a":true,"why":"O conjunto não autoriza ignorar atribuições ou concluir que todos os membros se subordinam a uma única chefia nacional. Base: Art. 127, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 127, § 1º","origin":"authored_current_official_source"},{"q":"Todos os Ministérios Públicos estaduais são órgãos hierarquicamente subordinados ao Procurador-Geral da República.","a":false,"why":"O art. 128 distingue MPU e MPs dos estados. O PGR chefia o MPU, não é chefe administrativo de todos os MPs estaduais. Base: Art. 128.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 128","origin":"authored_current_official_source"},{"q":"O MPU inclui Ministério Público Federal, do Trabalho, Militar e do Distrito Federal e Territórios.","a":true,"why":"Não se deve excluir o MPDFT apenas por ele atuar no Distrito Federal. A localização não altera a enumeração constitucional. Base: Art. 128, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 128, I","origin":"authored_current_official_source"},{"q":"O PGR é escolhido sem aprovação do Senado e recebe mandato constitucional vitalício.","a":false,"why":"Há aprovação por maioria absoluta do Senado e mandato de dois anos, permitida recondução. O enunciado altera duas condições centrais. Base: Art. 128, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 128, § 1º","origin":"authored_current_official_source"},{"q":"A escolha do PGR e a dos procuradores-gerais estaduais não devem ser explicadas por uma única fórmula indiferenciada.","a":true,"why":"Os dispositivos estabelecem procedimentos próprios, incluindo diferenças de lista e aprovação. Identifique a chefia antes de aplicar a regra. Base: Art. 128, §§ 1º e 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 128, §§ 1º e 3º","origin":"authored_current_official_source"},{"q":"O CNMP tem quinze membros e é presidido pelo presidente do STF, como se fosse o mesmo órgão do CNJ.","a":false,"why":"O CNMP tem quatorze membros e presidência do PGR. A proximidade de siglas não elimina suas diferenças constitucionais. Base: Art. 130-A.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 130-A","origin":"authored_current_official_source"},{"q":"O controle administrativo, financeiro e de deveres funcionais do CNMP possui âmbito constitucional próprio.","a":true,"why":"Não é correto descrevê-lo como tribunal de recursos judiciais de todo processo em que o MP participe. É preciso identificar o ato controlado. Base: Art. 130-A.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 130-A","origin":"authored_current_official_source"},{"q":"Independência funcional permite ao membro do MP exercer atividade político-partidária mesmo diante da vedação constitucional.","a":false,"why":"A garantia convive com vedações expressas. Independência não equivale a dispensa das regras constitucionais da instituição. Base: Art. 128, § 5º, II.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 128, § 5º, II","origin":"authored_current_official_source"},{"q":"A AGU representa a União judicial e extrajudicialmente e exerce consultoria e assessoramento do Executivo nos termos constitucionais.","a":true,"why":"As funções não significam representação particular indiscriminada de qualquer pessoa. O âmbito institucional precisa ser preservado. Base: Art. 131.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 131","origin":"authored_current_official_source"},{"q":"A Constituição exige que o advogado-geral da União seja obrigatoriamente ministro do STF antes de sua nomeação.","a":false,"why":"O § 1º prevê livre nomeação presidencial entre cidadãos com os requisitos indicados. Não contém a condição inventada de ser ministro do Supremo. Base: Art. 131, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 131, § 1º","origin":"authored_current_official_source"},{"q":"Não se deve presumir aprovação pelo Senado para o advogado-geral da União apenas por esse requisito existir em outras autoridades.","a":true,"why":"O dispositivo de escolha tem disciplina própria. Transferir uma regra de outro cargo sem fundamento gera erro. Base: Art. 131, § 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 131, § 1º","origin":"authored_current_official_source"},{"q":"A inviolabilidade do advogado constitui autorização irrestrita para qualquer conduta, fora dos limites legais e da atividade profissional.","a":false,"why":"O art. 133 contém referência aos limites da lei. A garantia não é imunidade absoluta para todo comportamento pessoal. Base: Art. 133.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 133","origin":"authored_current_official_source"},{"q":"A Defensoria Pública tem atuação constitucional individual e coletiva, judicial e extrajudicial.","a":true,"why":"Reduzi-la à defesa penal elimina parte de sua missão. Orientação jurídica e promoção de direitos humanos também integram o texto. Base: Art. 134.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 134","origin":"authored_current_official_source"},{"q":"A finalidade constitucional da Defensoria é representar a União em qualquer cobrança tributária, substituindo integralmente a advocacia pública.","a":false,"why":"As instituições têm funções distintas. A Defensoria atua na proteção dos necessitados nas condições constitucionais, não como substituta genérica da AGU. Base: Art. 134.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 134","origin":"authored_current_official_source"},{"q":"A autonomia e os princípios institucionais da Defensoria precisam ser considerados na análise de sua organização.","a":true,"why":"Não é adequado tratá-la como atividade privada informal ou subordiná-la sem exame às regras de outra instituição. Base: Art. 134, §§ 2º a 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 134, §§ 2º a 4º","origin":"authored_current_official_source"},{"q":"A assistência jurídica integral e gratuita exige concluir que toda pessoa, em qualquer situação econômica, tem automaticamente toda demanda custeada.","a":false,"why":"O inciso LXXIV se refere aos que comprovarem insuficiência de recursos. A garantia não deve ser ampliada sem considerar seu recorte e a disciplina aplicável. Base: Art. 5º, LXXIV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 5º, LXXIV","origin":"authored_current_official_source"},{"q":"Vitaliciedade, inamovibilidade e irredutibilidade dos membros do MP possuem requisitos e ressalvas constitucionais.","a":true,"why":"Não se deve interpretar o nome da garantia como dispensa de responsabilidade ou proibição absoluta de qualquer medida constitucionalmente prevista. Base: Art. 128, § 5º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 128, § 5º","origin":"authored_current_official_source"},{"q":"CNMP e CNJ são o mesmo colegiado, com nome variável conforme o processo discutido.","a":false,"why":"São conselhos distintos, com composição, presidência e atribuições próprias. A matéria controlada não transforma um no outro. Base: Art. 130-A; Art. 103-B.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 130-A; Art. 103-B","origin":"authored_current_official_source"}]},"legal_review":{"checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Conferência restrita aos dispositivos e precedentes utilizados neste módulo. Não afirma revisão integral de cada diploma nem de toda a jurisprudência. Elaboração assistida delegada pelo responsável de publicação.","sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d"}],"changes":[],"corrections":["Texto antigo não foi importado automaticamente; a redação foi reconstruída a partir das fontes oficiais indicadas."]}},"enrichment":{"id":"0d8e3ee2-51a8-5ae2-b234-edc85454638c","material_slug":"constitucional-funcoes-essenciais-justica","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"4a4ab0bffcad8eed34a8463b63310c2d040d3cec22888d96093f2fccc19c2a07","content":{"cases":[{"id":"chefia","title":"MP estadual e PGR","scenario":"Um organograma coloca todos os Ministérios Públicos estaduais como departamentos subordinados ao PGR.","question":"O princípio da unidade impõe essa chefia nacional única?","steps":["Leia a distinção entre MPU e MPs estaduais.","Identifique a chefia do MPU no art. 128.","Não converta unidade institucional em hierarquia inexistente entre instituições distintas."],"conclusion":"Não. O organograma confunde a estrutura constitucional dos Ministérios Públicos.","pitfall":"Usar unidade como sinônimo de subordinação de todo MP ao PGR.","variation":{"scenario":"O órgão indicado é o MPDFT.","answer":"Ele integra o MPU conforme enumeração constitucional; a estrutura deve ser identificada antes de generalizar pelo local de atuação."},"articles":["Art. 128"]},{"id":"instituicao","title":"Quem representa quem?","scenario":"Uma pessoa afirma que Defensoria e AGU são equivalentes e devem representar indistintamente qualquer interesse do governo ou de um particular.","question":"Quais finalidades precisam ser separadas?","steps":["Identifique representação da União e consultoria do Executivo.","Compare com orientação e defesa dos necessitados pela Defensoria.","Considere atuação judicial e extrajudicial nos respectivos âmbitos."],"conclusion":"As instituições têm missões distintas, e a condição de essenciais à Justiça não as torna intercambiáveis.","pitfall":"Escolher a instituição apenas por ambas contarem com profissionais do Direito.","variation":{"scenario":"A controvérsia é sobre defesa coletiva de necessitados.","answer":"A análise deve considerar a missão constitucional ampla da Defensoria, que não se limita à defesa criminal individual."},"articles":["Art. 131","Art. 134"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Identifique o problema antes de escolher a regra e teste a mudança de um fato.","nodes":["Identificar o direito e os fatos","Localizar o dispositivo e suas condições","Aplicar sem trocar categorias","Reavaliar se os fatos mudarem"]}]},"sources":[{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"update","expected_material":{"id":"7d517d28-2e6e-503d-b72f-bc7421d6d492","quiz":[{"a":false,"q":"Uma comissão propõe chamar de “soberania municipal” a competência de um município para elaborar sua lei orgânica. Essa denominação descreve corretamente o vínculo constitucional do município.","why":"O município é autônomo, não soberano. A elaboração da lei orgânica expressa autonomia de organização; a soberania é fundamento da República Federativa do Brasil. Exemplo: o município organiza sua atuação dentro dos limites constitucionais, sem se tornar país independente. Base: CF, Art. 1º; Art. 18."},{"a":true,"q":"Em uma ficha de revisão, a linha “distribuição territorial do poder político” deve ser associada à Federação, enquanto a linha “forma de governo brasileira” deve ser associada à República.","why":"As categorias respondem a perguntas diferentes. Exemplo: escrever “república” como forma de Estado troca a organização do governo pela distribuição territorial do poder. Base: CF, Art. 1º; Art. 18."},{"a":false,"q":"Dois estados pretendem incorporar-se entre si. Como a Constituição afirma que a Federação é indissolúvel, qualquer incorporação interna é proibida, mesmo quando cumpridas as condições constitucionais.","why":"O art. 18, § 3º, admite reorganizações internas sob condições próprias. É necessário distinguir incorporação dentro do Brasil de separação para formar um país independente. Base: CF, Art. 18, § 3º."},{"a":false,"q":"Um plebiscito local favorável basta para que um estado deixe o Brasil e se torne país independente, pois autonomia inclui direito unilateral de secessão.","why":"O vínculo federativo é indissolúvel. O plebiscito previsto para reorganização interna não é autorização para romper o país. Mesmo no rearranjo interno existem outras condições, como lei complementar do Congresso Nacional. Base: CF, Art. 1º; Art. 18, § 3º."},{"a":true,"q":"Ao revisar um organograma, a estudante retira “Territórios Federais” da lista de entes autônomos e os posiciona como integrantes da União. A correção corresponde ao art. 18.","why":"O caput enumera União, estados, Distrito Federal e municípios como autônomos; o § 2º dispõe que os territórios integram a União. Não se cria uma quinta categoria de ente federativo autônomo. Base: CF, Art. 18, § 2º."},{"a":false,"q":"Um projeto prevê dividir o Distrito Federal em municípios, justificando que isso seria simples exercício de sua autonomia. A justificativa afasta a vedação constitucional.","why":"O art. 32 veda expressamente a divisão do Distrito Federal em municípios. Autonomia não permite contrariar essa restrição; a organização distrital tem disciplina constitucional própria. Base: CF, Art. 32."},{"a":true,"q":"Uma constituição estadual pode organizar o estado, mas não pode afastar os princípios impostos pela Constituição Federal sob o argumento de que ambos os textos têm a mesma liberdade de criação.","why":"O art. 25 condiciona a organização estadual aos princípios da Constituição Federal. A capacidade de auto-organização não equivale a poder constituinte originário soberano. Base: CF, Art. 25."},{"a":false,"q":"Para demonstrar autonomia municipal, o enunciado afirma que o município deve se reger por uma constituição municipal promulgada pelo governador. A descrição está correta.","why":"O município se rege por lei orgânica aprovada e promulgada pela Câmara Municipal, com as condições do art. 29. Não é constituição estadual nem ato do governador. Base: CF, Art. 29."},{"a":true,"q":"Em um resumo, a União aparece como um ente da organização político-administrativa, e não como sinônimo de toda a República Federativa do Brasil. Essa distinção evita confundir organização interna e Estado brasileiro.","why":"O art. 18 inclui a União ao lado de estados, Distrito Federal e municípios. A República Federativa do Brasil compreende o conjunto da organização, não apenas esse ente. Base: CF, Art. 18."},{"a":false,"q":"Uma proposta declara expressamente extinguir a forma federativa. Se atingir três quintos dos votos em dois turnos de cada Casa, o quórum supera a limitação material constitucional.","why":"Cumprir o procedimento não afasta uma cláusula pétrea. O § 4º impede deliberar proposta tendente a abolir a forma federativa; quórum qualificado não transforma o conteúdo proibido em conteúdo permitido. Base: CF, Art. 60, § 4º, I."},{"a":true,"q":"A proteção da forma federativa não permite concluir que toda alteração pontual de competência entre entes seja automaticamente proibida. É preciso examinar se a proposta tende a abolir essa forma de Estado.","why":"A Constituição protege contra a abolição, sem petrificar indistintamente cada regra de organização. Exemplo: avaliar uma modificação de competência exige analisar seu conteúdo e efeito, não apenas sua existência. Base: CF, Art. 60, § 4º, I."},{"a":false,"q":"Ao constatar que “forma republicana” não está escrita literalmente no rol do § 4º, um candidato conclui que uma emenda pode, sem examinar mais nada, eliminar eleições periódicas e instituir cargo político hereditário.","why":"A conclusão ignora limites expressos, como a proteção do voto direto, secreto, universal e periódico. A ausência de uma expressão na lista não dispensa examinar as demais garantias constitucionais. Base: CF, Art. 60, § 4º."},{"a":true,"q":"Para explicar a relação entre república e controle, um quadro associa a forma republicana à prestação de contas da administração, ambas protegidas no art. 34, VII.","why":"O dispositivo contém esses princípios em alíneas distintas. Exemplo: a eleição de um governante não elimina a exigência de prestar contas sobre a administração pública. Base: CF, Art. 34, VII, a e d."},{"a":false,"q":"Um governante afirma que vencer uma eleição elimina qualquer responsabilidade por atos que atentem contra a Constituição. Essa consequência decorre do princípio republicano.","why":"A Constituição prevê responsabilização, incluindo crimes de responsabilidade do Presidente no art. 85. Legitimidade eleitoral não cria imunidade absoluta nem coloca o governante acima da Constituição. Base: CF, Art. 85."},{"a":true,"q":"Um material que explique a origem popular do poder somente pela eleição de representantes está incompleto se excluir toda possibilidade de exercício direto prevista na Constituição.","why":"O parágrafo único contempla representantes eleitos ou exercício direto, nos termos constitucionais. Isso não significa que qualquer decisão popular, sem observar tais termos, produza todo efeito pretendido. Base: CF, Art. 1º, parágrafo único."},{"a":false,"q":"Em uma tabela, “presidencialismo” é indicado como forma de Estado e “Federação” como sistema de governo. As duas classificações estão corretas.","why":"As posições estão invertidas: Federação é forma de Estado; presidencialismo é sistema de governo. Os arts. 76 e 77 dão suporte ao estudo da Presidência, não mudam a categoria da Federação. Base: CF, Art. 76; Art. 77."},{"a":true,"q":"Um esquema que apresenta Legislativo, Executivo e Judiciário como independentes e harmônicos não autoriza concluir que um deles pode eliminar os outros por decisão unilateral.","why":"O art. 2º exige independência e harmonia, não supressão de Poderes. A separação também é protegida pelo art. 60, § 4º, III. Base: CF, Art. 2º."},{"a":false,"q":"A Constituição trataria a forma republicana como assunto sem proteção específica, pois o art. 34, VII, somente se refere a questões financeiras.","why":"A alínea a menciona forma republicana, sistema representativo e regime democrático. O dispositivo não se restringe a finanças, ainda que também contenha previsões sobre prestação de contas. Base: CF, Art. 34, VII, a."},{"a":true,"q":"O Distrito Federal acumula competências legislativas reservadas aos estados e aos municípios, sem que isso o transforme em dois entes separados ou permita sua divisão municipal.","why":"O art. 32, § 1º, atribui essas competências ao próprio Distrito Federal, enquanto o caput veda sua divisão em municípios. Acumular competências não altera essa identidade. Base: CF, Art. 18; Art. 32, § 1º."},{"a":true,"q":"Uma emenda deve ser examinada quanto ao conteúdo protegido mesmo quando mantém o nome “Federação”: o rótulo, isoladamente, não comprova respeito à forma federativa nem ao voto periódico.","why":"A proteção alcança propostas tendentes a abolir as garantias, e não apenas a troca de seus nomes. O exame precisa considerar os efeitos normativos concretos da alteração proposta. Base: CF, Art. 60, § 4º, I e II."}],"slug":"constitucional-principios-fundamentais-federacao-republica","title":"Princípios fundamentais: Federação, República e autonomia dos entes","body_md":"## O que você vai distinguir\n\nFederação responde **como o poder político se distribui no território**. República responde **como se organiza o governo e como seus titulares respondem pelo exercício do poder**. Presidencialismo é um sistema de governo; democracia diz respeito à participação e à legitimidade do poder. Essas categorias não são sinônimas.\n\n| Pergunta | Resposta para o Brasil | Leitura de apoio |\n| --- | --- | --- |\n| Qual é a forma de Estado? | Federação | CF, arts. 1º e 18 |\n| Qual é a forma de governo? | República | CF, arts. 1º e 34, VII, a |\n| Qual é o sistema de governo? | Presidencialismo | CF, arts. 76 e 77 |\n| Quem é a fonte do poder político? | O povo, com exercício representativo ou direto nos termos da Constituição | CF, art. 1º, parágrafo único |\n\n## Leia a base constitucional\n\n**Art. 1º — trecho inicial:** “A República Federativa do Brasil, formada pela união indissolúvel dos Estados e Municípios e do Distrito Federal, constitui-se em Estado Democrático de Direito”.\n\n**Art. 18 — caput:** “A organização político-administrativa da República Federativa do Brasil compreende a União, os Estados, o Distrito Federal e os Municípios, todos autônomos, nos termos desta Constituição.”\n\nEsses recortes não substituem a leitura integral. Consulte os artigos na [Constituição compilada oficial](https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm).\n\n## Federação: autonomia sem direito de separação\n\nA Constituição distribui competências entre União, estados, Distrito Federal e municípios. Eles possuem autonomia constitucional; não são quatro categorias de países soberanos. A soberania é fundamento da República Federativa do Brasil.\n\nA **União** é um ente da organização interna. A **República Federativa do Brasil** é o Estado brasileiro. Confundir os dois nomes costuma transformar uma afirmação correta sobre soberania em uma conclusão errada sobre hierarquia entre entes.\n\nAutonomia não significa liberdade para contrariar a Constituição. Os estados elaboram constituições próprias dentro dos limites federais (art. 25); os municípios se regem por leis orgânicas (art. 29); o Distrito Federal tem lei orgânica e não pode ser dividido em municípios (art. 32).\n\n**Indissolubilidade:** um estado não pode tornar-se país independente por decisão unilateral. Isso não impede toda alteração interna do mapa: incorporação, subdivisão e desmembramento de estados têm condições próprias no art. 18, § 3º, incluindo plebiscito da população diretamente interessada e lei complementar do Congresso Nacional. Alterar limites internos e romper a Federação são situações diferentes.\n\n**Territórios federais:** integram a União (art. 18, § 2º). Não devem ser acrescentados ao rol de entes autônomos do caput.\n\n## República: mandato, controle e responsabilidade\n\nA lógica republicana afasta a ideia de tratar o cargo político como patrimônio pessoal ou hereditário. Para estudar suas consequências concretas, associe eleição e duração de mandatos à responsabilidade dos governantes e ao dever de prestar contas, sem presumir que todo cargo público seja eletivo.\n\nA Constituição prevê mandatos políticos de duração definida e mecanismos de responsabilização. Os arts. 34, VII, a e d, protegem a forma republicana, o regime democrático e a prestação de contas. O art. 85 trata dos crimes de responsabilidade do Presidente da República.\n\n**Cuidado:** eleição não é autorização para agir acima da Constituição. A escolha popular de um governante não elimina os controles nem converte recursos públicos em propriedade do eleito.\n\n## Proteção da Federação e da democracia\n\nO art. 60, § 4º, impede deliberar proposta de emenda **tendente a abolir** a forma federativa de Estado. Também protege o voto direto, secreto, universal e periódico; a separação dos Poderes; e os direitos e garantias individuais.\n\nNão é correto concluir que toda regra sobre competências federativas seja imutável. A proteção recai contra a tendência de abolir a forma federativa, e não contra qualquer mudança compatível com ela.\n\nA expressão “forma republicana” não aparece literalmente nessa lista. Esse dado de leitura não autoriza afirmar que qualquer alteração de governo seja constitucional: ainda é preciso examinar os demais limites, especialmente o voto periódico e o regime democrático.\n\n## Como resolver uma questão deste assunto\n\n1. Identifique a categoria cobrada: Estado, governo, sistema de governo ou regime político.\n2. Veja se o enunciado troca **autonomia** por **soberania**.\n3. Diferencie rearranjo territorial interno de separação do país.\n4. Quando houver emenda, confira se ela apenas modifica uma regra ou tende a abolir uma proteção constitucional.\n5. Use o dispositivo pertinente; não transfira uma regra penal ou internacional para a teoria geral do Estado.\n\n## Duas correções conceituais importantes\n\n**Povo, população e nação:** são categorias distintas. Em uma introdução, povo se relaciona ao vínculo jurídico-político; população é expressão demográfica; nação se relaciona a vínculos históricos e culturais. Isso não significa que toda pessoa presente no território possa exercer todos os direitos políticos. Para os requisitos constitucionais específicos, continue em [Nacionalidade](/dashboard/library/constitucional-nacionalidade-medidas-retirada) e [Direitos políticos](/dashboard/library/constitucional-direitos-politicos-elegibilidade).\n\n**Embarcações e aeronaves:** o Código Penal, art. 5º, § 1º, prevê extensão do território **para efeitos penais**, com requisitos próprios. Essa técnica de aplicação da lei penal não significa que a embarcação transforme fisicamente o território estrangeiro em território brasileiro. O estudo completo fica em [Lei penal no espaço](/dashboard/library/penal-lei-no-espaco), evitando repetir esse conteúdo aqui.\n\nAs classificações doutrinárias históricas do federalismo podem variar conforme o autor e a banca. Para este módulo, priorize o que o texto constitucional permite verificar: autonomia dos entes, repartição de competências, vínculo indissolúvel e limites à reforma.\n","summary":"Aprenda a separar forma de Estado, forma e sistema de governo; diferencie autonomia de soberania e resolva casos sobre vínculo federativo, República e limites às emendas. Leia o texto-base, abra os casos resolvidos e pratique com 20 exercícios comentados.","created_at":"2026-10-24T20:44:09.699895+00:00","discipline":"Direito Constitucional","flashcards":[{"b":"Federação. Trata da distribuição territorial do poder político.","f":"Qual é a forma de Estado brasileira?"},{"b":"República. Não confundir com Federação nem com presidencialismo.","f":"Qual é a forma de governo brasileira?"},{"b":"São autônomos nos termos do art. 18. A soberania é fundamento da República Federativa do Brasil.","f":"Os entes federativos são soberanos?"},{"b":"Não. O art. 18 prevê condições para reorganizações internas; isso não é secessão.","f":"A indissolubilidade proíbe toda alteração interna de limites?"},{"b":"Não. A vedação está no art. 32.","f":"O Distrito Federal pode ser dividido em municípios?"},{"b":"Não. Isso não afasta os demais limites constitucionais, como o voto periódico e a separação dos Poderes.","f":"A forma republicana está escrita literalmente no rol do art. 60, § 4º?"}],"sort_order":1,"updated_at":"2026-10-24T20:44:09.699895+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","title":"Constituição Federal compilada — princípios fundamentais e organização do Estado"},{"url":"https://www.planalto.gov.br/ccivil_03/Decreto-Lei/Del2848compilado.htm","title":"Código Penal — art. 5º, delimitação da extensão para efeitos penais"}],"reviewed_at":"2026-10-24T20:38:35.690514+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Explicações, casos e exercícios com redação própria. Textos oficiais consultados em 24/10/2026. Vínculo curricular: PMSC Soldado 2023, item 1.1. A aplicação a outros concursos depende do edital e de sua data de corte. Os exercícios são de fixação; não reproduzem questões de uma banca.","topic_label":"Princípios fundamentais","contest_name":"Polícia Militar de Santa Catarina — Soldado — 2023","legal_review":{"scope":"Conferência dos dispositivos constitucionais utilizados e do art. 5º do Código Penal. As explicações são elaboração própria, sem reprodução da redação didática ou dos exercícios da apostila. Não certifica auditoria de toda a Constituição ou jurisprudência.","changes":[],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","sha256":"82a054357e7b18f0a2f1d2c1d584a1ef77ff40842cf7297d9ff9fc78f9929349"},{"url":"https://www.planalto.gov.br/ccivil_03/Decreto-Lei/Del2848compilado.htm","title":"Código Penal — art. 5º, delimitação da extensão para efeitos penais","sha256":"7f567d6359fa6650072427ae9fcfc4f20adfa81f04d0c861831110144820ae92"}],"checked_at":"2026-10-24T20:38:35.690514+00:00","corrections":["Separada autonomia dos entes de soberania do Estado brasileiro.","Diferenciada a extensão territorial para efeitos penais de território físico.","Evitada a conclusão de que ausência literal da forma republicana no art. 60 permite qualquer reforma."]},"content_status":"active","practice_review":{"items":[{"a":false,"q":"Uma comissão propõe chamar de “soberania municipal” a competência de um município para elaborar sua lei orgânica. Essa denominação descreve corretamente o vínculo constitucional do município.","why":"O município é autônomo, não soberano. A elaboração da lei orgânica expressa autonomia de organização; a soberania é fundamento da República Federativa do Brasil. Exemplo: o município organiza sua atuação dentro dos limites constitucionais, sem se tornar país independente. Base: CF, Art. 1º; Art. 18.","origin":"authored_official_constitution_case","article":"Art. 1º; Art. 18","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Em uma ficha de revisão, a linha “distribuição territorial do poder político” deve ser associada à Federação, enquanto a linha “forma de governo brasileira” deve ser associada à República.","why":"As categorias respondem a perguntas diferentes. Exemplo: escrever “república” como forma de Estado troca a organização do governo pela distribuição territorial do poder. Base: CF, Art. 1º; Art. 18.","origin":"authored_official_constitution_case","article":"Art. 1º; Art. 18","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Dois estados pretendem incorporar-se entre si. Como a Constituição afirma que a Federação é indissolúvel, qualquer incorporação interna é proibida, mesmo quando cumpridas as condições constitucionais.","why":"O art. 18, § 3º, admite reorganizações internas sob condições próprias. É necessário distinguir incorporação dentro do Brasil de separação para formar um país independente. Base: CF, Art. 18, § 3º.","origin":"authored_official_constitution_case","article":"Art. 18, § 3º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Um plebiscito local favorável basta para que um estado deixe o Brasil e se torne país independente, pois autonomia inclui direito unilateral de secessão.","why":"O vínculo federativo é indissolúvel. O plebiscito previsto para reorganização interna não é autorização para romper o país. Mesmo no rearranjo interno existem outras condições, como lei complementar do Congresso Nacional. Base: CF, Art. 1º; Art. 18, § 3º.","origin":"authored_official_constitution_case","article":"Art. 1º; Art. 18, § 3º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Ao revisar um organograma, a estudante retira “Territórios Federais” da lista de entes autônomos e os posiciona como integrantes da União. A correção corresponde ao art. 18.","why":"O caput enumera União, estados, Distrito Federal e municípios como autônomos; o § 2º dispõe que os territórios integram a União. Não se cria uma quinta categoria de ente federativo autônomo. Base: CF, Art. 18, § 2º.","origin":"authored_official_constitution_case","article":"Art. 18, § 2º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Um projeto prevê dividir o Distrito Federal em municípios, justificando que isso seria simples exercício de sua autonomia. A justificativa afasta a vedação constitucional.","why":"O art. 32 veda expressamente a divisão do Distrito Federal em municípios. Autonomia não permite contrariar essa restrição; a organização distrital tem disciplina constitucional própria. Base: CF, Art. 32.","origin":"authored_official_constitution_case","article":"Art. 32","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Uma constituição estadual pode organizar o estado, mas não pode afastar os princípios impostos pela Constituição Federal sob o argumento de que ambos os textos têm a mesma liberdade de criação.","why":"O art. 25 condiciona a organização estadual aos princípios da Constituição Federal. A capacidade de auto-organização não equivale a poder constituinte originário soberano. Base: CF, Art. 25.","origin":"authored_official_constitution_case","article":"Art. 25","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Para demonstrar autonomia municipal, o enunciado afirma que o município deve se reger por uma constituição municipal promulgada pelo governador. A descrição está correta.","why":"O município se rege por lei orgânica aprovada e promulgada pela Câmara Municipal, com as condições do art. 29. Não é constituição estadual nem ato do governador. Base: CF, Art. 29.","origin":"authored_official_constitution_case","article":"Art. 29","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Em um resumo, a União aparece como um ente da organização político-administrativa, e não como sinônimo de toda a República Federativa do Brasil. Essa distinção evita confundir organização interna e Estado brasileiro.","why":"O art. 18 inclui a União ao lado de estados, Distrito Federal e municípios. A República Federativa do Brasil compreende o conjunto da organização, não apenas esse ente. Base: CF, Art. 18.","origin":"authored_official_constitution_case","article":"Art. 18","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Uma proposta declara expressamente extinguir a forma federativa. Se atingir três quintos dos votos em dois turnos de cada Casa, o quórum supera a limitação material constitucional.","why":"Cumprir o procedimento não afasta uma cláusula pétrea. O § 4º impede deliberar proposta tendente a abolir a forma federativa; quórum qualificado não transforma o conteúdo proibido em conteúdo permitido. Base: CF, Art. 60, § 4º, I.","origin":"authored_official_constitution_case","article":"Art. 60, § 4º, I","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"A proteção da forma federativa não permite concluir que toda alteração pontual de competência entre entes seja automaticamente proibida. É preciso examinar se a proposta tende a abolir essa forma de Estado.","why":"A Constituição protege contra a abolição, sem petrificar indistintamente cada regra de organização. Exemplo: avaliar uma modificação de competência exige analisar seu conteúdo e efeito, não apenas sua existência. Base: CF, Art. 60, § 4º, I.","origin":"authored_official_constitution_case","article":"Art. 60, § 4º, I","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Ao constatar que “forma republicana” não está escrita literalmente no rol do § 4º, um candidato conclui que uma emenda pode, sem examinar mais nada, eliminar eleições periódicas e instituir cargo político hereditário.","why":"A conclusão ignora limites expressos, como a proteção do voto direto, secreto, universal e periódico. A ausência de uma expressão na lista não dispensa examinar as demais garantias constitucionais. Base: CF, Art. 60, § 4º.","origin":"authored_official_constitution_case","article":"Art. 60, § 4º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Para explicar a relação entre república e controle, um quadro associa a forma republicana à prestação de contas da administração, ambas protegidas no art. 34, VII.","why":"O dispositivo contém esses princípios em alíneas distintas. Exemplo: a eleição de um governante não elimina a exigência de prestar contas sobre a administração pública. Base: CF, Art. 34, VII, a e d.","origin":"authored_official_constitution_case","article":"Art. 34, VII, a e d","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Um governante afirma que vencer uma eleição elimina qualquer responsabilidade por atos que atentem contra a Constituição. Essa consequência decorre do princípio republicano.","why":"A Constituição prevê responsabilização, incluindo crimes de responsabilidade do Presidente no art. 85. Legitimidade eleitoral não cria imunidade absoluta nem coloca o governante acima da Constituição. Base: CF, Art. 85.","origin":"authored_official_constitution_case","article":"Art. 85","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Um material que explique a origem popular do poder somente pela eleição de representantes está incompleto se excluir toda possibilidade de exercício direto prevista na Constituição.","why":"O parágrafo único contempla representantes eleitos ou exercício direto, nos termos constitucionais. Isso não significa que qualquer decisão popular, sem observar tais termos, produza todo efeito pretendido. Base: CF, Art. 1º, parágrafo único.","origin":"authored_official_constitution_case","article":"Art. 1º, parágrafo único","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Em uma tabela, “presidencialismo” é indicado como forma de Estado e “Federação” como sistema de governo. As duas classificações estão corretas.","why":"As posições estão invertidas: Federação é forma de Estado; presidencialismo é sistema de governo. Os arts. 76 e 77 dão suporte ao estudo da Presidência, não mudam a categoria da Federação. Base: CF, Art. 76; Art. 77.","origin":"authored_official_constitution_case","article":"Art. 76; Art. 77","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Um esquema que apresenta Legislativo, Executivo e Judiciário como independentes e harmônicos não autoriza concluir que um deles pode eliminar os outros por decisão unilateral.","why":"O art. 2º exige independência e harmonia, não supressão de Poderes. A separação também é protegida pelo art. 60, § 4º, III. Base: CF, Art. 2º.","origin":"authored_official_constitution_case","article":"Art. 2º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"A Constituição trataria a forma republicana como assunto sem proteção específica, pois o art. 34, VII, somente se refere a questões financeiras.","why":"A alínea a menciona forma republicana, sistema representativo e regime democrático. O dispositivo não se restringe a finanças, ainda que também contenha previsões sobre prestação de contas. Base: CF, Art. 34, VII, a.","origin":"authored_official_constitution_case","article":"Art. 34, VII, a","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"O Distrito Federal acumula competências legislativas reservadas aos estados e aos municípios, sem que isso o transforme em dois entes separados ou permita sua divisão municipal.","why":"O art. 32, § 1º, atribui essas competências ao próprio Distrito Federal, enquanto o caput veda sua divisão em municípios. Acumular competências não altera essa identidade. Base: CF, Art. 18; Art. 32, § 1º.","origin":"authored_official_constitution_case","article":"Art. 18; Art. 32, § 1º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Uma emenda deve ser examinada quanto ao conteúdo protegido mesmo quando mantém o nome “Federação”: o rótulo, isoladamente, não comprova respeito à forma federativa nem ao voto periódico.","why":"A proteção alcança propostas tendentes a abolir as garantias, e não apenas a troca de seus nomes. O exame precisa considerar os efeitos normativos concretos da alteração proposta. Base: CF, Art. 60, § 4º, I e II.","origin":"authored_official_constitution_case","article":"Art. 60, § 4º, I e II","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"scope":"Exercícios de fixação autorais, conferidos com a Constituição compilada oficial, vinculados ao tópico atual cadastrado da edição PMSC 2023. A atualização para estudo não modifica a data de corte de provas históricas. Não são questões atribuídas à banca ou à apostila enviada.","status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"82a054357e7b18f0a2f1d2c1d584a1ef77ff40842cf7297d9ff9fc78f9929349","checked_at":"2026-10-24T20:38:35.690514+00:00"}],"subject":"Direito Constitucional","version":1,"checked_at":"2026-10-24T20:38:35.690514+00:00","topic_label":"Princípios fundamentais","material_slug":"constitucional-principios-fundamentais-federacao-republica","syllabus_topic_id":"5b5a7f1e-44bf-4cab-903e-199eacd65578"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-24T20:38:35.690514+00:00"},"expected_active_enrichments":[{"id":"f6c88d53-75ae-5647-b6c7-b50e815b93ca","status":"active","content":{"cases":[{"id":"autonomia","steps":["Identifique o efeito pretendido: deixar o Brasil, e não apenas mudar um limite interno.","Leia a união indissolúvel no art. 1º e a autonomia nos termos da Constituição no art. 18.","Não use a consulta para rearranjo interno como autorização de secessão."],"title":"O estado pode transformar autonomia em soberania?","pitfall":"Tratar qualquer aprovação popular como autorização para ignorar as condições constitucionais.","articles":["Art. 1º","Art. 18"],"question":"A consulta local autoriza romper a Federação?","scenario":"Uma assembleia estadual pretende declarar o estado um país independente após consulta local. O projeto usa a expressão “exercício da autonomia”.","variation":{"answer":"O art. 18, § 3º, admite essa hipótese sob condições, como plebiscito da população diretamente interessada e lei complementar do Congresso. Permanecer na Federação muda a análise, sem dispensar requisitos.","scenario":"Os estados querem incorporar-se entre si, permanecendo no Brasil."},"conclusion":"Não. A autonomia constitucional não inclui direito unilateral de separar-se do país."},{"id":"categorias","steps":["Associe distribuição territorial do poder à forma de Estado.","Associe República à forma de governo.","Associe presidencialismo ao sistema de governo e leia os arts. 76 e 77."],"title":"Três etiquetas, três perguntas","pitfall":"Usar as três palavras como se fossem respostas intercambiáveis.","articles":["Art. 1º","Art. 18","Art. 76","Art. 77"],"question":"Como corrigir as três linhas?","scenario":"Um aplicativo de revisão mostra: forma de Estado = República; forma de governo = presidencialismo; sistema de governo = Federação.","variation":{"answer":"Agora a referência é o povo, conforme o art. 1º, parágrafo único. A resposta não é o nome de um sistema de governo.","scenario":"A pergunta troca “sistema de governo” por “titularidade do poder político”."},"conclusion":"Forma de Estado: Federação. Forma de governo: República. Sistema de governo: presidencialismo."},{"id":"reforma","steps":["Separe requisitos procedimentais de limites de conteúdo.","Localize a forma federativa no art. 60, § 4º, I.","Confira a expressão “tendente a abolir”, que não se limita à mudança de um nome."],"title":"Um quórum alto resolve qualquer emenda?","pitfall":"Imaginar que quantidade de votos elimina todos os limites ao poder de reforma.","articles":["Art. 60"],"question":"O procedimento formal elimina a vedação material?","scenario":"Uma proposta obtém apoio para extinguir a forma federativa e sustenta que respeitar dois turnos e três quintos em cada Casa seria suficiente.","variation":{"answer":"Não se presume proibição de toda modificação. Examine se o efeito tende a abolir a forma federativa, além de conferir os demais requisitos constitucionais.","scenario":"A proposta apenas altera uma competência específica, mantendo a estrutura federativa."},"conclusion":"Não. A limitação material continua aplicável mesmo com apoio suficiente para o procedimento de votação."},{"id":"republica","steps":["Reconheça que legitimidade eleitoral não elimina o dever de observar a Constituição.","Consulte a proteção da forma republicana e da prestação de contas no art. 34, VII.","Observe no art. 85 a previsão de crimes de responsabilidade do Presidente, sem presumir culpa em um caso real."],"title":"Eleição dispensa prestar contas?","pitfall":"Confundir origem democrática do mandato com imunidade absoluta ou propriedade privada do cargo.","articles":["Art. 34","Art. 85"],"question":"A eleição produz essas duas consequências?","scenario":"Um governante afirma que a vitória eleitoral lhe permite administrar recursos públicos sem prestar contas e impede qualquer responsabilização constitucional.","variation":{"answer":"Exercer defesa é compatível com a Constituição. A existência de responsabilidade não dispensa processo, competência e garantias aplicáveis.","scenario":"O governante apenas questiona uma acusação e exerce seu direito de defesa."},"conclusion":"Não. Mandato eletivo, dever de prestar contas e mecanismos de responsabilização convivem no regime constitucional."}],"illustrations":[]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","title":"Constituição Federal compilada — princípios fundamentais e organização do Estado"}],"version":"2026-10-24-principios-v1","checked_at":"2026-10-24T20:38:35.690514+00:00","reviewed_at":"2026-10-24T20:38:35.690514+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"constitucional-principios-fundamentais-federacao-republica","source_body_sha256":"5cc997d1bac9f783e60e6fb11f7bf0047a912b7e5ab507d1f5af9ecec9b6d8a9"}],"material":{"id":"7d517d28-2e6e-503d-b72f-bc7421d6d492","quiz":[{"q":"Uma comissão propõe chamar de “soberania municipal” a competência de um município para elaborar sua lei orgânica. Essa denominação descreve corretamente o vínculo constitucional do município.","a":false,"why":"O município é autônomo, não soberano. A elaboração da lei orgânica expressa autonomia de organização; a soberania é fundamento da República Federativa do Brasil. Exemplo: o município organiza sua atuação dentro dos limites constitucionais, sem se tornar país independente. Base: CF, Art. 1º; Art. 18."},{"q":"Em uma ficha de revisão, a linha “distribuição territorial do poder político” deve ser associada à Federação, enquanto a linha “forma de governo brasileira” deve ser associada à República.","a":true,"why":"As categorias respondem a perguntas diferentes. Exemplo: escrever “república” como forma de Estado troca a organização do governo pela distribuição territorial do poder. Base: CF, Art. 1º; Art. 18."},{"q":"Dois estados pretendem incorporar-se entre si. Como a Constituição afirma que a Federação é indissolúvel, qualquer incorporação interna é proibida, mesmo quando cumpridas as condições constitucionais.","a":false,"why":"O art. 18, § 3º, admite reorganizações internas sob condições próprias. É necessário distinguir incorporação dentro do Brasil de separação para formar um país independente. Base: CF, Art. 18, § 3º."},{"q":"Um plebiscito local favorável basta para que um estado deixe o Brasil e se torne país independente, pois autonomia inclui direito unilateral de secessão.","a":false,"why":"O vínculo federativo é indissolúvel. O plebiscito previsto para reorganização interna não é autorização para romper o país. Mesmo no rearranjo interno existem outras condições, como lei complementar do Congresso Nacional. Base: CF, Art. 1º; Art. 18, § 3º."},{"q":"Ao revisar um organograma, a estudante retira “Territórios Federais” da lista de entes autônomos e os posiciona como integrantes da União. A correção corresponde ao art. 18.","a":true,"why":"O caput enumera União, estados, Distrito Federal e municípios como autônomos; o § 2º dispõe que os territórios integram a União. Não se cria uma quinta categoria de ente federativo autônomo. Base: CF, Art. 18, § 2º."},{"q":"Um projeto prevê dividir o Distrito Federal em municípios, justificando que isso seria simples exercício de sua autonomia. A justificativa afasta a vedação constitucional.","a":false,"why":"O art. 32 veda expressamente a divisão do Distrito Federal em municípios. Autonomia não permite contrariar essa restrição; a organização distrital tem disciplina constitucional própria. Base: CF, Art. 32."},{"q":"Uma constituição estadual pode organizar o estado, mas não pode afastar os princípios impostos pela Constituição Federal sob o argumento de que ambos os textos têm a mesma liberdade de criação.","a":true,"why":"O art. 25 condiciona a organização estadual aos princípios da Constituição Federal. A capacidade de auto-organização não equivale a poder constituinte originário soberano. Base: CF, Art. 25."},{"q":"Para demonstrar autonomia municipal, o enunciado afirma que o município deve se reger por uma constituição municipal promulgada pelo governador. A descrição está correta.","a":false,"why":"O município se rege por lei orgânica aprovada e promulgada pela Câmara Municipal, com as condições do art. 29. Não é constituição estadual nem ato do governador. Base: CF, Art. 29."},{"q":"Em um resumo, a União aparece como um ente da organização político-administrativa, e não como sinônimo de toda a República Federativa do Brasil. Essa distinção evita confundir organização interna e Estado brasileiro.","a":true,"why":"O art. 18 inclui a União ao lado de estados, Distrito Federal e municípios. A República Federativa do Brasil compreende o conjunto da organização, não apenas esse ente. Base: CF, Art. 18."},{"q":"Uma proposta declara expressamente extinguir a forma federativa. Se atingir três quintos dos votos em dois turnos de cada Casa, o quórum supera a limitação material constitucional.","a":false,"why":"Cumprir o procedimento não afasta uma cláusula pétrea. O § 4º impede deliberar proposta tendente a abolir a forma federativa; quórum qualificado não transforma o conteúdo proibido em conteúdo permitido. Base: CF, Art. 60, § 4º, I."},{"q":"A proteção da forma federativa não permite concluir que toda alteração pontual de competência entre entes seja automaticamente proibida. É preciso examinar se a proposta tende a abolir essa forma de Estado.","a":true,"why":"A Constituição protege contra a abolição, sem petrificar indistintamente cada regra de organização. Exemplo: avaliar uma modificação de competência exige analisar seu conteúdo e efeito, não apenas sua existência. Base: CF, Art. 60, § 4º, I."},{"q":"Ao constatar que “forma republicana” não está escrita literalmente no rol do § 4º, um candidato conclui que uma emenda pode, sem examinar mais nada, eliminar eleições periódicas e instituir cargo político hereditário.","a":false,"why":"A conclusão ignora limites expressos, como a proteção do voto direto, secreto, universal e periódico. A ausência de uma expressão na lista não dispensa examinar as demais garantias constitucionais. Base: CF, Art. 60, § 4º."},{"q":"Um quadro classifica soberania como objetivo do art. 3º, apenas por ela ser relevante para o país. A posição está correta.","a":false,"why":"Soberania é fundamento do art. 1º. Relevância de um valor não permite trocá-lo de lista constitucional. Base: Art. 1º; Art. 3º."},{"q":"Ao revisar fundamentos, a estudante mantém valores sociais do trabalho e da livre iniciativa no mesmo inciso, sem excluir um dos elementos.","a":true,"why":"A Constituição reúne os dois no inciso IV. A interpretação não deve apagar um deles por preferência pessoal. Base: Art. 1º, IV."},{"q":"Uma proposta que combate marginalização e desigualdades pode ser relacionada aos objetivos fundamentais, sem chamar esses itens de regras de composição dos Poderes.","a":true,"why":"O art. 3º enumera finalidades da República. Objetivo constitucional e estrutura de um órgão não são categorias equivalentes. Base: Art. 3º."},{"q":"Um quadro classifica a concessão de asilo político como objetivo fundamental do art. 3º, sem distingui-la dos princípios das relações internacionais.","a":false,"why":"O art. 4º a inclui entre os princípios das relações internacionais. A importância da medida não autoriza trocar sua posição pela lista de objetivos do art. 3º. Base: Art. 4º, X."},{"q":"A integração latino-americana prevista constitucionalmente tem dimensão apenas econômica, excluídas política, sociedade e cultura.","a":false,"why":"O parágrafo único prevê integração econômica, política, social e cultural dos povos da América Latina. Reduzi-la a comércio altera a formulação constitucional. Base: Art. 4º, parágrafo único."},{"q":"Um esquema de democracia que só admita exercício do poder por representantes fica incompleto diante da previsão constitucional de exercício direto nos seus termos.","a":true,"why":"O texto admite as duas vias. Isso não significa que qualquer decisão informal dispense as condições constitucionais de participação. Base: Art. 1º, parágrafo único."},{"q":"Independência entre Poderes significa que a harmonia constitucional pode ser eliminada por decisão unilateral de qualquer deles.","a":false,"why":"O art. 2º combina independência e harmonia. Controles recíprocos exigem fundamento e não autorizam supressão arbitrária. Base: Art. 2º."},{"q":"Para não misturar categorias, o aluno distingue presidencialismo como sistema de governo, República como forma de governo e Federação como forma de Estado.","a":true,"why":"As categorias respondem a perguntas distintas. A Presidência está disciplinada em seus dispositivos próprios, sem trocar o sentido da Federação. Base: Art. 76; Art. 1º."}],"slug":"constitucional-principios-fundamentais-federacao-republica","title":"Princípios fundamentais: Federação, República e autonomia dos entes","body_md":"## O que você vai distinguir\n\nFederação responde **como o poder político se distribui no território**. República responde **como se organiza o governo e como seus titulares respondem pelo exercício do poder**. Presidencialismo é um sistema de governo; democracia diz respeito à participação e à legitimidade do poder. Essas categorias não são sinônimas.\n\n| Pergunta | Resposta para o Brasil | Leitura de apoio |\n| --- | --- | --- |\n| Qual é a forma de Estado? | Federação | CF, arts. 1º e 18 |\n| Qual é a forma de governo? | República | CF, arts. 1º e 34, VII, a |\n| Qual é o sistema de governo? | Presidencialismo | CF, arts. 76 e 77 |\n| Quem é a fonte do poder político? | O povo, com exercício representativo ou direto nos termos da Constituição | CF, art. 1º, parágrafo único |\n\n## Leia a base constitucional\n\n**Art. 1º — trecho inicial:** “A República Federativa do Brasil, formada pela união indissolúvel dos Estados e Municípios e do Distrito Federal, constitui-se em Estado Democrático de Direito”.\n\n**Art. 18 — caput:** “A organização político-administrativa da República Federativa do Brasil compreende a União, os Estados, o Distrito Federal e os Municípios, todos autônomos, nos termos desta Constituição.”\n\nEsses recortes não substituem a leitura integral. Consulte os artigos na [Constituição compilada oficial](https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm).\n\n## Federação: autonomia sem direito de separação\n\nA Constituição distribui competências entre União, estados, Distrito Federal e municípios. Eles possuem autonomia constitucional; não são quatro categorias de países soberanos. A soberania é fundamento da República Federativa do Brasil.\n\nA **União** é um ente da organização interna. A **República Federativa do Brasil** é o Estado brasileiro. Confundir os dois nomes costuma transformar uma afirmação correta sobre soberania em uma conclusão errada sobre hierarquia entre entes.\n\nAutonomia não significa liberdade para contrariar a Constituição. Os estados elaboram constituições próprias dentro dos limites federais (art. 25); os municípios se regem por leis orgânicas (art. 29); o Distrito Federal tem lei orgânica e não pode ser dividido em municípios (art. 32).\n\n**Indissolubilidade:** um estado não pode tornar-se país independente por decisão unilateral. Isso não impede toda alteração interna do mapa: incorporação, subdivisão e desmembramento de estados têm condições próprias no art. 18, § 3º, incluindo plebiscito da população diretamente interessada e lei complementar do Congresso Nacional. Alterar limites internos e romper a Federação são situações diferentes.\n\n**Territórios federais:** integram a União (art. 18, § 2º). Não devem ser acrescentados ao rol de entes autônomos do caput.\n\n## República: mandato, controle e responsabilidade\n\nA lógica republicana afasta a ideia de tratar o cargo político como patrimônio pessoal ou hereditário. Para estudar suas consequências concretas, associe eleição e duração de mandatos à responsabilidade dos governantes e ao dever de prestar contas, sem presumir que todo cargo público seja eletivo.\n\nA Constituição prevê mandatos políticos de duração definida e mecanismos de responsabilização. Os arts. 34, VII, a e d, protegem a forma republicana, o regime democrático e a prestação de contas. O art. 85 trata dos crimes de responsabilidade do Presidente da República.\n\n**Cuidado:** eleição não é autorização para agir acima da Constituição. A escolha popular de um governante não elimina os controles nem converte recursos públicos em propriedade do eleito.\n\n## Proteção da Federação e da democracia\n\nO art. 60, § 4º, impede deliberar proposta de emenda **tendente a abolir** a forma federativa de Estado. Também protege o voto direto, secreto, universal e periódico; a separação dos Poderes; e os direitos e garantias individuais.\n\nNão é correto concluir que toda regra sobre competências federativas seja imutável. A proteção recai contra a tendência de abolir a forma federativa, e não contra qualquer mudança compatível com ela.\n\nA expressão “forma republicana” não aparece literalmente nessa lista. Esse dado de leitura não autoriza afirmar que qualquer alteração de governo seja constitucional: ainda é preciso examinar os demais limites, especialmente o voto periódico e o regime democrático.\n\n## Como resolver uma questão deste assunto\n\n1. Identifique a categoria cobrada: Estado, governo, sistema de governo ou regime político.\n2. Veja se o enunciado troca **autonomia** por **soberania**.\n3. Diferencie rearranjo territorial interno de separação do país.\n4. Quando houver emenda, confira se ela apenas modifica uma regra ou tende a abolir uma proteção constitucional.\n5. Use o dispositivo pertinente; não transfira uma regra penal ou internacional para a teoria geral do Estado.\n\n## Duas correções conceituais importantes\n\n**Povo, população e nação:** são categorias distintas. Em uma introdução, povo se relaciona ao vínculo jurídico-político; população é expressão demográfica; nação se relaciona a vínculos históricos e culturais. Isso não significa que toda pessoa presente no território possa exercer todos os direitos políticos. Para os requisitos constitucionais específicos, continue em [Nacionalidade](/dashboard/library/constitucional-nacionalidade-medidas-retirada) e [Direitos políticos](/dashboard/library/constitucional-direitos-politicos-elegibilidade).\n\n**Embarcações e aeronaves:** o Código Penal, art. 5º, § 1º, prevê extensão do território **para efeitos penais**, com requisitos próprios. Essa técnica de aplicação da lei penal não significa que a embarcação transforme fisicamente o território estrangeiro em território brasileiro. O estudo completo fica em [Lei penal no espaço](/dashboard/library/penal-lei-no-espaco), evitando repetir esse conteúdo aqui.\n\nAs classificações doutrinárias históricas do federalismo podem variar conforme o autor e a banca. Para este módulo, priorize o que o texto constitucional permite verificar: autonomia dos entes, repartição de competências, vínculo indissolúvel e limites à reforma.\n\n## Fundamentos, objetivos e relações internacionais: três listas diferentes\n\n| Dispositivo | Pergunta | Conteúdo de referência |\n| --- | --- | --- |\n| Art. 1º | Em que se funda a República? | Soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa e pluralismo político |\n| Art. 3º | Quais objetivos fundamentais devem orientar a atuação? | Sociedade livre, justa e solidária; desenvolvimento nacional; erradicação da pobreza e marginalização e redução das desigualdades; bem de todos sem discriminação |\n| Art. 4º | Quais princípios regem relações internacionais? | Independência nacional, direitos humanos, autodeterminação, não intervenção, igualdade entre Estados, paz, solução pacífica, repúdio ao terrorismo e racismo, cooperação e asilo político |\n\nNão troque um item de lista apenas porque ele expressa um valor importante. A soberania aparece entre os fundamentos; promover o bem de todos, entre os objetivos; concessão de asilo político, nas relações internacionais. O parágrafo único do art. 4º prevê integração econômica, política, social e cultural dos povos da América Latina; não se limita a um acordo comercial.\n\n## Presidencialismo, democracia e controles\n\nOs arts. 76 e 77 sustentam o estudo do sistema presidencialista. A origem popular do poder é expressa no art. 1º, parágrafo único: representação e exercício direto convivem nos termos constitucionais. Não reduza democracia a qualquer decisão tomada sem observar os procedimentos e garantias.\n\nA separação do art. 2º combina independência e harmonia. Controles entre Poderes precisam de fundamento constitucional: não constituem autorização para um Poder eliminar os demais. Da mesma forma, desempenhar uma função atípica constitucionalmente prevista não apaga a função típica do órgão.\n\n**Leitura de conferência:** Constituição compilada, arts. 1º a 4º, 76 e 77. Este complemento amplia o módulo existente; não cria outra faixa de conteúdo com as mesmas noções de Federação e República.\n","summary":"Aprenda a separar forma de Estado, forma e sistema de governo; diferencie autonomia de soberania e resolva casos sobre vínculo federativo, República e limites às emendas. Leia o texto-base, abra os casos resolvidos e pratique com 20 exercícios comentados.","created_at":"2026-10-24T20:44:09.699895+00:00","discipline":"Direito Constitucional","flashcards":[{"b":"Federação. Trata da distribuição territorial do poder político.","f":"Qual é a forma de Estado brasileira?"},{"b":"República. Não confundir com Federação nem com presidencialismo.","f":"Qual é a forma de governo brasileira?"},{"b":"São autônomos nos termos do art. 18. A soberania é fundamento da República Federativa do Brasil.","f":"Os entes federativos são soberanos?"},{"b":"Não. O art. 18 prevê condições para reorganizações internas; isso não é secessão.","f":"A indissolubilidade proíbe toda alteração interna de limites?"},{"b":"Não. A vedação está no art. 32.","f":"O Distrito Federal pode ser dividido em municípios?"},{"b":"Não. Isso não afasta os demais limites constitucionais, como o voto periódico e a separação dos Poderes.","f":"A forma republicana está escrita literalmente no rol do art. 60, § 4º?"}],"sort_order":1,"updated_at":"2026-10-24T20:44:09.699895+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","title":"Constituição Federal compilada — princípios fundamentais e organização do Estado"},{"url":"https://www.planalto.gov.br/ccivil_03/Decreto-Lei/Del2848compilado.htm","title":"Código Penal — art. 5º, delimitação da extensão para efeitos penais"}],"reviewed_at":"2026-10-24T20:38:35.690514+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Explicações, casos e exercícios com redação própria. Textos oficiais consultados em 24/10/2026. Vínculo curricular: PMSC Soldado 2023, item 1.1. A aplicação a outros concursos depende do edital e de sua data de corte. Os exercícios são de fixação; não reproduzem questões de uma banca. Complemento de 24/10/2026: distinções e casos do recorte constitucional, com fonte compilada atual. Fontes e recortes anteriores foram preservados; não se declara nova auditoria integral dos demais temas.","topic_label":"Princípios fundamentais","contest_name":"Polícia Militar de Santa Catarina — Soldado — 2023","legal_review":{"scope":"Conferência dos dispositivos constitucionais utilizados e do art. 5º do Código Penal. As explicações são elaboração própria, sem reprodução da redação didática ou dos exercícios da apostila. Não certifica auditoria de toda a Constituição ou jurisprudência.","changes":[],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","title":"Constituição Federal compilada — princípios fundamentais e organização do Estado","sha256":"82a054357e7b18f0a2f1d2c1d584a1ef77ff40842cf7297d9ff9fc78f9929349"},{"url":"https://www.planalto.gov.br/ccivil_03/Decreto-Lei/Del2848compilado.htm","title":"Código Penal — art. 5º, delimitação da extensão para efeitos penais","sha256":"7f567d6359fa6650072427ae9fcfc4f20adfa81f04d0c861831110144820ae92"}],"checked_at":"2026-10-24T20:38:35.690514+00:00","corrections":["Separada autonomia dos entes de soberania do Estado brasileiro.","Diferenciada a extensão territorial para efeitos penais de território físico.","Evitada a conclusão de que ausência literal da forma republicana no art. 60 permite qualquer reforma."]},"content_status":"active","practice_review":{"items":[{"a":false,"q":"Uma comissão propõe chamar de “soberania municipal” a competência de um município para elaborar sua lei orgânica. Essa denominação descreve corretamente o vínculo constitucional do município.","why":"O município é autônomo, não soberano. A elaboração da lei orgânica expressa autonomia de organização; a soberania é fundamento da República Federativa do Brasil. Exemplo: o município organiza sua atuação dentro dos limites constitucionais, sem se tornar país independente. Base: CF, Art. 1º; Art. 18.","origin":"authored_official_constitution_case","article":"Art. 1º; Art. 18","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Em uma ficha de revisão, a linha “distribuição territorial do poder político” deve ser associada à Federação, enquanto a linha “forma de governo brasileira” deve ser associada à República.","why":"As categorias respondem a perguntas diferentes. Exemplo: escrever “república” como forma de Estado troca a organização do governo pela distribuição territorial do poder. Base: CF, Art. 1º; Art. 18.","origin":"authored_official_constitution_case","article":"Art. 1º; Art. 18","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Dois estados pretendem incorporar-se entre si. Como a Constituição afirma que a Federação é indissolúvel, qualquer incorporação interna é proibida, mesmo quando cumpridas as condições constitucionais.","why":"O art. 18, § 3º, admite reorganizações internas sob condições próprias. É necessário distinguir incorporação dentro do Brasil de separação para formar um país independente. Base: CF, Art. 18, § 3º.","origin":"authored_official_constitution_case","article":"Art. 18, § 3º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Um plebiscito local favorável basta para que um estado deixe o Brasil e se torne país independente, pois autonomia inclui direito unilateral de secessão.","why":"O vínculo federativo é indissolúvel. O plebiscito previsto para reorganização interna não é autorização para romper o país. Mesmo no rearranjo interno existem outras condições, como lei complementar do Congresso Nacional. Base: CF, Art. 1º; Art. 18, § 3º.","origin":"authored_official_constitution_case","article":"Art. 1º; Art. 18, § 3º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Ao revisar um organograma, a estudante retira “Territórios Federais” da lista de entes autônomos e os posiciona como integrantes da União. A correção corresponde ao art. 18.","why":"O caput enumera União, estados, Distrito Federal e municípios como autônomos; o § 2º dispõe que os territórios integram a União. Não se cria uma quinta categoria de ente federativo autônomo. Base: CF, Art. 18, § 2º.","origin":"authored_official_constitution_case","article":"Art. 18, § 2º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Um projeto prevê dividir o Distrito Federal em municípios, justificando que isso seria simples exercício de sua autonomia. A justificativa afasta a vedação constitucional.","why":"O art. 32 veda expressamente a divisão do Distrito Federal em municípios. Autonomia não permite contrariar essa restrição; a organização distrital tem disciplina constitucional própria. Base: CF, Art. 32.","origin":"authored_official_constitution_case","article":"Art. 32","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Uma constituição estadual pode organizar o estado, mas não pode afastar os princípios impostos pela Constituição Federal sob o argumento de que ambos os textos têm a mesma liberdade de criação.","why":"O art. 25 condiciona a organização estadual aos princípios da Constituição Federal. A capacidade de auto-organização não equivale a poder constituinte originário soberano. Base: CF, Art. 25.","origin":"authored_official_constitution_case","article":"Art. 25","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Para demonstrar autonomia municipal, o enunciado afirma que o município deve se reger por uma constituição municipal promulgada pelo governador. A descrição está correta.","why":"O município se rege por lei orgânica aprovada e promulgada pela Câmara Municipal, com as condições do art. 29. Não é constituição estadual nem ato do governador. Base: CF, Art. 29.","origin":"authored_official_constitution_case","article":"Art. 29","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"Em um resumo, a União aparece como um ente da organização político-administrativa, e não como sinônimo de toda a República Federativa do Brasil. Essa distinção evita confundir organização interna e Estado brasileiro.","why":"O art. 18 inclui a União ao lado de estados, Distrito Federal e municípios. A República Federativa do Brasil compreende o conjunto da organização, não apenas esse ente. Base: CF, Art. 18.","origin":"authored_official_constitution_case","article":"Art. 18","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Uma proposta declara expressamente extinguir a forma federativa. Se atingir três quintos dos votos em dois turnos de cada Casa, o quórum supera a limitação material constitucional.","why":"Cumprir o procedimento não afasta uma cláusula pétrea. O § 4º impede deliberar proposta tendente a abolir a forma federativa; quórum qualificado não transforma o conteúdo proibido em conteúdo permitido. Base: CF, Art. 60, § 4º, I.","origin":"authored_official_constitution_case","article":"Art. 60, § 4º, I","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":true,"q":"A proteção da forma federativa não permite concluir que toda alteração pontual de competência entre entes seja automaticamente proibida. É preciso examinar se a proposta tende a abolir essa forma de Estado.","why":"A Constituição protege contra a abolição, sem petrificar indistintamente cada regra de organização. Exemplo: avaliar uma modificação de competência exige analisar seu conteúdo e efeito, não apenas sua existência. Base: CF, Art. 60, § 4º, I.","origin":"authored_official_constitution_case","article":"Art. 60, § 4º, I","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"a":false,"q":"Ao constatar que “forma republicana” não está escrita literalmente no rol do § 4º, um candidato conclui que uma emenda pode, sem examinar mais nada, eliminar eleições periódicas e instituir cargo político hereditário.","why":"A conclusão ignora limites expressos, como a proteção do voto direto, secreto, universal e periódico. A ausência de uma expressão na lista não dispensa examinar as demais garantias constitucionais. Base: CF, Art. 60, § 4º.","origin":"authored_official_constitution_case","article":"Art. 60, § 4º","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"},{"q":"Um quadro classifica soberania como objetivo do art. 3º, apenas por ela ser relevante para o país. A posição está correta.","a":false,"why":"Soberania é fundamento do art. 1º. Relevância de um valor não permite trocá-lo de lista constitucional. Base: Art. 1º; Art. 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º; Art. 3º","origin":"authored_current_official_source"},{"q":"Ao revisar fundamentos, a estudante mantém valores sociais do trabalho e da livre iniciativa no mesmo inciso, sem excluir um dos elementos.","a":true,"why":"A Constituição reúne os dois no inciso IV. A interpretação não deve apagar um deles por preferência pessoal. Base: Art. 1º, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º, IV","origin":"authored_current_official_source"},{"q":"Uma proposta que combate marginalização e desigualdades pode ser relacionada aos objetivos fundamentais, sem chamar esses itens de regras de composição dos Poderes.","a":true,"why":"O art. 3º enumera finalidades da República. Objetivo constitucional e estrutura de um órgão não são categorias equivalentes. Base: Art. 3º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 3º","origin":"authored_current_official_source"},{"q":"Um quadro classifica a concessão de asilo político como objetivo fundamental do art. 3º, sem distingui-la dos princípios das relações internacionais.","a":false,"why":"O art. 4º a inclui entre os princípios das relações internacionais. A importância da medida não autoriza trocar sua posição pela lista de objetivos do art. 3º. Base: Art. 4º, X.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 4º, X","origin":"authored_current_official_source"},{"q":"A integração latino-americana prevista constitucionalmente tem dimensão apenas econômica, excluídas política, sociedade e cultura.","a":false,"why":"O parágrafo único prevê integração econômica, política, social e cultural dos povos da América Latina. Reduzi-la a comércio altera a formulação constitucional. Base: Art. 4º, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 4º, parágrafo único","origin":"authored_current_official_source"},{"q":"Um esquema de democracia que só admita exercício do poder por representantes fica incompleto diante da previsão constitucional de exercício direto nos seus termos.","a":true,"why":"O texto admite as duas vias. Isso não significa que qualquer decisão informal dispense as condições constitucionais de participação. Base: Art. 1º, parágrafo único.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 1º, parágrafo único","origin":"authored_current_official_source"},{"q":"Independência entre Poderes significa que a harmonia constitucional pode ser eliminada por decisão unilateral de qualquer deles.","a":false,"why":"O art. 2º combina independência e harmonia. Controles recíprocos exigem fundamento e não autorizam supressão arbitrária. Base: Art. 2º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 2º","origin":"authored_current_official_source"},{"q":"Para não misturar categorias, o aluno distingue presidencialismo como sistema de governo, República como forma de governo e Federação como forma de Estado.","a":true,"why":"As categorias respondem a perguntas distintas. A Presidência está disciplinada em seus dispositivos próprios, sem trocar o sentido da Federação. Base: Art. 76; Art. 1º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 76; Art. 1º","origin":"authored_current_official_source"}],"scope":"Bateria reequilibrada para cobrir as três partes do assunto: doze itens publicados preservados e oito novos sobre fundamentos, objetivos, relações internacionais e separação dos Poderes. Conferência restrita ao texto constitucional utilizado; não modifica corte temporal de edital histórico.","status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"subject":"Direito Constitucional","version":1,"checked_at":"2026-10-24T21:27:58.671975+00:00","topic_label":"Princípios fundamentais","material_slug":"constitucional-principios-fundamentais-federacao-republica","syllabus_topic_id":"5b5a7f1e-44bf-4cab-903e-199eacd65578"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-24T20:38:35.690514+00:00"},"enrichment":{"id":"d6fba95f-a4de-53ea-a039-c533e2382341","material_slug":"constitucional-principios-fundamentais-federacao-republica","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"bc7a192b8ecdbaaafba0e91e76b4f92675b8d6af676017b8f33334cf41f9489d","content":{"cases":[{"id":"autonomia","steps":["Identifique o efeito pretendido: deixar o Brasil, e não apenas mudar um limite interno.","Leia a união indissolúvel no art. 1º e a autonomia nos termos da Constituição no art. 18.","Não use a consulta para rearranjo interno como autorização de secessão."],"title":"O estado pode transformar autonomia em soberania?","pitfall":"Tratar qualquer aprovação popular como autorização para ignorar as condições constitucionais.","articles":["Art. 1º","Art. 18"],"question":"A consulta local autoriza romper a Federação?","scenario":"Uma assembleia estadual pretende declarar o estado um país independente após consulta local. O projeto usa a expressão “exercício da autonomia”.","variation":{"answer":"O art. 18, § 3º, admite essa hipótese sob condições, como plebiscito da população diretamente interessada e lei complementar do Congresso. Permanecer na Federação muda a análise, sem dispensar requisitos.","scenario":"Os estados querem incorporar-se entre si, permanecendo no Brasil."},"conclusion":"Não. A autonomia constitucional não inclui direito unilateral de separar-se do país."},{"id":"categorias","steps":["Associe distribuição territorial do poder à forma de Estado.","Associe República à forma de governo.","Associe presidencialismo ao sistema de governo e leia os arts. 76 e 77."],"title":"Três etiquetas, três perguntas","pitfall":"Usar as três palavras como se fossem respostas intercambiáveis.","articles":["Art. 1º","Art. 18","Art. 76","Art. 77"],"question":"Como corrigir as três linhas?","scenario":"Um aplicativo de revisão mostra: forma de Estado = República; forma de governo = presidencialismo; sistema de governo = Federação.","variation":{"answer":"Agora a referência é o povo, conforme o art. 1º, parágrafo único. A resposta não é o nome de um sistema de governo.","scenario":"A pergunta troca “sistema de governo” por “titularidade do poder político”."},"conclusion":"Forma de Estado: Federação. Forma de governo: República. Sistema de governo: presidencialismo."},{"id":"reforma","steps":["Separe requisitos procedimentais de limites de conteúdo.","Localize a forma federativa no art. 60, § 4º, I.","Confira a expressão “tendente a abolir”, que não se limita à mudança de um nome."],"title":"Um quórum alto resolve qualquer emenda?","pitfall":"Imaginar que quantidade de votos elimina todos os limites ao poder de reforma.","articles":["Art. 60"],"question":"O procedimento formal elimina a vedação material?","scenario":"Uma proposta obtém apoio para extinguir a forma federativa e sustenta que respeitar dois turnos e três quintos em cada Casa seria suficiente.","variation":{"answer":"Não se presume proibição de toda modificação. Examine se o efeito tende a abolir a forma federativa, além de conferir os demais requisitos constitucionais.","scenario":"A proposta apenas altera uma competência específica, mantendo a estrutura federativa."},"conclusion":"Não. A limitação material continua aplicável mesmo com apoio suficiente para o procedimento de votação."},{"id":"republica","steps":["Reconheça que legitimidade eleitoral não elimina o dever de observar a Constituição.","Consulte a proteção da forma republicana e da prestação de contas no art. 34, VII.","Observe no art. 85 a previsão de crimes de responsabilidade do Presidente, sem presumir culpa em um caso real."],"title":"Eleição dispensa prestar contas?","pitfall":"Confundir origem democrática do mandato com imunidade absoluta ou propriedade privada do cargo.","articles":["Art. 34","Art. 85"],"question":"A eleição produz essas duas consequências?","scenario":"Um governante afirma que a vitória eleitoral lhe permite administrar recursos públicos sem prestar contas e impede qualquer responsabilização constitucional.","variation":{"answer":"Exercer defesa é compatível com a Constituição. A existência de responsabilidade não dispensa processo, competência e garantias aplicáveis.","scenario":"O governante apenas questiona uma acusação e exerce seu direito de defesa."},"conclusion":"Não. Mandato eletivo, dever de prestar contas e mecanismos de responsabilização convivem no regime constitucional."},{"id":"listas-principios","title":"Três listas que não se misturam","scenario":"Um quadro coloca soberania em objetivos, erradicação da pobreza em relações internacionais e asilo político em fundamentos.","question":"Como reconstruir a classificação?","steps":["Separe os arts. 1º, 3º e 4º.","Associe fundamentos à soberania, objetivos à erradicação da pobreza e relações internacionais ao asilo.","Não use apenas a importância de uma ideia para trocar seu lugar textual."],"conclusion":"As categorias constitucionais devem ser corrigidas; valor relevante não é sinônimo de mesma lista.","pitfall":"Memorizar uma lista única sem o dispositivo de referência.","variation":{"scenario":"A pergunta trata da integração dos povos da América Latina.","answer":"A referência é o parágrafo único do art. 4º, com integração econômica, política, social e cultural."},"articles":["Art. 1º","Art. 3º","Art. 4º"]},{"id":"harmonia","title":"Independência sem apagamento dos demais","scenario":"Um resumo ensina que independência permite a cada Poder eliminar os outros quando considerar seus atos inconvenientes.","question":"Essa conclusão cabe no art. 2º?","steps":["Identifique a combinação de independência e harmonia.","Distinga controles constitucionais de supressão de Poderes.","Lembre a proteção à separação do art. 60, § 4º."],"conclusion":"Não. O sistema de controles exige fundamento constitucional e não é autorização de eliminação unilateral.","pitfall":"Transformar freios e contrapesos em supremacia irrestrita de um órgão.","variation":{"scenario":"O exercício questionado é uma competência de controle expressamente prevista.","answer":"Examine a hipótese e o procedimento dessa competência; controle constitucional não se confunde com supressão dos demais."},"articles":["Art. 2º","Art. 60"]}],"illustrations":[]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","title":"Constituição Federal compilada — princípios fundamentais e organização do Estado"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"update","expected_material":{"id":"7c20498d-8989-4cfe-8fd9-46e6bb4bf76f","quiz":[{"a":false,"q":"Estrangeiros e apátridas são cidadãos brasileiros.","why":"Cidadania pressupõe nacionalidade; estrangeiros e apátridas não são cidadãos brasileiros."},{"a":false,"q":"Quem nasce no Brasil, filho de pais estrangeiros que estão a serviço do país deles, é brasileiro nato.","why":"A regra do jus soli exclui os filhos de estrangeiros a serviço de seu país."},{"a":true,"q":"A deportação decorre de situação migratória irregular.","why":"É a retirada compulsória de pessoa em situação migratória irregular."},{"a":false,"q":"Após a EC 131/2023, o brasileiro que adquire outra nacionalidade perde, por isso, a brasileira.","why":"A mera aquisição de outra nacionalidade deixou de gerar a perda; só há perda por cancelamento judicial da naturalização ou por pedido expresso, sem gerar apatridia."},{"a":true,"q":"Filho de brasileiros nascido no exterior enquanto um deles está a serviço do Brasil é brasileiro nato?","why":"CF, art. 12, I, b."},{"a":false,"q":"Todo nascido no exterior de pai ou mãe brasileira é brasileiro nato automaticamente, sem qualquer condição?","why":"CF, art. 12, I, b e c, exige serviço do Brasil ou registro em repartição competente ou residência e opção após maioridade."},{"a":true,"q":"Filho de brasileiro nascido fora do país pode adquirir nacionalidade originária mediante registro em repartição brasileira competente?","why":"CF, art. 12, I, c."},{"a":true,"q":"O nascido no estrangeiro de pai ou mãe brasileira que venha residir no Brasil pode optar pela nacionalidade brasileira após atingir a maioridade?","why":"CF, art. 12, I, c."},{"a":true,"q":"A naturalização ordinária exige, para originários de países de língua portuguesa, residência por um ano ininterrupto e idoneidade moral?","why":"CF, art. 12, II, a."},{"a":true,"q":"Estrangeiro de qualquer nacionalidade residente no Brasil há mais de quinze anos ininterruptos e sem condenação penal pode requerer nacionalidade brasileira?","why":"CF, art. 12, II, b, desde que requeira a nacionalidade brasileira."},{"a":false,"q":"A Constituição permite que lei estabeleça distinção entre brasileiros natos e naturalizados em qualquer situação?","why":"CF, art. 12, § 2º: proíbe distinção salvo nos casos previstos na Constituição."},{"a":true,"q":"O cargo de Presidente da República é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, I."},{"a":true,"q":"O cargo de Ministro do Supremo Tribunal Federal é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, IV."},{"a":false,"q":"O cargo de Ministro de Estado da Justiça é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, VII, reserva especificamente Ministro de Estado da Defesa, não Justiça."},{"a":true,"q":"A Constituição reserva a brasileiros natos os cargos de oficial das Forças Armadas?","why":"CF, art. 12, § 3º, VI."},{"a":false,"q":"Após a EC 131/2023, adquirir outra nacionalidade implica automaticamente perder a brasileira?","why":"CF, art. 12, § 4º: mera aquisição de outra nacionalidade não configura perda automática."},{"a":true,"q":"A perda da nacionalidade pode ocorrer por cancelamento judicial da naturalização em razão de fraude relacionada ao processo de naturalização?","why":"CF, art. 12, § 4º, I, com redação da EC 131/2023."},{"a":false,"q":"Pedido expresso de perda da nacionalidade brasileira pode ser deferido se resultar em apatridia?","why":"CF, art. 12, § 4º, II: ressalva situações que acarretem apatridia."},{"a":true,"q":"A pessoa que renunciou à nacionalidade brasileira pode readquirir a nacionalidade originária nos termos da lei?","why":"CF, art. 12, § 5º."},{"a":true,"q":"A língua portuguesa é o idioma oficial da República Federativa do Brasil?","why":"CF, art. 13, caput."}],"slug":"constitucional-nacionalidade-medidas-retirada","title":"Nacionalidade: brasileiros natos e naturalizados","body_md":"## Conceitos que não se confundem\n\n| Termo | Alcance |\n|---|---|\n| **Nacionalidade** | Só os nacionais (natos ou naturalizados) de um Estado |\n| **Povo** | O conjunto de nacionais |\n| **População** | Nacionais, estrangeiros e apátridas |\n| **Cidadania** | Qualifica o nacional para os direitos políticos, ativos (votar) e passivos (ser votado) |\n\n> **Cuidado:** estrangeiros e apátridas **não** são cidadãos brasileiros.\n\n## Nacionalidade originária e secundária\n\n- **Originária (primária):** resulta de fato natural, o nascimento. É unilateral e independe da vontade do indivíduo.\n- **Secundária (adquirida):** resulta de fato voluntário, a naturalização. É bilateral e depende de requerimento.\n\n## Brasileiros natos (art. 12, I)\n\n1. Nascidos no Brasil, ainda que de pais estrangeiros, desde que estes **não estejam a serviço de seu país** (critério *jus soli*).\n2. Nascidos no estrangeiro, de pai ou mãe brasileiros, **a serviço do Brasil** (critério *jus sanguinis*).\n3. Nascidos no estrangeiro, de pai ou mãe brasileiros, que sejam **registrados em repartição brasileira competente** ou **venham a residir no Brasil e optem**, a qualquer tempo, depois de atingida a maioridade, pela nacionalidade brasileira.\n\n## Brasileiros naturalizados (art. 12, II)\n\n| Naturalização | Requisitos |\n|---|---|\n| **Ordinária** | Originários de países de língua portuguesa: residência por **um ano ininterrupto** e idoneidade moral |\n| **Extraordinária (quinzenária)** | Estrangeiros de qualquer nacionalidade, residentes há **mais de 15 anos ininterruptos**, **sem condenação penal**, que a requeiram |\n\nA lei não pode distinguir natos de naturalizados, **salvo** nos casos previstos na Constituição.\n\n## Cargos privativos de brasileiro nato\n\nPresidente e Vice-Presidente da República, Presidente da Câmara, Presidente do Senado, Ministro do STF, carreira diplomática, oficial das Forças Armadas e Ministro de Estado da Defesa.\n\n## Perda e reaquisição\n\nPerde a nacionalidade brasileira (art. 12, § 4º) quem:\n\n1. tiver **cancelada a naturalização, por sentença judicial**, em virtude de **fraude relacionada ao processo de naturalização** ou de **atentado contra a ordem constitucional e o Estado Democrático**;\n2. fizer **pedido expresso de perda da nacionalidade** perante autoridade brasileira competente, **ressalvadas as situações que acarretem apatridia**.\n\nA **renúncia** (pedido expresso) **não impede** que o interessado **readquira** a nacionalidade brasileira **originária**, nos termos da lei (art. 12, § 5º).\n\n> **Atualização legislativa (conferida no Planalto): Emenda Constitucional nº 131, de 3/10/2023.** Passou a **não** haver perda da nacionalidade pela mera **aquisição de outra nacionalidade**: as antigas alíneas \"a\" e \"b\" do inciso II foram **revogadas**. A perda por cancelamento da naturalização agora exige fraude no processo de naturalização ou atentado contra a ordem constitucional (antes: \"atividade nociva ao interesse nacional\"). Surgiu a **perda a pedido**, vedada se gerar apatridia. Provas anteriores a 2023 que afirmem \"adquirir outra nacionalidade faz perder a brasileira\" estão **desatualizadas**.\n\n## Medidas de retirada ou de proteção\n\n| Medida | Natureza | Ideia central |\n|---|---|---|\n| **Extradição** | Cooperação internacional | Entrega de pessoa a outro Estado que tenha **condenação criminal definitiva** ou responda a **processo penal em curso** (art. 81). Ativa: feita pelo Brasil. Passiva: solicitada ao Brasil |\n| **Expulsão** | Administrativa | Retirada compulsória, com impedimento de reingresso por prazo determinado, com base em **condenação transitada em julgado** por certos crimes (art. 54) |\n| **Deportação** | Administrativa | Retirada compulsória de pessoa em situação migratória **irregular**, precedida de notificação com prazo de regularização não inferior a **60 dias** (art. 50) |\n| **Repatriação** | Administrativa | Devolução de pessoa em situação de impedimento de ingresso, observadas as hipóteses e garantias do art. 49 da Lei de Migração; ausência de visto não resume todos os impedimentos |\n| **Refúgio** | Humanitário | Proteção nas hipóteses do art. 1º da Lei 9.474/1997: perseguição por raça, religião, nacionalidade, grupo social ou opinião política, e grave e generalizada violação de direitos humanos; não presumir decisão apenas coletiva |\n| **Asilo político** | Político | Proteção política, de concessão discricionária, prevista nos arts. 27 a 29 da Lei de Migração; não se confunde com extradição ou refúgio |\n\n> **Atualização legislativa (conferida no Planalto):** essas medidas são hoje regidas pela **Lei nº 13.445/2017 (Lei de Migração)**, que substituiu o antigo Estatuto do Estrangeiro (Lei nº 6.815/1980). Pontos que mudaram a cobrança: a **extradição** cabe também para **instrução de processo penal em curso**, e não só após condenação (art. 81); a **expulsão** exige condenação com **trânsito em julgado** por crime de genocídio, contra a humanidade, de guerra ou de agressão, ou por crime comum doloso com pena privativa de liberdade (art. 54); a **deportação** é precedida de notificação com prazo de regularização de **no mínimo 60 dias** (art. 50). **Não se concede extradição de brasileiro nato** (art. 82, I).\n\n> **Cai em prova:** o brasileiro **nato** não é extraditado. Diferencie **extradição** (cooperação com outro Estado), **expulsão** (condenação por crime) e **deportação** (irregularidade migratória).","summary":"Quem é nato, quem é naturalizado, cargos privativos de nato e as medidas de retirada do estrangeiro.","created_at":"2026-10-01T02:09:32.414894+00:00","discipline":"Direito Constitucional","flashcards":[{"b":"Nacionalidade: vínculo com o Estado (nato ou naturalizado). Cidadania: gozo dos direitos políticos, ativos e passivos.","f":"Nacionalidade × cidadania"},{"b":"Países de língua portuguesa: um ano de residência ininterrupta e idoneidade moral.","f":"Naturalização ordinária"},{"b":"Mais de 15 anos de residência ininterrupta, sem condenação penal, e requerimento.","f":"Naturalização extraordinária (quinzenária)"},{"b":"Presidente e Vice, presidentes da Câmara e do Senado, Ministro do STF, diplomata, oficial das Forças Armadas e Ministro da Defesa.","f":"Cargos privativos de nato"},{"b":"Extradição: entrega a outro Estado por condenação definitiva ou processo penal em curso. Expulsão: retirada por condenação transitada em julgado. Deportação: retirada por situação migratória irregular.","f":"Extradição × expulsão × deportação"}],"sort_order":10,"updated_at":"2026-10-24T18:31:56.295625+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc131.htm","title":"Emenda Constitucional nº 131/2023"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13445.htm","title":"Lei nº 13.445/2017 (Lei de Migração)"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9474.htm","title":"Fonte oficial complementar — l9474.htm"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir dos mapas mentais da pasta Apostilas, com organização e destaques próprios. Normas conferidas nas fontes oficiais (Planalto e Constituição anotada do STF): ver o bloco \"Atualização legislativa\" e as fontes abaixo. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material.","topic_label":"Nacionalidade","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc131.htm","title":"Emenda Constitucional nº 131/2023","sha256":"9299a227db5b305c7e99398cd3c525c48f5008b9077f197bf583f01665708be0"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13445.htm","title":"Lei nº 13.445/2017 (Lei de Migração)","sha256":"12c47d0f0bb28441eff144f345b5cc75adf4d343db7e4f8ecd89255995c2a850"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9474.htm","title":"Fonte oficial complementar — l9474.htm","sha256":"2a3ce423a4726738eefc36299ae12e4fb92a57f2a3a16acf476de34aa75bb01e"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":["Corrigidas simplificações sobre repatriação, asilo e refúgio; mantida a alteração da nacionalidade pela EC 131/2023."],"course_slug":"migracao"},"content_status":"active","practice_review":{"items":[{"a":false,"q":"Estrangeiros e apátridas são cidadãos brasileiros.","why":"Cidadania pressupõe nacionalidade; estrangeiros e apátridas não são cidadãos brasileiros.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Quem nasce no Brasil, filho de pais estrangeiros que estão a serviço do país deles, é brasileiro nato.","why":"A regra do jus soli exclui os filhos de estrangeiros a serviço de seu país.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A deportação decorre de situação migratória irregular.","why":"É a retirada compulsória de pessoa em situação migratória irregular.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Após a EC 131/2023, o brasileiro que adquire outra nacionalidade perde, por isso, a brasileira.","why":"A mera aquisição de outra nacionalidade deixou de gerar a perda; só há perda por cancelamento judicial da naturalização ou por pedido expresso, sem gerar apatridia.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Filho de brasileiros nascido no exterior enquanto um deles está a serviço do Brasil é brasileiro nato?","why":"CF, art. 12, I, b.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Todo nascido no exterior de pai ou mãe brasileira é brasileiro nato automaticamente, sem qualquer condição?","why":"CF, art. 12, I, b e c, exige serviço do Brasil ou registro em repartição competente ou residência e opção após maioridade.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Filho de brasileiro nascido fora do país pode adquirir nacionalidade originária mediante registro em repartição brasileira competente?","why":"CF, art. 12, I, c.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O nascido no estrangeiro de pai ou mãe brasileira que venha residir no Brasil pode optar pela nacionalidade brasileira após atingir a maioridade?","why":"CF, art. 12, I, c.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A naturalização ordinária exige, para originários de países de língua portuguesa, residência por um ano ininterrupto e idoneidade moral?","why":"CF, art. 12, II, a.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Estrangeiro de qualquer nacionalidade residente no Brasil há mais de quinze anos ininterruptos e sem condenação penal pode requerer nacionalidade brasileira?","why":"CF, art. 12, II, b, desde que requeira a nacionalidade brasileira.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"A Constituição permite que lei estabeleça distinção entre brasileiros natos e naturalizados em qualquer situação?","why":"CF, art. 12, § 2º: proíbe distinção salvo nos casos previstos na Constituição.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O cargo de Presidente da República é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O cargo de Ministro do Supremo Tribunal Federal é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, IV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"O cargo de Ministro de Estado da Justiça é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, VII, reserva especificamente Ministro de Estado da Defesa, não Justiça.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A Constituição reserva a brasileiros natos os cargos de oficial das Forças Armadas?","why":"CF, art. 12, § 3º, VI.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Após a EC 131/2023, adquirir outra nacionalidade implica automaticamente perder a brasileira?","why":"CF, art. 12, § 4º: mera aquisição de outra nacionalidade não configura perda automática.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A perda da nacionalidade pode ocorrer por cancelamento judicial da naturalização em razão de fraude relacionada ao processo de naturalização?","why":"CF, art. 12, § 4º, I, com redação da EC 131/2023.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Pedido expresso de perda da nacionalidade brasileira pode ser deferido se resultar em apatridia?","why":"CF, art. 12, § 4º, II: ressalva situações que acarretem apatridia.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A pessoa que renunciou à nacionalidade brasileira pode readquirir a nacionalidade originária nos termos da lei?","why":"CF, art. 12, § 5º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A língua portuguesa é o idioma oficial da República Federativa do Brasil?","why":"CF, art. 13, caput.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}],"status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}],"subject":"Direito Constitucional","version":1,"material_slug":"constitucional-nacionalidade-medidas-retirada","syllabus_topic_id":"ef9221e3-d6c4-4b76-b747-e1a1e89fc1a2"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_active_enrichments":[{"id":"166f5b16-8fb5-5a1c-a199-d6641a16f56d","status":"active","content":{"cases":[{"id":"case-1","steps":["Leia a regra de nascimento em território brasileiro com sua exceção expressa.","A hipótese dos pais estrangeiros a serviço de seu país exige tratamento distinto da regra geral do art. 12, I, a."],"title":"Local de nascimento não basta sempre","pitfall":"Omitir a condição dos pais na alternativa de prova.","articles":["Constituição, art. 12, I, a"],"question":"Ela é brasileira nata apenas por nascer aqui?","scenario":"Uma pessoa nasce no Brasil, filha de estrangeiros que estão a serviço de seu próprio país.","variation":{"answer":"Na hipótese territorial descrita, aplica-se a regra geral de brasileiro nato, sem transferir a exceção anterior.","scenario":"E se os pais estrangeiros não estiverem a serviço de seu país?"},"conclusion":"Não conclua nacionalidade nata só pelo território nesse cenário; analise outras hipóteses constitucionais que eventualmente se apliquem."}],"illustrations":[{"kind":"flow","nodes":["Local de nascimento não basta sempre","Ela é brasileira nata apenas por nascer aqui?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"aefcad2bb097434824e1a363c76e769b88dc43427f9f57e1c0b29c8e183df62e","checked_at":"2026-10-05T04:33:22.631922+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc131.htm","title":"Emenda Constitucional nº 131/2023","sha256":"051d9ef5299add1b4706f68ae925ae51eadf813ac11e289466f50b73fce05da4","checked_at":"2026-10-05T04:33:20.568755+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13445.htm","title":"Lei nº 13.445/2017 (Lei de Migração)","sha256":"6ff7854f7a9e38652198aae29529fab3f399922fbafe3c111ac63f091e9e9755","checked_at":"2026-10-05T04:33:17.995520+00:00"}],"version":"2026-10-05","checked_at":"2026-10-05T04:50:24.464194+00:00","reviewed_at":"2026-10-05T05:00:41.044+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"constitucional-nacionalidade-medidas-retirada","source_body_sha256":"c8d3538470bcef2431bf3eb9378af5df96a4b213c90b9d0c83fd2df200a09ce4"}],"material":{"id":"7c20498d-8989-4cfe-8fd9-46e6bb4bf76f","quiz":[{"q":"Residir no Brasil, por si só, transforma toda pessoa estrangeira em brasileira nata e a habilita a todos os cargos reservados.","a":false,"why":"Residência, nacionalidade e equiparação são categorias distintas. O art. 12 estabelece condições próprias e reserva determinados cargos a brasileiros natos; a simples residência não produz essa transformação."},{"a":false,"q":"Quem nasce no Brasil, filho de pais estrangeiros que estão a serviço do país deles, é brasileiro nato.","why":"A regra do jus soli exclui os filhos de estrangeiros a serviço de seu país."},{"q":"Armas e selo nacionais integram os símbolos constitucionais da República, sem impedir símbolos próprios dos entes nas condições do art. 13.","a":true,"why":"O art. 13, § 1º, enumera os símbolos nacionais, e o § 2º permite símbolos próprios a estados, Distrito Federal e municípios. Não se deve confundir essas duas escalas de identificação."},{"a":false,"q":"Após a EC 131/2023, o brasileiro que adquire outra nacionalidade perde, por isso, a brasileira.","why":"A mera aquisição de outra nacionalidade deixou de gerar a perda; só há perda por cancelamento judicial da naturalização ou por pedido expresso, sem gerar apatridia."},{"a":true,"q":"Filho de brasileiros nascido no exterior enquanto um deles está a serviço do Brasil é brasileiro nato?","why":"CF, art. 12, I, b."},{"a":false,"q":"Todo nascido no exterior de pai ou mãe brasileira é brasileiro nato automaticamente, sem qualquer condição?","why":"CF, art. 12, I, b e c, exige serviço do Brasil ou registro em repartição competente ou residência e opção após maioridade."},{"a":true,"q":"Filho de brasileiro nascido fora do país pode adquirir nacionalidade originária mediante registro em repartição brasileira competente?","why":"CF, art. 12, I, c."},{"a":true,"q":"O nascido no estrangeiro de pai ou mãe brasileira que venha residir no Brasil pode optar pela nacionalidade brasileira após atingir a maioridade?","why":"CF, art. 12, I, c."},{"a":true,"q":"A naturalização ordinária exige, para originários de países de língua portuguesa, residência por um ano ininterrupto e idoneidade moral?","why":"CF, art. 12, II, a."},{"a":true,"q":"Estrangeiro de qualquer nacionalidade residente no Brasil há mais de quinze anos ininterruptos e sem condenação penal pode requerer nacionalidade brasileira?","why":"CF, art. 12, II, b, desde que requeira a nacionalidade brasileira."},{"a":false,"q":"A Constituição permite que lei estabeleça distinção entre brasileiros natos e naturalizados em qualquer situação?","why":"CF, art. 12, § 2º: proíbe distinção salvo nos casos previstos na Constituição."},{"a":true,"q":"O cargo de Presidente da República é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, I."},{"a":true,"q":"O cargo de Ministro do Supremo Tribunal Federal é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, IV."},{"a":false,"q":"O cargo de Ministro de Estado da Justiça é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, VII, reserva especificamente Ministro de Estado da Defesa, não Justiça."},{"a":true,"q":"A Constituição reserva a brasileiros natos os cargos de oficial das Forças Armadas?","why":"CF, art. 12, § 3º, VI."},{"q":"A equiparação do art. 12, § 1º, considera residência permanente e reciprocidade, sem transformar automaticamente o português em brasileiro nato.","a":true,"why":"O dispositivo atribui direitos nas condições e ressalvas constitucionais; não cria uma nova hipótese automática de nacionalidade originária. É preciso distinguir o instituto da naturalização e dos cargos reservados."},{"a":true,"q":"A perda da nacionalidade pode ocorrer por cancelamento judicial da naturalização em razão de fraude relacionada ao processo de naturalização?","why":"CF, art. 12, § 4º, I, com redação da EC 131/2023."},{"a":false,"q":"Pedido expresso de perda da nacionalidade brasileira pode ser deferido se resultar em apatridia?","why":"CF, art. 12, § 4º, II: ressalva situações que acarretem apatridia."},{"a":true,"q":"A pessoa que renunciou à nacionalidade brasileira pode readquirir a nacionalidade originária nos termos da lei?","why":"CF, art. 12, § 5º."},{"a":true,"q":"A língua portuguesa é o idioma oficial da República Federativa do Brasil?","why":"CF, art. 13, caput."}],"slug":"constitucional-nacionalidade-medidas-retirada","title":"Nacionalidade: brasileiros natos e naturalizados","body_md":"## Conceitos que não se confundem\n\n| Termo | Alcance |\n|---|---|\n| **Nacionalidade** | Só os nacionais (natos ou naturalizados) de um Estado |\n| **Povo** | O conjunto de nacionais |\n| **População** | Nacionais, estrangeiros e apátridas |\n| **Cidadania** | Qualifica o nacional para os direitos políticos, ativos (votar) e passivos (ser votado) |\n\n> **Cuidado:** nacionalidade, residência e capacidade eleitoral não são sinônimos; a equiparação de portugueses tem condições e ressalvas constitucionais próprias.\n\n## Nacionalidade originária e secundária\n\n- **Originária (primária):** decorre das hipóteses constitucionais ligadas ao nascimento; conforme a via aplicável, registro ou opção também podem integrar os requisitos.\n- **Secundária (adquirida):** resulta de fato voluntário, a naturalização. É bilateral e depende de requerimento.\n\n## Brasileiros natos (art. 12, I)\n\n1. Nascidos no Brasil, ainda que de pais estrangeiros, desde que estes **não estejam a serviço de seu país** (critério *jus soli*).\n2. Nascidos no estrangeiro, de pai ou mãe brasileiros, **a serviço do Brasil** (critério *jus sanguinis*).\n3. Nascidos no estrangeiro, de pai ou mãe brasileiros, que sejam **registrados em repartição brasileira competente** ou **venham a residir no Brasil e optem**, a qualquer tempo, depois de atingida a maioridade, pela nacionalidade brasileira.\n\n## Brasileiros naturalizados (art. 12, II)\n\n| Naturalização | Requisitos |\n|---|---|\n| **Ordinária** | Originários de países de língua portuguesa: residência por **um ano ininterrupto** e idoneidade moral |\n| **Extraordinária (quinzenária)** | Estrangeiros de qualquer nacionalidade, residentes há **mais de 15 anos ininterruptos**, **sem condenação penal**, que a requeiram |\n\nA lei não pode distinguir natos de naturalizados, **salvo** nos casos previstos na Constituição.\n\n## Cargos privativos de brasileiro nato\n\nPresidente e Vice-Presidente da República, Presidente da Câmara, Presidente do Senado, Ministro do STF, carreira diplomática, oficial das Forças Armadas e Ministro de Estado da Defesa.\n\n## Perda e reaquisição\n\nPerde a nacionalidade brasileira (art. 12, § 4º) quem:\n\n1. tiver **cancelada a naturalização, por sentença judicial**, em virtude de **fraude relacionada ao processo de naturalização** ou de **atentado contra a ordem constitucional e o Estado Democrático**;\n2. fizer **pedido expresso de perda da nacionalidade** perante autoridade brasileira competente, **ressalvadas as situações que acarretem apatridia**.\n\nA **renúncia** (pedido expresso) **não impede** que o interessado **readquira** a nacionalidade brasileira **originária**, nos termos da lei (art. 12, § 5º).\n\n> **Atualização legislativa (conferida no Planalto): Emenda Constitucional nº 131, de 3/10/2023.** Passou a **não** haver perda da nacionalidade pela mera **aquisição de outra nacionalidade**: as antigas alíneas \"a\" e \"b\" do inciso II foram **revogadas**. A perda por cancelamento da naturalização agora exige fraude no processo de naturalização ou atentado contra a ordem constitucional (antes: \"atividade nociva ao interesse nacional\"). Surgiu a **perda a pedido**, vedada se gerar apatridia. Provas anteriores a 2023 que afirmem \"adquirir outra nacionalidade faz perder a brasileira\" estão **desatualizadas**.\n\n## Medidas de retirada ou de proteção\n\n| Medida | Natureza | Ideia central |\n|---|---|---|\n| **Extradição** | Cooperação internacional | Entrega de pessoa a outro Estado que tenha **condenação criminal definitiva** ou responda a **processo penal em curso** (art. 81). Ativa: feita pelo Brasil. Passiva: solicitada ao Brasil |\n| **Expulsão** | Administrativa | Retirada compulsória, com impedimento de reingresso por prazo determinado, com base em **condenação transitada em julgado** por certos crimes (art. 54) |\n| **Deportação** | Administrativa | Retirada compulsória de pessoa em situação migratória **irregular**, precedida de notificação com prazo de regularização não inferior a **60 dias** (art. 50) |\n| **Repatriação** | Administrativa | Devolução de pessoa em situação de impedimento de ingresso, observadas as hipóteses e garantias do art. 49 da Lei de Migração; ausência de visto não resume todos os impedimentos |\n| **Refúgio** | Humanitário | Proteção nas hipóteses do art. 1º da Lei 9.474/1997: perseguição por raça, religião, nacionalidade, grupo social ou opinião política, e grave e generalizada violação de direitos humanos; não presumir decisão apenas coletiva |\n| **Asilo político** | Político | Proteção política, de concessão discricionária, prevista nos arts. 27 a 29 da Lei de Migração; não se confunde com extradição ou refúgio |\n\n> **Atualização legislativa (conferida no Planalto):** essas medidas são hoje regidas pela **Lei nº 13.445/2017 (Lei de Migração)**, que substituiu o antigo Estatuto do Estrangeiro (Lei nº 6.815/1980). Pontos que mudaram a cobrança: a **extradição** cabe também para **instrução de processo penal em curso**, e não só após condenação (art. 81); a **expulsão** exige condenação com **trânsito em julgado** por crime de genocídio, contra a humanidade, de guerra ou de agressão, ou por crime comum doloso com pena privativa de liberdade (art. 54); a **deportação** é precedida de notificação com prazo de regularização de **no mínimo 60 dias** (art. 50). **Não se concede extradição de brasileiro nato** (art. 82, I).\n\n> **Cai em prova:** o brasileiro **nato** não é extraditado. Diferencie **extradição** (cooperação com outro Estado), **expulsão** (condenação por crime) e **deportação** (irregularidade migratória).\n\n## Português equiparado: não confunda equiparação com naturalização\n\nO art. 12, § 1º, prevê atribuição de direitos inerentes ao brasileiro a portugueses com residência permanente no País, se houver reciprocidade em favor de brasileiros, ressalvados os casos constitucionais. Não é correto presumir essa situação apenas pela nacionalidade portuguesa e pela entrada no território.\n\nEsse instituto não transforma automaticamente o beneficiário em brasileiro nato. Antes de responder sobre cargo, direito político ou restrição constitucional, identifique a situação e confira as condições pertinentes. Também não confunda equiparação com os requisitos da naturalização para originários de países de língua portuguesa.\n\n## Registro e opção no nascimento no exterior\n\nNo art. 12, I, c, as vias de registro em repartição brasileira competente e de residência no Brasil com opção após a maioridade não devem ser reduzidas a uma única exigência cumulativa. Leia o caminho do caso concreto. A classificação de nacionalidade originária não autoriza apagar registro ou opção quando a própria hipótese os exige.\n\n## Idioma e símbolos\n\nO art. 13 estabelece o português como idioma oficial e enumera bandeira, hino, armas e selo nacionais como símbolos da República. Estados, Distrito Federal e municípios podem ter símbolos próprios. Idioma oficial, nacionalidade, residência e capacidade eleitoral são categorias distintas.\n\nA seção anterior sobre perda já aplica a EC 131/2023 e foi preservada: não se reintroduz a regra antiga de perda pela mera aquisição de outra nacionalidade. O fundamento amplo de cancelamento por “atividade nociva ao interesse nacional” também não deve substituir a redação constitucional atual.\n","summary":"Quem é nato, quem é naturalizado, cargos privativos de nato e as medidas de retirada do estrangeiro.","created_at":"2026-10-01T02:09:32.414894+00:00","discipline":"Direito Constitucional","flashcards":[{"b":"Nacionalidade: vínculo com o Estado (nato ou naturalizado). Cidadania: gozo dos direitos políticos, ativos e passivos.","f":"Nacionalidade × cidadania"},{"b":"Países de língua portuguesa: um ano de residência ininterrupta e idoneidade moral.","f":"Naturalização ordinária"},{"b":"Mais de 15 anos de residência ininterrupta, sem condenação penal, e requerimento.","f":"Naturalização extraordinária (quinzenária)"},{"b":"Presidente e Vice, presidentes da Câmara e do Senado, Ministro do STF, diplomata, oficial das Forças Armadas e Ministro da Defesa.","f":"Cargos privativos de nato"},{"b":"Extradição: entrega a outro Estado por condenação definitiva ou processo penal em curso. Expulsão: retirada por condenação transitada em julgado. Deportação: retirada por situação migratória irregular.","f":"Extradição × expulsão × deportação"}],"sort_order":10,"updated_at":"2026-10-24T18:31:56.295625+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc131.htm","title":"Emenda Constitucional nº 131/2023"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13445.htm","title":"Lei nº 13.445/2017 (Lei de Migração)"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9474.htm","title":"Fonte oficial complementar — l9474.htm"},{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir dos mapas mentais da pasta Apostilas, com organização e destaques próprios. Normas conferidas nas fontes oficiais (Planalto e Constituição anotada do STF): ver o bloco \"Atualização legislativa\" e as fontes abaixo. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: distinções e casos do recorte constitucional, com fonte compilada atual. Fontes e recortes anteriores foram preservados; não se declara nova auditoria integral dos demais temas. A fixação constitucional recebeu metadados completos e vínculo ao tópico oficial PCPI Delegado cadastrado; o enquadramento em outros editais deve ser conferido.","topic_label":"Nacionalidade","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc131.htm","title":"Emenda Constitucional nº 131/2023","sha256":"9299a227db5b305c7e99398cd3c525c48f5008b9077f197bf583f01665708be0"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13445.htm","title":"Lei nº 13.445/2017 (Lei de Migração)","sha256":"12c47d0f0bb28441eff144f345b5cc75adf4d343db7e4f8ecd89255995c2a850"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9474.htm","title":"Fonte oficial complementar — l9474.htm","sha256":"2a3ce423a4726738eefc36299ae12e4fb92a57f2a3a16acf476de34aa75bb01e"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":["Corrigidas simplificações sobre repatriação, asilo e refúgio; mantida a alteração da nacionalidade pela EC 131/2023."],"course_slug":"migracao"},"content_status":"active","practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-nacionalidade-medidas-retirada","subject":"Direito Constitucional","topic_label":"Nacionalidade","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Revisão dos vinte exercícios constitucionais a partir da fonte compilada consultada. Metadados antigos incompletos foram substituídos por vínculo e evidência verificáveis do edital PCPI Delegado cadastrado; aplicação a outros concursos depende do edital. Não certifica nova auditoria das medidas migratórias do texto anterior. Não são questões de banca.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"q":"Residir no Brasil, por si só, transforma toda pessoa estrangeira em brasileira nata e a habilita a todos os cargos reservados.","a":false,"why":"Residência, nacionalidade e equiparação são categorias distintas. O art. 12 estabelece condições próprias e reserva determinados cargos a brasileiros natos; a simples residência não produz essa transformação.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12","origin":"authored_current_official_source"},{"a":false,"q":"Quem nasce no Brasil, filho de pais estrangeiros que estão a serviço do país deles, é brasileiro nato.","why":"A regra do jus soli exclui os filhos de estrangeiros a serviço de seu país.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, I, a","origin":"preserved_rechecked_official_constitution"},{"q":"Armas e selo nacionais integram os símbolos constitucionais da República, sem impedir símbolos próprios dos entes nas condições do art. 13.","a":true,"why":"O art. 13, § 1º, enumera os símbolos nacionais, e o § 2º permite símbolos próprios a estados, Distrito Federal e municípios. Não se deve confundir essas duas escalas de identificação.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 13, §§ 1º e 2º","origin":"authored_current_official_source"},{"a":false,"q":"Após a EC 131/2023, o brasileiro que adquire outra nacionalidade perde, por isso, a brasileira.","why":"A mera aquisição de outra nacionalidade deixou de gerar a perda; só há perda por cancelamento judicial da naturalização ou por pedido expresso, sem gerar apatridia.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 4º","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"Filho de brasileiros nascido no exterior enquanto um deles está a serviço do Brasil é brasileiro nato?","why":"CF, art. 12, I, b.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, I, b","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"Todo nascido no exterior de pai ou mãe brasileira é brasileiro nato automaticamente, sem qualquer condição?","why":"CF, art. 12, I, b e c, exige serviço do Brasil ou registro em repartição competente ou residência e opção após maioridade.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, I, b e c","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"Filho de brasileiro nascido fora do país pode adquirir nacionalidade originária mediante registro em repartição brasileira competente?","why":"CF, art. 12, I, c.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, I, c","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"O nascido no estrangeiro de pai ou mãe brasileira que venha residir no Brasil pode optar pela nacionalidade brasileira após atingir a maioridade?","why":"CF, art. 12, I, c.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, I, c","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A naturalização ordinária exige, para originários de países de língua portuguesa, residência por um ano ininterrupto e idoneidade moral?","why":"CF, art. 12, II, a.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, II, a","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"Estrangeiro de qualquer nacionalidade residente no Brasil há mais de quinze anos ininterruptos e sem condenação penal pode requerer nacionalidade brasileira?","why":"CF, art. 12, II, b, desde que requeira a nacionalidade brasileira.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, II, b","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"A Constituição permite que lei estabeleça distinção entre brasileiros natos e naturalizados em qualquer situação?","why":"CF, art. 12, § 2º: proíbe distinção salvo nos casos previstos na Constituição.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 2º","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"O cargo de Presidente da República é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 3º, I","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"O cargo de Ministro do Supremo Tribunal Federal é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 3º, IV","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"O cargo de Ministro de Estado da Justiça é privativo de brasileiro nato?","why":"CF, art. 12, § 3º, VII, reserva especificamente Ministro de Estado da Defesa, não Justiça.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 3º, VII","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A Constituição reserva a brasileiros natos os cargos de oficial das Forças Armadas?","why":"CF, art. 12, § 3º, VI.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 3º, VI","origin":"preserved_rechecked_official_constitution"},{"q":"A equiparação do art. 12, § 1º, considera residência permanente e reciprocidade, sem transformar automaticamente o português em brasileiro nato.","a":true,"why":"O dispositivo atribui direitos nas condições e ressalvas constitucionais; não cria uma nova hipótese automática de nacionalidade originária. É preciso distinguir o instituto da naturalização e dos cargos reservados.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 1º","origin":"authored_current_official_source"},{"a":true,"q":"A perda da nacionalidade pode ocorrer por cancelamento judicial da naturalização em razão de fraude relacionada ao processo de naturalização?","why":"CF, art. 12, § 4º, I, com redação da EC 131/2023.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 4º, I","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"Pedido expresso de perda da nacionalidade brasileira pode ser deferido se resultar em apatridia?","why":"CF, art. 12, § 4º, II: ressalva situações que acarretem apatridia.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 4º, II","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A pessoa que renunciou à nacionalidade brasileira pode readquirir a nacionalidade originária nos termos da lei?","why":"CF, art. 12, § 5º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 12, § 5º","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A língua portuguesa é o idioma oficial da República Federativa do Brasil?","why":"CF, art. 13, caput.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 13","origin":"preserved_rechecked_official_constitution"}]},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"enrichment":{"id":"1d108521-7ca3-541f-a040-f0419e7ec423","material_slug":"constitucional-nacionalidade-medidas-retirada","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"a5fc588c0592974f0de7428803050dbcb371ed3592ff65157aea38470d571c30","content":{"cases":[{"id":"case-1","steps":["Leia a regra de nascimento em território brasileiro com sua exceção expressa.","A hipótese dos pais estrangeiros a serviço de seu país exige tratamento distinto da regra geral do art. 12, I, a."],"title":"Local de nascimento não basta sempre","pitfall":"Omitir a condição dos pais na alternativa de prova.","articles":["Constituição, art. 12, I, a"],"question":"Ela é brasileira nata apenas por nascer aqui?","scenario":"Uma pessoa nasce no Brasil, filha de estrangeiros que estão a serviço de seu próprio país.","variation":{"answer":"Na hipótese territorial descrita, aplica-se a regra geral de brasileiro nato, sem transferir a exceção anterior.","scenario":"E se os pais estrangeiros não estiverem a serviço de seu país?"},"conclusion":"Não conclua nacionalidade nata só pelo território nesse cenário; analise outras hipóteses constitucionais que eventualmente se apliquem."},{"id":"portugues-equiparado","title":"Equiparação não cria nacionalidade originária","scenario":"Uma pessoa portuguesa com situação de equiparação pretende ocupar cargo de ministro do STF afirmando que recebeu automaticamente nacionalidade brasileira originária.","question":"Qual distinção deve ser feita?","steps":["Leia as condições do art. 12, § 1º, inclusive as ressalvas constitucionais.","Separe atribuição de direitos e aquisição de nacionalidade.","Confira o cargo reservado a brasileiro nato no § 3º."],"conclusion":"A equiparação não transforma automaticamente a pessoa em brasileira nata nem elimina a reserva constitucional do cargo.","pitfall":"Tratar residência, equiparação, naturalização e nacionalidade originária como um único instituto.","variation":{"scenario":"O interessado busca naturalização por ser originário de país de língua portuguesa.","answer":"Agora é necessário conferir a hipótese de naturalização e seus requisitos, sem usar automaticamente o regime da equiparação."},"articles":["Art. 12, § 1º","Art. 12, § 3º"]},{"id":"registro-opcao","title":"Duas vias para nascimento no exterior","scenario":"Filha de pessoa brasileira nasce no exterior e é registrada em repartição brasileira competente. O resumo exige sempre, além do registro, residência no Brasil e opção após a maioridade.","question":"O resumo respeita as alternativas do art. 12, I, c?","steps":["Identifique a filiação brasileira e o registro informado.","Leia a separação entre a via de registro e a de residência com opção.","Não transforme o conectivo alternativo em soma obrigatória de todas as condições."],"conclusion":"Não. As vias constitucionais precisam ser distinguidas conforme o caso.","pitfall":"Converter todos os caminhos em uma única lista cumulativa.","variation":{"scenario":"Não há registro, e a pessoa invoca a via de residência e opção.","answer":"Agora os requisitos dessa via devem ser conferidos; não se pode presumir preenchimento apenas pelo nascimento no exterior."},"articles":["Art. 12, I, c"]}],"illustrations":[{"kind":"flow","nodes":["Local de nascimento não basta sempre","Ela é brasileira nata apenas por nascer aqui?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"aefcad2bb097434824e1a363c76e769b88dc43427f9f57e1c0b29c8e183df62e","checked_at":"2026-10-05T04:33:22.631922+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc131.htm","title":"Emenda Constitucional nº 131/2023","sha256":"051d9ef5299add1b4706f68ae925ae51eadf813ac11e289466f50b73fce05da4","checked_at":"2026-10-05T04:33:20.568755+00:00"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13445.htm","title":"Lei nº 13.445/2017 (Lei de Migração)","sha256":"6ff7854f7a9e38652198aae29529fab3f399922fbafe3c111ac63f091e9e9755","checked_at":"2026-10-05T04:33:17.995520+00:00"},{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}},{"kind":"update","expected_material":{"id":"b82da9ff-297d-44cc-b1fb-5e4d0c164726","quiz":[{"a":true,"q":"O voto é facultativo para os maiores de 70 anos.","why":"Também é facultativo para analfabetos e para maiores de 16 e menores de 18 anos."},{"a":false,"q":"A Constituição admite a cassação de direitos políticos em caso de improbidade administrativa.","why":"A cassação é vedada; a improbidade pode gerar suspensão, nos casos do art. 15."},{"a":true,"q":"A idade mínima para ser Senador é de 35 anos.","why":"Presidente, Vice-Presidente e Senador exigem 35 anos."},{"a":true,"q":"O alistamento eleitoral e o voto são obrigatórios para maiores de 18 anos, ressalvadas as exceções constitucionais?","why":"CF, art. 14, § 1º, I."},{"a":true,"q":"O voto é facultativo para analfabetos?","why":"CF, art. 14, § 1º, II, a."},{"a":true,"q":"O voto é facultativo para maiores de 16 e menores de 18 anos?","why":"CF, art. 14, § 1º, II, c."},{"a":false,"q":"Estrangeiros podem alistar-se como eleitores brasileiros apenas por residirem no país?","why":"CF, art. 14, § 2º: estrangeiros não podem alistar-se, ressalvadas situações específicas decorrentes de normas constitucionais e tratados."},{"a":false,"q":"Conscritos durante o serviço militar obrigatório podem alistar-se como eleitores?","why":"CF, art. 14, § 2º: conscritos não podem alistar-se durante o serviço militar obrigatório."},{"a":true,"q":"Filiação partidária integra as condições constitucionais de elegibilidade?","why":"CF, art. 14, § 3º, V."},{"a":true,"q":"O domicílio eleitoral na circunscrição é condição de elegibilidade?","why":"CF, art. 14, § 3º, IV."},{"a":true,"q":"A idade mínima constitucional para Deputado Federal é 21 anos?","why":"CF, art. 14, § 3º, VI, c."},{"a":true,"q":"A idade mínima constitucional para Governador é 30 anos?","why":"CF, art. 14, § 3º, VI, b."},{"a":true,"q":"A idade mínima constitucional para Vereador é 18 anos?","why":"CF, art. 14, § 3º, VI, d."},{"a":true,"q":"Analfabetos são inelegíveis segundo a Constituição?","why":"CF, art. 14, § 4º."},{"a":false,"q":"Os inalistáveis são elegíveis se tiverem apoio de partido político?","why":"CF, art. 14, § 4º: inalistáveis são inelegíveis."},{"a":true,"q":"Presidente da República pode ser reeleito para um único período subsequente?","why":"CF, art. 14, § 5º."},{"a":true,"q":"Chefe do Executivo que pretenda concorrer a outro cargo deve renunciar ao mandato até seis meses antes do pleito?","why":"CF, art. 14, § 6º."},{"a":true,"q":"A Constituição admite perda ou suspensão de direitos políticos nos casos taxativamente indicados no art. 15?","why":"CF, art. 15, vedada a cassação."},{"a":true,"q":"Condenação criminal transitada em julgado pode gerar suspensão de direitos políticos enquanto durarem seus efeitos?","why":"CF, art. 15, III."},{"a":false,"q":"Lei que altera o processo eleitoral pode ser aplicada à eleição que ocorra até um ano de sua vigência?","why":"CF, art. 16: lei entra em vigor na publicação, mas não se aplica à eleição que ocorra até um ano da vigência."}],"slug":"constitucional-direitos-politicos-elegibilidade","title":"Direitos políticos, elegibilidade e partidos políticos","body_md":"## Formas de exercício da soberania popular\n\n**Sufrágio universal**, **voto direto e secreto**, **plebiscito**, **referendo** e **iniciativa popular**.\n\n| | Plebiscito | Referendo |\n|---|---|---|\n| **Consulta** | Ao povo, sobre matéria relevante (constitucional, legislativa ou administrativa) | Igual |\n| **Quando** | **Antes** do ato | **Depois** do ato |\n| **Para quê** | Aprovar ou denegar | Ratificar ou rejeitar |\n\nA convocação é feita pelo **Congresso Nacional**.\n\n## Voto\n\n| Situação | Voto |\n|---|---|\n| Maiores de 18 anos | **Obrigatório** |\n| Analfabetos, maiores de 70 anos, maiores de 16 e menores de 18 | **Facultativo** |\n| Estrangeiros e conscritos (durante o serviço militar obrigatório) | **Inalistáveis** |\n\n## Condições de elegibilidade\n\nNacionalidade brasileira, pleno exercício dos direitos políticos, alistamento eleitoral, domicílio eleitoral na circunscrição, filiação partidária e **idade mínima**:\n\n| Cargo | Idade mínima |\n|---|---|\n| Presidente, Vice-Presidente e Senador | **35** anos |\n| Governador e Vice-Governador | **30** anos |\n| Deputado, Prefeito, Vice-Prefeito e Juiz de paz | **21** anos |\n| Vereador | **18** anos |\n\nOs **analfabetos** são **inelegíveis**.\n\n## Militar alistável\n\n- **Menos de 10 anos de serviço:** deve afastar-se da atividade.\n- **Mais de 10 anos:** é agregado pela autoridade superior e, se eleito, passa para a inatividade.\n\n## Impugnação do mandato eletivo\n\nPerante a **Justiça Eleitoral**, no prazo de **15 dias** contados da diplomação, nos casos de abuso do poder econômico, corrupção ou fraude.\n\n## Perda × suspensão\n\nÉ **vedada a cassação** de direitos políticos. A perda ou a suspensão só ocorre nos casos:\n\n- cancelamento da naturalização por sentença transitada em julgado;\n- incapacidade civil absoluta;\n- condenação criminal transitada em julgado, enquanto durarem seus efeitos;\n- recusa de cumprir obrigação a todos imposta ou prestação alternativa;\n- improbidade administrativa.\n\n## Partidos políticos (art. 17)\n\nÉ **livre** a criação, fusão, incorporação e extinção, com caráter nacional e prestação de contas à Justiça Eleitoral. São **proibidos** o recebimento de recursos de entidade ou governo estrangeiros e a subordinação a eles. Têm **autonomia** para definir sua estrutura interna, a escolha, formação e duração de seus órgãos e para formar coligações nas eleições majoritárias, nos termos da lei.\n\n> **Cai em prova:** a Constituição **veda a cassação** dos direitos políticos. Só existem perda e suspensão, nas hipóteses do art. 15.\n\n> **Atualização legislativa (conferida na Constituição anotada do STF):** a **EC nº 97/2017** deu nova redação ao art. 17, § 1º: os partidos têm autonomia para adotar o regime de suas coligações **nas eleições majoritárias**, sendo **vedada a coligação nas eleições proporcionais**. Foram conferidos o art. 14, § 3º, VI (idades de 35, 30, 21 e 18 anos), o art. 14, § 4º (inelegíveis: inalistáveis e analfabetos) e as cinco hipóteses do art. 15 (naturalização cancelada, incapacidade civil absoluta, condenação criminal transitada, recusa de obrigação a todos imposta e improbidade administrativa).","summary":"Sufrágio, plebiscito e referendo, idades mínimas, condições de elegibilidade e a diferença entre suspensão e perda.","created_at":"2026-10-01T02:09:32.414894+00:00","discipline":"Direito Constitucional","flashcards":[{"b":"Plebiscito é anterior ao ato (aprovar ou denegar); referendo é posterior (ratificar ou rejeitar).","f":"Plebiscito × referendo"},{"b":"35 anos.","f":"Idade mínima: Presidente, Vice e Senador"},{"b":"30 anos.","f":"Idade mínima: Governador e Vice"},{"b":"21 anos. Vereador: 18 anos.","f":"Idade mínima: Deputado, Prefeito e Juiz de paz"},{"b":"É vedada. Só há perda ou suspensão, nas hipóteses do art. 15 da Constituição.","f":"Cassação de direitos políticos"}],"sort_order":20,"updated_at":"2026-10-24T18:31:58.781239+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir dos mapas mentais da pasta Apostilas, com organização e destaques próprios. Normas conferidas nas fontes oficiais (Planalto e Constituição anotada do STF): ver o bloco \"Atualização legislativa\" e as fontes abaixo. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material.","topic_label":"Direitos políticos","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":[],"course_slug":null},"content_status":"active","practice_review":{"items":[{"a":true,"q":"O voto é facultativo para os maiores de 70 anos.","why":"Também é facultativo para analfabetos e para maiores de 16 e menores de 18 anos.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"A Constituição admite a cassação de direitos políticos em caso de improbidade administrativa.","why":"A cassação é vedada; a improbidade pode gerar suspensão, nos casos do art. 15.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A idade mínima para ser Senador é de 35 anos.","why":"Presidente, Vice-Presidente e Senador exigem 35 anos.","origin":"preserved_published","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O alistamento eleitoral e o voto são obrigatórios para maiores de 18 anos, ressalvadas as exceções constitucionais?","why":"CF, art. 14, § 1º, I.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O voto é facultativo para analfabetos?","why":"CF, art. 14, § 1º, II, a.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O voto é facultativo para maiores de 16 e menores de 18 anos?","why":"CF, art. 14, § 1º, II, c.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Estrangeiros podem alistar-se como eleitores brasileiros apenas por residirem no país?","why":"CF, art. 14, § 2º: estrangeiros não podem alistar-se, ressalvadas situações específicas decorrentes de normas constitucionais e tratados.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Conscritos durante o serviço militar obrigatório podem alistar-se como eleitores?","why":"CF, art. 14, § 2º: conscritos não podem alistar-se durante o serviço militar obrigatório.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Filiação partidária integra as condições constitucionais de elegibilidade?","why":"CF, art. 14, § 3º, V.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"O domicílio eleitoral na circunscrição é condição de elegibilidade?","why":"CF, art. 14, § 3º, IV.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A idade mínima constitucional para Deputado Federal é 21 anos?","why":"CF, art. 14, § 3º, VI, c.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A idade mínima constitucional para Governador é 30 anos?","why":"CF, art. 14, § 3º, VI, b.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A idade mínima constitucional para Vereador é 18 anos?","why":"CF, art. 14, § 3º, VI, d.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Analfabetos são inelegíveis segundo a Constituição?","why":"CF, art. 14, § 4º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Os inalistáveis são elegíveis se tiverem apoio de partido político?","why":"CF, art. 14, § 4º: inalistáveis são inelegíveis.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Presidente da República pode ser reeleito para um único período subsequente?","why":"CF, art. 14, § 5º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Chefe do Executivo que pretenda concorrer a outro cargo deve renunciar ao mandato até seis meses antes do pleito?","why":"CF, art. 14, § 6º.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"A Constituição admite perda ou suspensão de direitos políticos nos casos taxativamente indicados no art. 15?","why":"CF, art. 15, vedada a cassação.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":true,"q":"Condenação criminal transitada em julgado pode gerar suspensão de direitos políticos enquanto durarem seus efeitos?","why":"CF, art. 15, III.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"},{"a":false,"q":"Lei que altera o processo eleitoral pode ser aplicada à eleição que ocorra até um ano de sua vigência?","why":"CF, art. 16: lei entra em vigor na publicação, mas não se aplica à eleição que ocorra até um ano da vigência.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}],"status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}],"subject":"Direito Constitucional","version":1,"material_slug":"constitucional-direitos-politicos-elegibilidade","syllabus_topic_id":"ef9221e3-d6c4-4b76-b747-e1a1e89fc1a2"},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"expected_active_enrichments":[{"id":"621b2010-79a1-54cb-95bc-a0ec7b18c747","status":"active","content":{"cases":[{"id":"case-1","steps":["A Constituição fixa 21 anos para prefeito e 30 para governador.","Compare com 22, sem presumir que basta uma idade única para todos os cargos."],"title":"Idade mínima muda conforme o cargo","pitfall":"Confundir idade de voto facultativo ou obrigatório com idade de candidatura.","articles":["Constituição, art. 14, § 3º, VI"],"question":"A idade satisfaz os dois cargos?","scenario":"Uma pessoa de 22 anos reúne as demais condições de elegibilidade. Compare candidatura a prefeito e a governador.","variation":{"answer":"A idade constitucional é 35 anos; não se transporta a regra de prefeito.","scenario":"E para presidente da República?"},"conclusion":"A idade atende ao cargo de prefeito, mas não ao de governador; as demais condições e impedimentos continuam necessários."}],"illustrations":[{"kind":"flow","nodes":["Idade mínima muda conforme o cargo","A idade satisfaz os dois cargos?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"aefcad2bb097434824e1a363c76e769b88dc43427f9f57e1c0b29c8e183df62e","checked_at":"2026-10-05T04:33:22.631922+00:00"}],"version":"2026-10-05","checked_at":"2026-10-05T04:50:24.464194+00:00","reviewed_at":"2026-10-05T05:00:41.277+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","material_slug":"constitucional-direitos-politicos-elegibilidade","source_body_sha256":"8e2af8aa08fb8ff4f4d16bd2bf0558d86f6fb05518f55f9fc708f1c98d7a18b3"}],"material":{"id":"b82da9ff-297d-44cc-b1fb-5e4d0c164726","quiz":[{"a":true,"q":"O voto é facultativo para os maiores de 70 anos.","why":"Também é facultativo para analfabetos e para maiores de 16 e menores de 18 anos."},{"a":false,"q":"A Constituição admite a cassação de direitos políticos em caso de improbidade administrativa.","why":"A cassação é vedada; a improbidade pode gerar suspensão, nos casos do art. 15."},{"a":true,"q":"A idade mínima para ser Senador é de 35 anos.","why":"Presidente, Vice-Presidente e Senador exigem 35 anos."},{"a":true,"q":"O alistamento eleitoral e o voto são obrigatórios para maiores de 18 anos, ressalvadas as exceções constitucionais?","why":"CF, art. 14, § 1º, I."},{"a":true,"q":"O voto é facultativo para analfabetos?","why":"CF, art. 14, § 1º, II, a."},{"a":true,"q":"O voto é facultativo para maiores de 16 e menores de 18 anos?","why":"CF, art. 14, § 1º, II, c."},{"a":false,"q":"Estrangeiros podem alistar-se como eleitores brasileiros apenas por residirem no país?","why":"CF, art. 14, § 2º: estrangeiros não podem alistar-se, ressalvadas situações específicas decorrentes de normas constitucionais e tratados."},{"a":false,"q":"Conscritos durante o serviço militar obrigatório podem alistar-se como eleitores?","why":"CF, art. 14, § 2º: conscritos não podem alistar-se durante o serviço militar obrigatório."},{"a":true,"q":"Filiação partidária integra as condições constitucionais de elegibilidade?","why":"CF, art. 14, § 3º, V."},{"a":true,"q":"O domicílio eleitoral na circunscrição é condição de elegibilidade?","why":"CF, art. 14, § 3º, IV."},{"a":true,"q":"A idade mínima constitucional para Deputado Federal é 21 anos?","why":"CF, art. 14, § 3º, VI, c."},{"a":true,"q":"A idade mínima constitucional para Governador é 30 anos?","why":"CF, art. 14, § 3º, VI, b."},{"a":true,"q":"A idade mínima constitucional para Vereador é 18 anos?","why":"CF, art. 14, § 3º, VI, d."},{"a":true,"q":"Analfabetos são inelegíveis segundo a Constituição?","why":"CF, art. 14, § 4º."},{"a":false,"q":"Os inalistáveis são elegíveis se tiverem apoio de partido político?","why":"CF, art. 14, § 4º: inalistáveis são inelegíveis."},{"a":true,"q":"Presidente da República pode ser reeleito para um único período subsequente?","why":"CF, art. 14, § 5º."},{"a":true,"q":"Chefe do Executivo que pretenda concorrer a outro cargo deve renunciar ao mandato até seis meses antes do pleito?","why":"CF, art. 14, § 6º."},{"a":true,"q":"A Constituição admite perda ou suspensão de direitos políticos nos casos taxativamente indicados no art. 15?","why":"CF, art. 15, vedada a cassação."},{"a":true,"q":"Condenação criminal transitada em julgado pode gerar suspensão de direitos políticos enquanto durarem seus efeitos?","why":"CF, art. 15, III."},{"a":false,"q":"Lei que altera o processo eleitoral pode ser aplicada à eleição que ocorra até um ano de sua vigência?","why":"CF, art. 16: lei entra em vigor na publicação, mas não se aplica à eleição que ocorra até um ano da vigência."}],"slug":"constitucional-direitos-politicos-elegibilidade","title":"Direitos políticos, elegibilidade e partidos políticos","body_md":"## Formas de exercício da soberania popular\n\n**Sufrágio universal**, **voto direto e secreto**, **plebiscito**, **referendo** e **iniciativa popular**.\n\n| | Plebiscito | Referendo |\n|---|---|---|\n| **Consulta** | Ao povo, sobre matéria relevante (constitucional, legislativa ou administrativa) | Igual |\n| **Quando** | **Antes** do ato | **Depois** do ato |\n| **Para quê** | Aprovar ou denegar | Ratificar ou rejeitar |\n\nNo âmbito nacional, o Congresso tem competência para **autorizar referendo e convocar plebiscito** (art. 49, XV). As consultas locais possuem disciplina constitucional própria, explicada no complemento abaixo.\n\n## Voto\n\n| Situação | Voto |\n|---|---|\n| Maiores de 18 anos | **Obrigatório** |\n| Analfabetos, maiores de 70 anos, maiores de 16 e menores de 18 | **Facultativo** |\n| Estrangeiros e conscritos (durante o serviço militar obrigatório) | **Inalistáveis** |\n\n## Condições de elegibilidade\n\nNacionalidade brasileira, pleno exercício dos direitos políticos, alistamento eleitoral, domicílio eleitoral na circunscrição, filiação partidária e **idade mínima**:\n\n| Cargo | Idade mínima |\n|---|---|\n| Presidente, Vice-Presidente e Senador | **35** anos |\n| Governador e Vice-Governador | **30** anos |\n| Deputado, Prefeito, Vice-Prefeito e Juiz de paz | **21** anos |\n| Vereador | **18** anos |\n\nOs **analfabetos** são **inelegíveis**.\n\n## Militar alistável\n\n- **Menos de 10 anos de serviço:** deve afastar-se da atividade.\n- **Mais de 10 anos:** é agregado pela autoridade superior e, se eleito, passa automaticamente para a inatividade no ato da diplomação.\n\n## Impugnação do mandato eletivo\n\nPerante a **Justiça Eleitoral**, no prazo de **15 dias** contados da diplomação, nos casos de abuso do poder econômico, corrupção ou fraude.\n\n## Perda × suspensão\n\nÉ **vedada a cassação** de direitos políticos. A perda ou a suspensão só ocorre nos casos:\n\n- cancelamento da naturalização por sentença transitada em julgado;\n- incapacidade civil absoluta;\n- condenação criminal transitada em julgado, enquanto durarem seus efeitos;\n- recusa de cumprir obrigação a todos imposta ou prestação alternativa;\n- improbidade administrativa.\n\n## Partidos políticos (art. 17)\n\nÉ **livre** a criação, fusão, incorporação e extinção, com caráter nacional e prestação de contas à Justiça Eleitoral. São **proibidos** o recebimento de recursos de entidade ou governo estrangeiros e a subordinação a eles. Têm **autonomia** para definir sua estrutura interna, a escolha, formação e duração de seus órgãos e para formar coligações nas eleições majoritárias, nos termos da lei.\n\n> **Cai em prova:** a Constituição **veda a cassação** dos direitos políticos. Só existem perda e suspensão, nas hipóteses do art. 15.\n\n> **Atualização legislativa (conferida na Constituição anotada do STF):** a **EC nº 97/2017** deu nova redação ao art. 17, § 1º: os partidos têm autonomia para adotar o regime de suas coligações **nas eleições majoritárias**, sendo **vedada a coligação nas eleições proporcionais**. Foram conferidos o art. 14, § 3º, VI (idades de 35, 30, 21 e 18 anos), o art. 14, § 4º (inelegíveis: inalistáveis e analfabetos) e as cinco hipóteses do art. 15 (naturalização cancelada, incapacidade civil absoluta, condenação criminal transitada, recusa de obrigação a todos imposta e improbidade administrativa).\n\n## Consultas locais e controle do mandato\n\nPlebiscito e referendo nacionais devem ser distinguidos das consultas locais do art. 14, §§ 12 e 13. O texto atual prevê consultas aprovadas pelas Câmaras Municipais e encaminhadas à Justiça Eleitoral nas condições constitucionais. A competência nacional do Congresso não deve ser ensinada como regra única de toda consulta em qualquer esfera.\n\nA ação de impugnação de mandato eletivo tem as condições do art. 14, §§ 10 e 11, incluindo prazo de quinze dias da diplomação e tramitação em segredo de justiça. Isso não autoriza usar a ação de modo temerário ou de manifesta má-fé. As hipóteses do art. 15 precisam ser aplicadas com a legislação atual: não presuma perda ou suspensão a partir de categorias clínicas e rótulos antigos.\n\n## Partidos: coligação, mandato e recursos não são a mesma regra\n\nO art. 17, § 1º, distingue coligações majoritárias e veda coligações proporcionais. Filiação, eleição e preservação do mandato exigem examinar a categoria do cargo. O § 6º trata de deputados e vereadores que se desligam do partido, com ressalvas de anuência ou justa causa legal. Não se deve estender automaticamente cada consequência a todo cargo eletivo indistintamente.\n\n| Previsão constitucional | Âmbito que não deve ser confundido |\n| --- | --- |\n| Art. 17, § 7º | Mínimo de 5% do fundo partidário para programas de promoção e difusão da participação política das mulheres |\n| Art. 17, § 8º | Mínimo de 30% dos recursos e do tempo de propaganda nas condições previstas para candidatas, observada a proporcionalidade e a disciplina constitucional |\n| Art. 17, § 9º | Aplicação de 30% dos recursos dos fundos indicados destinados a campanhas em candidaturas de pessoas pretas e pardas, no recorte do dispositivo |\n\nEssas previsões possuem objetos e bases próprios. Não some percentuais mecanicamente, não os transfira a qualquer fonte de dinheiro e confira as normas eleitorais atuais antes de resolver distribuição concreta. A Constituição não resume todas as regras de financiamento e prestação de contas.\n","summary":"Sufrágio, plebiscito e referendo, idades mínimas, condições de elegibilidade e a diferença entre suspensão e perda.","created_at":"2026-10-01T02:09:32.414894+00:00","discipline":"Direito Constitucional","flashcards":[{"b":"Plebiscito é anterior ao ato (aprovar ou denegar); referendo é posterior (ratificar ou rejeitar).","f":"Plebiscito × referendo"},{"b":"35 anos.","f":"Idade mínima: Presidente, Vice e Senador"},{"b":"30 anos.","f":"Idade mínima: Governador e Vice"},{"b":"21 anos. Vereador: 18 anos.","f":"Idade mínima: Deputado, Prefeito e Juiz de paz"},{"b":"É vedada. Só há perda ou suspensão, nas hipóteses do art. 15 da Constituição.","f":"Cassação de direitos políticos"}],"sort_order":20,"updated_at":"2026-10-24T18:31:58.781239+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"reviewed_at":"2026-10-07T21:40:50.944228+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","source_note":"Reescrito a partir dos mapas mentais da pasta Apostilas, com organização e destaques próprios. Normas conferidas nas fontes oficiais (Planalto e Constituição anotada do STF): ver o bloco \"Atualização legislativa\" e as fontes abaixo. Conferência de atualização em 07/10/2026: consulte o quadro de mudanças, vigência e correções deste material. Complemento de 24/10/2026: distinções e casos do recorte constitucional, com fonte compilada atual. Fontes e recortes anteriores foram preservados; não se declara nova auditoria integral dos demais temas. A fixação constitucional recebeu metadados completos e vínculo ao tópico oficial PCPI Delegado cadastrado; o enquadramento em outros editais deve ser conferido.","topic_label":"Direitos políticos","contest_name":"Polícia Federal","legal_review":{"scope":"Conferência das fontes oficiais deste módulo em 07/10/2026. Mudanças de 2025 e 2026 nos diplomas consultados estão destacadas abaixo; sua cobrança depende do recorte e da data de corte do edital.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","state":"reference","title":"EC 136/2025","summary":"Atualiza limites, orçamento e atualização de precatórios, além de parcelamentos previdenciários. As regras possuem marcos próprios, inclusive efeitos específicos em 2026, 2027 e 2036; não aplicar todos os percentuais de uma vez.","vigency":"Em vigor desde a publicação em 10/09/2025; observar os marcos expressos de cada dispositivo, inclusive efeitos futuros.","articles":["CF, arts. 100 e 165","ADCT, arts. 76-B, 97, 101 e 115 a 117"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","state":"effective","title":"EC 137/2025","summary":"Amplia a não incidência de IPVA para veículos terrestres de passageiros, caminhonetes e mistos com vinte anos ou mais de fabricação, com exceções expressas para micro-ônibus, ônibus, reboques e semirreboques.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial e as exceções do inciso.","articles":["CF, art. 155, § 6º, III"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","state":"effective","title":"EC 138/2025","summary":"Passa a permitir acumulação remunerada de um cargo de professor com outro de qualquer natureza, com compatibilidade de horários e observância do teto. A antiga limitação a cargo técnico ou científico não é a redação atual.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial. Permanecem as condições constitucionais aplicáveis.","articles":["CF, art. 37, XVI, b"]},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","state":"effective","title":"EC 139/2026","summary":"Reconhece os Tribunais de Contas como órgãos permanentes e essenciais e veda sua extinção, criação ou instalação nas condições da nova redação. Compare os arts. 31 e 75, sem reduzir a atualização apenas à vedação de criação.","vigency":"Em vigor na publicação: conferir o art. 2º do ato oficial.","articles":["CF, arts. 31, § 1º, e 75"]},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15484.htm","state":"effective","title":"LEI Nº 15.484/2026","summary":"LEI Nº 15.484/2026","vigency":"Art. 7º Esta Lei entra em vigor após decorridos 30 (trinta) dias de sua publicação oficial. Publicação: 04/08/2026. Entrada em vigor calculada pelo prazo legal: 03/09/2026.","articles":["Art. 105"]}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"6a1f0f56efd9ee984dd432060b2ef38378b50087b291943303d5e84795ba5416"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc136.htm","title":"Emenda Constitucional 136/2025","sha256":"594bbbad74459ba2a0ee9171ac265aab581afee63d4c672486b68278c7284535"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc137.htm","title":"Emenda Constitucional 137/2025","sha256":"1933de34926fe42f01c2cbce6265aa6135c114d808058319b77e28bc8510a6d6"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc138.htm","title":"Emenda Constitucional 138/2025","sha256":"037c5be2e65c76dd2ac7e2d75e2f31914f2dea6172a230b37d2883730421fbdf"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc139.htm","title":"Emenda Constitucional 139/2026","sha256":"4a10a62e3f5c42aafcc3caa07926240bbb2042df0ed084ab30f8510eef312d85"}],"checked_at":"2026-10-07T21:34:23.650731+00:00","corrections":[],"course_slug":null},"content_status":"active","practice_review":{"version":1,"status":"reviewed","material_slug":"constitucional-direitos-politicos-elegibilidade","subject":"Direito Constitucional","topic_label":"Direitos políticos","syllabus_topic_id":"bd6227f4-9ece-4b9f-948f-e45446a51f90","checked_at":"2026-10-24T21:27:58.671975+00:00","scope":"Revisão dos vinte exercícios constitucionais a partir da fonte compilada consultada. Metadados antigos incompletos foram substituídos por vínculo e evidência verificáveis do edital PCPI Delegado cadastrado; aplicação a outros concursos depende do edital. Não certifica nova auditoria das medidas migratórias do texto anterior. Não são questões de banca.","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","sha256":"f392ec09dc8a1be39c563dbe343f78a1093f61c1d3b67a8e81b23c60b496399d","checked_at":"2026-10-24T20:54:33.563025+00:00"}],"items":[{"a":true,"q":"O voto é facultativo para os maiores de 70 anos.","why":"Também é facultativo para analfabetos e para maiores de 16 e menores de 18 anos.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 1º","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"A Constituição admite a cassação de direitos políticos em caso de improbidade administrativa.","why":"A cassação é vedada; a improbidade pode gerar suspensão, nos casos do art. 15.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 15; Art. 37, § 4º","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A idade mínima para ser Senador é de 35 anos.","why":"Presidente, Vice-Presidente e Senador exigem 35 anos.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 3º, VI, a","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"O alistamento eleitoral e o voto são obrigatórios para maiores de 18 anos, ressalvadas as exceções constitucionais?","why":"CF, art. 14, § 1º, I.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 1º, I","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"O voto é facultativo para analfabetos?","why":"CF, art. 14, § 1º, II, a.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 1º, II, a","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"O voto é facultativo para maiores de 16 e menores de 18 anos?","why":"CF, art. 14, § 1º, II, c.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 1º, II, c","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"Estrangeiros podem alistar-se como eleitores brasileiros apenas por residirem no país?","why":"CF, art. 14, § 2º: estrangeiros não podem alistar-se, ressalvadas situações específicas decorrentes de normas constitucionais e tratados.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 2º","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"Conscritos durante o serviço militar obrigatório podem alistar-se como eleitores?","why":"CF, art. 14, § 2º: conscritos não podem alistar-se durante o serviço militar obrigatório.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 2º","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"Filiação partidária integra as condições constitucionais de elegibilidade?","why":"CF, art. 14, § 3º, V.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 3º, V","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"O domicílio eleitoral na circunscrição é condição de elegibilidade?","why":"CF, art. 14, § 3º, IV.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 3º, IV","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A idade mínima constitucional para Deputado Federal é 21 anos?","why":"CF, art. 14, § 3º, VI, c.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 3º, VI, c","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A idade mínima constitucional para Governador é 30 anos?","why":"CF, art. 14, § 3º, VI, b.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 3º, VI, b","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A idade mínima constitucional para Vereador é 18 anos?","why":"CF, art. 14, § 3º, VI, d.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 3º, VI, d","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"Analfabetos são inelegíveis segundo a Constituição?","why":"CF, art. 14, § 4º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 4º","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"Os inalistáveis são elegíveis se tiverem apoio de partido político?","why":"CF, art. 14, § 4º: inalistáveis são inelegíveis.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 4º","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"Presidente da República pode ser reeleito para um único período subsequente?","why":"CF, art. 14, § 5º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 5º","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"Chefe do Executivo que pretenda concorrer a outro cargo deve renunciar ao mandato até seis meses antes do pleito?","why":"CF, art. 14, § 6º.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 14, § 6º","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"A Constituição admite perda ou suspensão de direitos políticos nos casos taxativamente indicados no art. 15?","why":"CF, art. 15, vedada a cassação.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 15","origin":"preserved_rechecked_official_constitution"},{"a":true,"q":"Condenação criminal transitada em julgado pode gerar suspensão de direitos políticos enquanto durarem seus efeitos?","why":"CF, art. 15, III.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 15, III","origin":"preserved_rechecked_official_constitution"},{"a":false,"q":"Lei que altera o processo eleitoral pode ser aplicada à eleição que ocorra até um ano de sua vigência?","why":"CF, art. 16: lei entra em vigor na publicação, mas não se aplica à eleição que ocorra até um ano da vigência.","source_url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm","article":"Art. 16","origin":"preserved_rechecked_official_constitution"}]},"syllabus_topic_order":1,"law_version_checked_at":"2026-10-07T21:34:23.650731+00:00"},"enrichment":{"id":"5b726ab3-2c1e-58fc-ae3b-23b12586568a","material_slug":"constitucional-direitos-politicos-elegibilidade","version":"2026-10-24-constitucional-continuacao-v1","source_body_sha256":"a9c5fc2d4c84800ca928ffc84590fe4997e99abfc55e55c979e7271e979368e2","content":{"cases":[{"id":"case-1","steps":["A Constituição fixa 21 anos para prefeito e 30 para governador.","Compare com 22, sem presumir que basta uma idade única para todos os cargos."],"title":"Idade mínima muda conforme o cargo","pitfall":"Confundir idade de voto facultativo ou obrigatório com idade de candidatura.","articles":["Constituição, art. 14, § 3º, VI"],"question":"A idade satisfaz os dois cargos?","scenario":"Uma pessoa de 22 anos reúne as demais condições de elegibilidade. Compare candidatura a prefeito e a governador.","variation":{"answer":"A idade constitucional é 35 anos; não se transporta a regra de prefeito.","scenario":"E para presidente da República?"},"conclusion":"A idade atende ao cargo de prefeito, mas não ao de governador; as demais condições e impedimentos continuam necessários."},{"id":"consulta-local","title":"Consulta local não é sempre convocação nacional","scenario":"Uma Câmara Municipal aprova consulta sobre questão local para o regime do art. 14, § 12. O resumo afirma que somente o Congresso pode agir em toda consulta local.","question":"Qual âmbito foi confundido?","steps":["Distinga a competência nacional do Congresso e a previsão constitucional de consultas locais.","Confira aprovação municipal e encaminhamento à Justiça Eleitoral.","Examine os prazos, limites operacionais e condições constitucionais, sem presumir convocação irrestrita."],"conclusion":"A regra nacional não deve apagar a hipótese local prevista pela Constituição.","pitfall":"Usar uma frase genérica para todas as esferas e procedimentos.","variation":{"scenario":"A questão é plebiscito nacional na hipótese de competência do Congresso.","answer":"A análise deve retornar ao art. 49, XV, distinguindo autorização de referendo e convocação de plebiscito."},"articles":["Art. 14, §§ 12 e 13","Art. 49, XV"]},{"id":"recursos","title":"Percentuais com bases diferentes","scenario":"Um quadro soma automaticamente o percentual de programas de participação feminina com os de campanhas de candidatas e de pessoas pretas e pardas, tratando tudo como uma única conta indiferenciada.","question":"Por que a conta não pode começar assim?","steps":["Leia separadamente os §§ 7º, 8º e 9º do art. 17.","Identifique finalidade, base dos recursos e destinatários de cada previsão.","Confira a disciplina eleitoral atual para aplicação concreta, sem presumir exclusividade ou soma mecânica."],"conclusion":"Percentuais com objetos e bases diferentes não autorizam conclusão aritmética simples sobre todo o financiamento.","pitfall":"Somar números antes de compreender a hipótese jurídica e os recursos abrangidos.","variation":{"scenario":"O caso se limita ao mínimo de programas de promoção da participação política das mulheres no fundo partidário.","answer":"O ponto de partida é o § 7º, e não a importação automática de todo percentual de campanha de outros dispositivos."},"articles":["Art. 17, §§ 7º a 9º"]}],"illustrations":[{"kind":"flow","nodes":["Idade mínima muda conforme o cargo","A idade satisfaz os dois cargos?","Separar os dados relevantes da regra aplicável","Conferir as condições e testar a variação"],"title":"Mapa do raciocínio","caption":"Observe a sequência de análise e confira os dados do caso abaixo."}]},"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988","sha256":"aefcad2bb097434824e1a363c76e769b88dc43427f9f57e1c0b29c8e183df62e","checked_at":"2026-10-05T04:33:22.631922+00:00"},{"title":"Constituição Federal — texto compilado oficial","url":"https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm"}],"checked_at":"2026-10-24T21:27:58.671975+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-24T21:27:58.671975+00:00"}}]}$constitutional_63dc1420384552ec$::jsonb);
do $guard$
declare p jsonb; r jsonb; m public.study_materials; e public.study_material_enrichments; final_match boolean; before_match boolean; active_ids jsonb; expected_ids jsonb;
begin
 select payload into p from constitutional_batch;
 if not exists(select 1 from public.user_roles where user_id=(p#>>'{rows,0,material,reviewed_by}')::uuid and role::text='admin') then raise exception 'Responsável não é administrador.'; end if;
 if not exists(select 1 from public.syllabus_topics t join public.syllabus_editions se on se.id=t.edition_id join public.content_sources s on s.id=se.source_id
   where t.id=(p#>>'{syllabus,topic,id}')::uuid and t.topic_text=p#>>'{syllabus,topic,topic_text}' and t.content_status='current' and se.status='active' and s.is_official and s.source_type='edital' and s.url=p#>>'{syllabus,source,url}') then raise exception 'Edital oficial ou tópico foi alterado.'; end if;
 for r in select value from jsonb_array_elements(p->'rows') order by value#>>'{material,slug}' loop
  if jsonb_array_length(r#>'{material,quiz}')<>20 or jsonb_array_length(r#>'{material,practice_review,items}')<>20 then raise exception 'Bateria incompleta.'; end if;
  if not exists(select 1 from public.syllabus_topics t join public.syllabus_editions se on se.id=t.edition_id where t.id=(r#>>'{material,practice_review,syllabus_topic_id}')::uuid and t.content_status='current' and se.status='active') then raise exception 'Vínculo de prática não é atual.'; end if;
  select * into m from public.study_materials where slug=r#>>'{material,slug}' for update;
  if r->>'kind'='new' then
   if found and (not (to_jsonb(m) @> ((r->'material')-'reviewed_at'-'law_version_checked_at')) or m.reviewed_at<>(r#>>'{material,reviewed_at}')::timestamptz or m.law_version_checked_at<>(r#>>'{material,law_version_checked_at}')::timestamptz) then raise exception 'Novo módulo já existe com conteúdo diferente: %',r#>>'{material,slug}'; end if;
   if exists(select 1 from public.study_materials x where lower(x.title)=lower(r#>>'{material,title}') and x.slug<>r#>>'{material,slug}' and x.content_status='active') then raise exception 'Título publicado em outro módulo; conferir duplicidade.'; end if;
   expected_ids='[]'::jsonb;
  else
   if not found then raise exception 'Material a complementar não encontrado.'; end if;
   final_match=m.content_status='active' and m.body_md=r#>>'{material,body_md}' and m.quiz=r#>'{material,quiz}' and m.practice_review=r#>'{material,practice_review}' and m.source_note=r#>>'{material,source_note}' and m.legal_basis=r#>'{material,legal_basis}';
   before_match=m.content_status='active' and m.updated_at=(r#>>'{expected_material,updated_at}')::timestamptz and m.body_md=r#>>'{expected_material,body_md}' and m.quiz=r#>'{expected_material,quiz}' and m.practice_review=r#>'{expected_material,practice_review}' and m.source_note=r#>>'{expected_material,source_note}' and m.legal_basis=r#>'{expected_material,legal_basis}';
   if not(final_match or before_match) then raise exception 'Alteração concorrente não foi sobrescrita: %',m.slug; end if;
   select coalesce(jsonb_agg(x->>'id' order by x->>'id'),'[]') into expected_ids from jsonb_array_elements(r->'expected_active_enrichments') x;
  end if;
  perform 1 from public.study_material_enrichments where material_slug=r#>>'{material,slug}' for update;
  select coalesce(jsonb_agg(id::text order by id::text),'[]') into active_ids from public.study_material_enrichments where material_slug=r#>>'{material,slug}' and status='active';
  if active_ids<>expected_ids and active_ids<>jsonb_build_array(r#>>'{enrichment,id}') then raise exception 'Casos ativos alterados em concorrência: %',r#>>'{material,slug}'; end if;
  if r->>'kind'='update' and active_ids=expected_ids and exists(select 1 from jsonb_array_elements(r->'expected_active_enrichments') x left join public.study_material_enrichments y on y.id=(x->>'id')::uuid where y.id is null or not(to_jsonb(y) @> (x-'checked_at'-'reviewed_at')) or y.checked_at<>(x->>'checked_at')::timestamptz or y.reviewed_at<>(x->>'reviewed_at')::timestamptz) then raise exception 'Exemplos anteriores foram alterados.'; end if;
  select * into e from public.study_material_enrichments where material_slug=r#>>'{material,slug}' and version=r#>>'{enrichment,version}';
  if found and (not(to_jsonb(e) @> ((r->'enrichment')-'checked_at'-'reviewed_at')) or e.checked_at<>(r#>>'{enrichment,checked_at}')::timestamptz) then raise exception 'Versão de exemplos existente é diferente.'; end if;
 end loop;
end $guard$;
insert into public.content_sources(source_type,title,issuer,url,status,is_official,checked_at,notes)
select case when s->>'url' like '%stf.jus.br%' then 'sumula' when s->>'url' like '%ConstituicaoCompilado%' then 'constituicao' when s->>'url' like '%conhecimento.fgv.br%' then 'edital' else 'lei' end,
 s->>'title',case when s->>'url' like '%stf.jus.br%' then 'Supremo Tribunal Federal' when s->>'url' like '%conhecimento.fgv.br%' then 'Polícia Civil do Piauí / FGV' else 'Presidência da República — Planalto' end,
 s->>'url','vigente',true,(s->>'checked_at')::timestamptz,'Conferência limitada ao recorte do lote constitucional. SHA-256 do documento consultado: '||(s->>'sha256')
from constitutional_batch p cross join lateral jsonb_array_elements(p.payload->'sources') s
on conflict(url) do nothing;
insert into public.study_materials (id,slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,law_version_checked_at,content_status,reviewed_by,reviewed_at,quiz,flashcards,practice_review,legal_review)
select m.id,m.slug,m.discipline,m.topic_label,m.sort_order,m.title,m.summary,m.body_md,m.contest_name,m.syllabus_topic_order,m.source_note,m.legal_basis,m.law_version_checked_at,m.content_status,m.reviewed_by,m.reviewed_at,m.quiz,m.flashcards,m.practice_review,m.legal_review from constitutional_batch p cross join lateral jsonb_array_elements(p.payload->'rows') r cross join lateral jsonb_populate_record(null::public.study_materials,r->'material') m where r->>'kind'='new' on conflict(slug) do nothing;
update public.study_materials m set body_md=r#>>'{material,body_md}',quiz=r#>'{material,quiz}',practice_review=r#>'{material,practice_review}',source_note=r#>>'{material,source_note}',legal_basis=r#>'{material,legal_basis}'
from constitutional_batch p cross join lateral jsonb_array_elements(p.payload->'rows') r
where r->>'kind'='update' and m.slug=r#>>'{material,slug}' and (m.body_md is distinct from r#>>'{material,body_md}' or m.quiz is distinct from r#>'{material,quiz}' or m.practice_review is distinct from r#>'{material,practice_review}');
-- As versões anteriores permanecem arquivadas; os casos válidos são preservados na versão nova.
update public.study_material_enrichments e set status='archived'
from constitutional_batch p cross join lateral jsonb_array_elements(p.payload->'rows') r
where r->>'kind'='update' and e.material_slug=r#>>'{material,slug}' and e.status='active' and e.id<>(r#>>'{enrichment,id}')::uuid;
insert into public.study_material_enrichments (id,material_slug,version,source_body_sha256,content,sources,checked_at,status,reviewed_by,reviewed_at)
select e.id,e.material_slug,e.version,e.source_body_sha256,e.content,e.sources,e.checked_at,e.status,e.reviewed_by,e.reviewed_at from constitutional_batch p cross join lateral jsonb_array_elements(p.payload->'rows') r cross join lateral jsonb_populate_record(null::public.study_material_enrichments,r->'enrichment') e on conflict(material_slug,version) do nothing;
do $verify$
declare p jsonb; r jsonb;
begin
 select payload into p from constitutional_batch;
 for r in select value from jsonb_array_elements(p->'rows') loop
  if not exists(select 1 from public.study_materials m where m.slug=r#>>'{material,slug}' and m.content_status='active' and m.body_md=r#>>'{material,body_md}' and m.quiz=r#>'{material,quiz}' and m.practice_review=r#>'{material,practice_review}' and m.source_note=r#>>'{material,source_note}' and m.legal_basis=r#>'{material,legal_basis}') then raise exception 'Falha na conferência final do material.'; end if;
  if not exists(select 1 from public.study_material_enrichments e where e.id=(r#>>'{enrichment,id}')::uuid and e.status='active' and e.content=r#>'{enrichment,content}' and e.source_body_sha256=r#>>'{enrichment,source_body_sha256}') then raise exception 'Falha na conferência final dos casos.'; end if;
  if (select count(*) from public.study_material_enrichments where material_slug=r#>>'{material,slug}' and status='active')<>1 then raise exception 'Mais de uma versão de casos ativa.'; end if;
 end loop;
end $verify$;
select count(*) as confirmed_materials,count(*) filter(where r->>'kind'='new') as new_modules,count(*) filter(where r->>'kind'='update') as updated_modules,
 sum(jsonb_array_length(m.quiz)) as exercises_in_final_snapshots
from constitutional_batch p cross join lateral jsonb_array_elements(p.payload->'rows') r join public.study_materials m on m.slug=r#>>'{material,slug}';
commit;
